window.POEM_DB=window.POEM_DB||{};POEM_DB["song_042"]={"n":"彭汝砺","dyn":"宋","poems":[{"t":"忠孝图","f":"五言古诗","c":["君亲等乾坤，恩义俱罔极。","浮生一毫发，尽出覆载力。","我思古之人，节义有遗则。","以身托万事，糜殒终无啬。","名教落编简，不与日月蚀。","世薄道亦微，纲常堕荆棘。","想像不可追，徘徊意悽恻。","燕卿真士雄，绘素见颜色。","谋惟引深思，摩揣穷多识。","金朱宠纯懿，斧钺诛奸慝。","欲将春秋法，转徙示九域。","肥陵泮宫庭，收拾在四壁。","千年土中身，精神回翰墨。","峥嵘列星辰，奴隶生叹息。","已死疑可求，欲语嗟复默。","清风飒冰霜，直气森剑戟。","富贵喜图画，蓄聚穷千亿。","丹青彼虽工，龟鉴吾自得。","愿言同此心，论世师盛德。","当使忠孝风，自家刑邦国。"]},{"t":"宿万孝子家","f":"七言古诗","c":["昔人回车胜母里，今我枉步孝子家。","天寒日暮林谷暗，回旋道路甘泥沙。","高台隆隆起门户，松桧夹径清阴斜。","县官把烛读碑字，夜阑相视生咨嗟。","今我为诗语万氏，万事成难败之易。","尔家承承今几年，勉旃无为先世累。"]},{"t":"七门堰","f":"七言古诗","c":["古人材大心亦公，忧乐每与天下同。","谋功虑事不草草，欲与天地为无穷。","我来舒城道三堰，行看利入东南遍。","渔樵处处乐太平，稻粱岁岁收馀羡。","江淮旱涝相缀联，舒城独自为丰年。","人知今日乐其土，不知古人为尔天。","二刘未必真奇伟，谋虑及民乃如此。","俗儒文多实已亡，洋洋大论言羲皇。","心欲为功害辄胜，医庸未足平膏肓。","纷纷予亦何为者，爱古伤今空涕洒。","题诗倚立寄西风，不知材力非骚雅。"]},{"t":"金星砚行","f":"词","c":["星出云之端，石在溪之浔。","天上地下相绝几百千万里，砚中安得有星点点明如金。","既非瑕掩瑜，又似徽在琴。","我疑星之飞流运动或不居，精采误落黟流深。","不然神灵悯恻学士久濡滞，故借光景资清吟。","或有感此理，杳默难推寻。","君不见虢山之石团团有桂在中象圆月，又不见庐江之石扶疏有木相樛为寒林。","无重言，但置寒窗笔札往古研于今。","大刚无睢睢，至明无阴阴。","君也能如此，是真金星砚之知音。"]},{"t":"选仙图","f":"七言古诗","c":["自昔黄老言无为，谬说汗漫为神仙。","古人力探源未塞，今世复用根尤坚。","仙经自是物外来，画图谁向人间传。","碧油堂印始等差，洞天福地分后先。","势穷或滞酆都幽，采胜即上昆崙巅。","得失无端见掌握，胜负有势生回旋。","终朝相视何为哉，万事不齐俱偶然。","物虽无庸意甚远，为子探取题诗篇。"]},{"t":"李卿惠太平州学诗","f":"七言古诗","c":["李侯昔也治当涂，作学以遗当涂民。","谣言散落在樵牧，事迹收拾归瑶珉。","高文大字比珠玉，长与后世为奇珍。","我因李侯念往初，党庠遂序明人伦。","井田变更万事废，士林泣血悲孤秦。","今人思虑到本原，愿见风俗终还醇。","尝闻君子天下志，一视万物无疏亲。","侯来我邦嗣其兄，爱惜不后当涂人。","即视学宫动风采，复尊师席尸陶钧。","道路尚思前召父，闾阎敢忘小冯君。"]},{"t":"瓦鼓","f":"五言古诗","c":["客游南昌归，归我四瓦鼓。","浑完自甄冶，质朴排罂甒。","触之散遗声，往往中商羽。","声来殆天得，不用询有瞽。","野心爱不彻，取之置林宇。","竹梢奏清风，似喜佳物伍。","岸巾策筇杖，共尔蠲毒暑。","世浮见此拙，坐觉幽兴聚。","丹楹惜异时，蒉桴想淳古。","君年比予少，能亦珍此否。"]},{"t":"寄佛印禅师","f":"七言古诗","c":["遣奴持书问云居，我今持节行匡庐。","请服磨衲大牛车，来饭香积及雕胡。","舍施琥珀及珊瑚，沧海径寸之明珠。","师应问吾今何如，谓方据案治文书。","较量贵贱调盈虚，擒取猾吏如捕狐。","夜凉饮酒一百壶，醉视万物浑锱铢。","云居若言太粗疏，谓我寄声谢云吁。"]},{"t":"去年行建昌作诗招云居元禅师近过南康不见用前韵驰寄","f":"七言古诗","c":["雕金閒璧云中居，卧龙更有文公庐。","门前不设羊牛车，谁捋虎须跋狼胡。","宝林环绕千珊瑚，中间一点摩尼珠。","游戏乐说心如如，诸方传录为奇书。","爱师谈实非空虚，生决定信无疑狐。","表里洞彻如冰壶，轻重已自分锱铢。","咫尺祇恨相逢疏，各自有口能无吁。"]},{"t":"答赵温甫见谢茶瓯韵","f":"七言古诗","c":["我昔曾涉昌江滨，故人指我观陶钧。","庞眉老匠矜捷手，为我百转雕舆轮。","镌刓刻画走风雨，须臾万态增鲜新。","盘龙飞凤满日月，细花密叶生瑶珉。","轻浮儿女爱奇崛，舟浮辇运倾金银。","我盂不野亦不文，浑然美璞含天真。","光沉未入世人爱，德洁诚为天下珍。","朅来东江欲学古，喜听英杰参吾伦。","谨持清白与子共，敢因泥土邀仁恩。","空言见复非所欲，再拜谢子之殷勤。"]},{"t":"雪夜饮分题得雪字","f":"词","c":["颠风夜号花木折，平明阶前三尺雪。","谁家羌笛落早梅，中夜南楼对明月。","苦寒侵人毛发缩，厌厌夜饮肠内热。","公才奔放欲万里，应恨低徊受羁绁。","一巢安稳身自在，生涯却羡鸤鸠拙。","人生所值俱所乐，万事悠悠无可说。","偶有名酒须尽醉，醉辄题诗如靖节。","君不见万卒征南凯未旋，戎衣虽厚冷如铁。"]},{"t":"和深之饮字","f":"五言古诗","c":["穷阴方欲归，故故作凝凛。","乾坤几日雪，昼作宵还甚。","寒威镇氛沴，和气生丰稔。","君子有酒食，健啖亦豪饮。","齑盐本吾味，笑此已多品。","芬芳臭如兰，烂熳文似锦。","夜阑烛花低，更转鸟声噤。","私饮乐已湛，情话言尤审。","驽才负荷重，终夕无安寝。","楼头钟几声，展转屡攲枕。"]},{"t":"和亶甫夜字","f":"五言古诗","c":["雪轻不自持，风急更相借。","仙人集蓬岛，鸿鹄云中下。","飞腾障空虚，细碎穿隙罅。","光明入幽室，晃耀不知夜。","苦寒为公饮，酒尽解貂贳。","盘蔬起乡思，披绵问鹅鲊。","浮生夙何缘，今昔同官舍。","才调稍迫促，每羡公优暇。","草玄入幽微，曾不解嘲骂。","文衡委轻重，事亦宗伯亚。","我愚实未称，得友还自诧。","两骖万里心，双璧连城价。","尘土难淹留，云霄看高跨。"]},{"t":"和执中游山四诗 其一 谷隐寺","f":"五言律诗","c":["谷隐多牡丹，一花百千叶。","一根出一切，一切一根摄。","爱君看花处，立悟恒沙劫。","其谁知此意，祇有花间蝶。"]},{"t":"和执中游山四诗 其二 谷隐寺","f":"五言律诗","c":["楼阁倚天外，钟梵落人间。","俗客有时去，野僧长日闲。","白云何所往，飞鸟未能还。","一望辄一叹，令人唯厚颜。"]},{"t":"和执中游山四诗 其三 岘山","f":"五言古诗","c":["甘棠如众木，岘首如众山。","燕人爱召公，公去不忍攀。","襄阳思叔子，堕泪湿孱颜。","至今山外溪，日夜波澜翻。","如公章贡祠，亦在山水间。"]},{"t":"和执中游山四诗 其四 高阳池","f":"五言律诗","c":["三年南雍居，十至高阳池。","鱼鸟如故人，相忘不相疑。","但持青莲叶，不倒白接䍦。","我与之子游，何似山公时。"]},{"t":"内乡山中 其一","f":"五言律诗","c":["野人住山中，不见山色好。","我行久尘土，窥览慰怀抱。","禹稷不乏人，翻焉忆商皓。","使我有以食，甘于此山老。"]},{"t":"内乡山中 其二","f":"五言律诗","c":["静喧岂殊途，能静理亦好。","所以见山色，爱之置怀抱。","揽镜照须发，已如霜雪皓。","吾方与神游，未肯尘土老。"]},{"t":"寄叶法曹","f":"七言古诗","c":["参军琢玉为天性，灵台一点秋江静。","少年勤苦取富贵，不知勤苦今为病。","世人喜邪疾中正，爱君与物终无竞。","围棋坐争百局胜，雕弓力挽六钧劲。","棋子劳神弓力硬，此图养疾俱非令。","作诗劝君今勿更，诗书自足资游泳。","奥室重帘锁幽径，我不见君心怲怲。","疾病勿忧有天命，恺悌君子神所庆。"]},{"t":"送皇甫法曹","f":"五言古诗","c":["始余来肥陵，问士得皇甫。","经年在闾巷，不肯出公府。","樽俎献酬间，为之赋翘楚。","今上襄阳官，拙诗愧兼取。","襄阳真名区，碑碣字多古。","能因东南风，取以寄予否。"]},{"t":"寄友人","f":"五言古诗","c":["汉上近多雨，江头应好风。","想君当此际，挂席随孤鸿。","翔龙压大浪，画鹢凌长空。","男子四方志，生时射桑蓬。","尔来何迟迟，吾忧祇忡忡。","安得百顷田，稍邻五老峰。","早赋归去来，同为采芝翁。"]},{"t":"和君时弟见贻一首","f":"五言古诗","c":["凫短非不足，鹤长非有馀。","泰山逮毫芒，其理固一如。","君才乃骅骝，行矣无踟蹰。","万里不加鞭，日力复有舒。","岂如老钝马，寸进徒渠渠。","低头恋栈豆，时复仰天嘘。","徊徨槽枥间，不用论智愚。","惟中可以休，吾与子归欤。"]},{"t":"送范侍郎归许昌一首","f":"词","c":["凤鸟跄跄，其羽仪仪。","其集伊何，梧桐之枝。","鸿飞冥冥，其翼差差。","其止伊何，清泠之池。","朝廷于公，夫岂不知。","国有大疑，爰度爰咨。","公虽家居，如在庙堂。","国之大经，论讨靡忘。","徐徐公车，在汴之郊。","薄言追之，以永今朝。","汎汎公舟，在河之阴。","薄言维之，以慰我心。","公赐我言，我斯藏之。","何以报之，羔羊素丝，秉德不遗。","公饮我酒，我斯酬之。","何以祝之，秀发庞眉，受福无期。"]},{"t":"读史","f":"五言古诗","c":["娄敬脱挽辂，独建金城安。","韩信出羁旅，遽上将军坛。","谋出万乘惊，名飞百夫叹。","丈夫松桂姿，直气虹霓蟠。","得时树功业，未谢娄与韩。"]},{"t":"管仲有老母","f":"五言律诗","c":["王阳为孝子，王尊未能非。","管仲有老母，鲍叔独能知。","同途不同行，亦各有所思。","今或有斯人，执鞭吾不辞。"]},{"t":"暴雨","f":"七言古诗","c":["云如惊澜如泼墨，万窍怒号四山黑。","电母摇睛嚇风伯，疾雷怒张坤轴侧。","雨如河倾如雨石，上山下山泉动脉。","石漂木拔崖裂坼，高原立脚成大泽。","古寺颠前后冈逼，瓦腐椽折破无壁。","泥佛露头水浸臆，苔钱藤蔓生金碧。","背堂众流如箭激，挟气急欲投閒隙。","衣掣脚芒看沟淢，有恻烝徒老荆棘。","荷戈与殳甲不释，中夕愁居昼艰食。","我今乃敢求安席，闾阎人家水没极。","壮夫浮泅老者溺，高占鸟巢据猿杙。","可怜欲走无羽翮，我起熟视惟叹息。","断檗栖苴在檐额，鸡飞犬跳上屋脊。","蛟鼋睥睨迷所宅，乾坤欲晴但顷刻。","广庭泥深犹数尺，大浪如银沸阡陌。","万马相踶毂相击，穷民欲炊无釜鬲。","蚯蚓在堂鱼在阈，儿童捕鱼不知戚。","溪南不能过溪北，跬步如越与胡隔。","溺者漫不见踪迹，东村西村哭声塞。","手援不能泪沾臆，掩胔虽欲终何益。","天理吁嗟杳难测，茕独无辜不爱惜。","葬填溪鱼瘗砂砾，乃能屈折容盗贼。","凿险开深听藏匿，不以血膋膏锋镝。","皇天无情祸福直，昔也昭昭今也惑。","我歌且谣写悲恻，竹林一夜生秋色。"]},{"t":"和执中游山","f":"五言古诗","c":["峨峨楚山前，屹屹樊堞后。","汗漫清汉左，蜿蜒大堤右。","雷霆沸波澜，龙虎卧冈阜。","春风无偏陂，润泽到藜莠。","日月有底急，匆匆似奔走。","乐哉城南游，矧复得智叟。","横踰路东头，纵踏山北口。","逶迤陟嵚崟，莽苍度林薮。","巍亭立青冥，隐几见十部。","崖石险欲落，参差露妍丑。","沉深开殿阁，阙穴得圈臼。","尚或埋泥涂，谁能斩薪槱。","法海惟我汎，禅关与君叩。","清泉给醍醐，一饮失尘垢。","丹凤杳不来，瞻想更搔首。","潭潭谷中寺，花木照堂坳。","楼阁守岧峣，敧危贴星斗。","白云杂香雾，终日在户牖。","有沼旱不枯，金莲岂凡偶。","不见白马至，似闻苍龙吼。","一雨作丰年，欢愉逮鸡狗。","税车高阳池，遗事问黄耇。","叹息当世士，所怀自非苟。","方醉白接䍦，宁贵朱组绶。","拭目堕泪碑，徘徊想忠厚。","河内借寇恂，南阳祠杜母。","彼惟一纯诚，名等天地久。","爱君所志远，尧舜望高后。","谈经破小辩，独自持纲纽。","德爱在章贡，甘棠不枯朽。","邅回久荆楚，白发嗟未偶。","轩昂更自拔，怵惕非人咎。","宁甘冻饥死，不一变厥守。","吾惟人间世，所遇皆所授。","生死等梦幻，可能憬然否。","譬犹二人奕，日夜竞胜负。","纷纷置黑白，毕竟一何有。","但愿山下水，尽作杯中酒。","时时与君醉，独与造化友。","忠臣不忘君，不问在畎亩。"]},{"t":"次韵尧民同年","f":"五言古诗","c":["飞雪鲙长鲸，浮蛆酦新酒。","故人不我过，绝壁频回首。","北冈无断绝，参错纷燕豆。","触目事斩新，怆怀治平旧。","龙飞第一榜，四百如兰友。","劲气沮金石，高文烂星斗。","我衰也久矣，彫落几无有。","未去真厚颜，欲归犹掣肘。","盘根发馀刃，想见敏捷手。","江河被郛郭，云雾生户牖。","顾瞻良集易，叹息幽期后。","兴到诗辄成，吾穷久钳口。"]},{"t":"答同舍游凝祥池","f":"七言古诗","c":["仙宫神灵之所宅，楼阁倚天一千尺。","先生好游犹挟册，藜苋不惭吾鼎食。","凝祥池头三月春，腰金骑狨多贵人。","天边五岳烟霞阔，海上三山雨露新。","蛱蝶能飞燕能舞，凤凰在云鸿在渚。","仙人骖鸾入云雾，寂寂不闻青鸟语。","洞天落日晚沉沉，渔舟缥缈桃源深。","红玉坐看花著子，青云行见叶成阴。","疾雷怒飞风雨急，瘦马不行归旆湿。","投閒一日须一来，岁时变化犹呼吸。"]},{"t":"栽竹","f":"七言律诗","c":["一生正能著几屐，旷达人称阮遥集。","何可一日无此君，风流我爱王参军。","夏葛冬裘吾便足，由来世间无可欲。","但栽翠竹满东林，我日对之歌且吟。"]},{"t":"送君宜之临城簿二首 其一","f":"五言古诗","c":["人之与万物，异名而同体。","贵贱何以殊，知与不知尔。","知之莫如学，学莫如修己。","汝学自有得，愿言惟不已。","不已须自到，不到由中止。","请观为田者，日夜服耒耜。","久之田自熟，其入须倍蓰。","至于耕耘废，稂莠败穈芑。","常时不用力，畬穫终无几。","予与尔知田，肆言聊及此。"]},{"t":"送君宜之临城簿二首 其二","f":"楚辞体","c":["事贤如事亲，敬长如敬兄。","读书如吃饭，近欲如近兵。","百事总欲是，一言不可轻。","汝能慎于初，更欲观厥成。","仲兮舍予南，汝今复北去。","南北牵我梦，终夕无定处。","但寄两眼泪，为君衣上露。","会知老者心，从尔无早暮。"]},{"t":"送范侍郎帅庆州得以字","f":"五言古诗","c":["池水日夜流，日行无停轨。","人生长道路，扰扰还如此。","莫辞饮我酒，酒尽君且起。","赠君双宝剑，有言惭近俚。","圣人之于物，爱视犹赤子。","顾复愁不至，不知分此尔。","谁欤较寻尺，竟未知所以。","夷外当反内，刮毛须及里。","边陲今无事，自可缓带理。","愿君宏远业，赫赫光祖祢。"]},{"t":"送颖叔帅临洮","f":"七言古诗","c":["风如疾雷雹如芋，积雪如丘壅道路，蒋侯车驰挽不住。","见说西人复啸聚，目视阴山欲飞去。","蒋侯文如江海注，一决万里无尽处。","笔落在纸成云雾，气吞云梦八九数。","力转丘山缚螭虎，终日笑言公不怒。","三军号令成樽俎，羌戎胆落汗流跗，边人乃至歌五裤。","昔誇禁中得颇牧，今见南阳称召杜。","前席宣室疑已暮，勒功燕然无可慕。","归来遍作人间雨，杕杜吾当为君赋。"]},{"t":"舟中大热夜半起坐因作是诗寄诸友","f":"五言古诗","c":["星辰与天旋，河汉入地流。","其行虽不同，昼夜不自休。","彼能致其诚，岂不至诚犹。","如何尔为士，乃不彊厥脩。","功不偿其食，不如马与牛。","金朱岂不宠，顾视祇可羞。","谁谓古之人，乃无一可忧。","何以图厥终，尚惟友之求。"]},{"t":"彦衡约饮湖亭行不及赴","f":"五言古诗","c":["主人欲留客，其意良已厚。","行人念行役，奔命惟恐后。","张帆半夜起，撇若惊蓬走。","盈盈水中莲，郁郁堤上柳。","相别不相见，已行更回首。","人生如朝露，理固无可久。","可为惟为德，万一或不朽。","行也死后已，庶犹无大咎。","君恩不胜报，聊一报我友。"]},{"t":"宋履中示月桂佳篇并圣俞诗因赋四韵","f":"七言律诗","c":["古人种花昔已老，后人种花今更好。","听诗令人饥顿饱，叹息古人不可到。","庭中花落君勿扫，醉饮全胜藉幽草。","白发不嫌花压帽，寄声我友车先膏。"]},{"t":"再用前韵书呈诸友学士","f":"七言律诗","c":["凡花朝开暮即老，仙桂春花秋更好。","幽砌终年看不饱，洞门无日春不到。","玉樽一挹把笔扫，跂脚诗成不立草。","醉倒淋漓应落帽，衣襟沾湿云如膏。"]},{"t":"察院学士灸焫连日戏作鄙句","f":"七言古诗","c":["截艾作炷大如椽，三日彻夜烧丹田。","心腹生火口生烟，皮毛润泽骨骼坚。","舍杖趋走脚轻儇，赫如渥丹颜色鲜。","五十六岁如少年，顾我一生百迍邅。","病多未老先华颠，欲灸自量无罪愆。","一切久矣付诸缘，三月人家花欲燃。","阳春水色碧于天，更欲载公青翰船。","唤取佳人舞绣筵，一饮一斗醉不眠。","不怕世人笑逃禅，火中自会生金莲。","作诗问公奚若旃，肌肉忍自投戈鋋。","亶顾厥后勤著鞭，万事悉置心超然。","服食不须求汞铅，公名已自列诸仙。"]},{"t":"再用前韵呈察院学士","f":"七言古诗","c":["真人养真如养源，道士耕道如耕田。","吐纳日月踏云烟，牢如金石齿牙坚。","捷如猿猱身体儇，沐浴露雾甚荣鲜。","受命一万有千年，既安且乐无回邅。","后人好恶纷倒颠，湎淫蛊惑作罪愆。","堕落世网缚尘缘，爱河流转业火燃。","猗公淡泊其得天，泛泛乘世如虚船。","精神采色照四筵，老鹤饮露夜不眠。","戏笑中有第三禅，净不著水花如莲。","酬酢不停奚敏旃，赋诗马上横殳鋋。","不放祖生先着鞭，北方灸焫自古然。","其力十百倍凡铅，功成不数饮中仙。"]},{"t":"是非寄君时","f":"五言古诗","c":["一或以为是，一或以为非。","是非如环中，毕竟无穷时。","汝唱我其从，嗟吾亦何为。"]},{"t":"自然","f":"五言古诗","c":["皇天典下民，实亦付自然。","祸福与是非，日夜相推迁。","譬犹泥在钧，随分有丑妍。","丑非其所恶，妍非其所怜。","彼怜吾不知，方知乐其天。"]},{"t":"行西城","f":"五言古诗","c":["我将行西城，曲指计日月。","汝来今几时，已卜钱塘别。","吾衰况多病，冉冉鬓已雪。","安能久去汝，漫自投羁绁。","田园苟可饭，声利非吾屑。","与汝归去来，相看至耆耋。","苍茫尚无涘，空复愁如结。"]},{"t":"汉上谒刘执中","f":"五言古诗","c":["尘土能污人，有如衣匪浣。","驱车出闉阇，纵目尽江汉。","渔舟泛青云，潇洒雁为伴。","芦花如飞雪，时逐风散漫。","可怜独清人，憔悴行泽畔。"]},{"t":"答君时用前韵","f":"五言古诗","c":["振衣近沧浪，聊以垢腻浣。","仰首冥冥雁，肃肃在云汉。","吾今寡所合，尔独为吾伴。","荡舟泛江海，四顾畏汗漫。","君看水中坻，不是无边畔。"]},{"t":"口占和君时","f":"五言古诗","c":["吾生有穷通，吾志不可衰。","飘飘如浮云，富贵我何为。","我今乐不浅，我歌尔其随。","譬犹富者家，畜聚不可訾。","怡怡任天真，何害为偲偲。","人惟学不学，高下成云泥。","是非惟所求，万物岂我私。","君看鉴中明，不隐嫫母媸。","君病本自无，吾药奚所施。","惟作日新铭，与汝同为规。"]},{"t":"菊苗 其一","f":"五言律诗","c":["重阳黄菊花，零落殆无有。","微阳动渊泉，嫩叶出枯朽。","青青好颜色，寂寥霜雪后。","物理如转环，开花岂其久。"]},{"t":"菊苗 其二","f":"五言律诗","c":["物理如转环，昔亡乃今有。","眷言篱边菊，根叶未终朽。","盛衰各一时，何足竞先后。","彼花似无情，能并天地久。"]},{"t":"采葵","f":"五言律诗","c":["古人采薇蕨，我亦爱斯葵。","能随朝阳倾，不为秋露萎。","烹调戒中厨，聊以燕母慈。","拔根取廉名，未愧鲁公仪。"]},{"t":"荠","f":"五言律诗","c":["阴风号暮景，零落悲晚秋。","纷纷彼芳荠，郁郁此中丘。","作甘岂不珍，冒寒不为柔。","薄言撷以归，呼奴具晨羞。"]},{"t":"途中和君时 其一","f":"五言律诗","c":["相望不相见，一步一回头。","况汝将有适，前路正悠悠。","土壤去宛叶，星躔近斗牛。","不知明之日，何以解吾忧。"]},{"t":"途中和君时 其二","f":"五言律诗","c":["闻君欲脂车，辗转睡不安。","忧心顽如石，百计不可宽。","鸤鸠祇在桑，归雁乃云端。","一瞻百叹息，强饮终无欢。"]},{"t":"行役","f":"五言律诗","c":["行行重行行，吾役几时休。","春风不相饶，尘土满敝裘。","人生能几何，乃有千岁忧。","须知一樽酒，可胜万户侯。"]},{"t":"南阳","f":"五言律诗","c":["复尔行南阳，兴言涉清汉。","日晴川谷明，风靡花竹乱。","遥瞻万山麓，近眺樊城岸。","南北有仳离，令人感鸿雁。"]},{"t":"途中","f":"五言律诗","c":["一日复一日，悠悠竟何之。","万物但此理，百年能几时。","墨翟悲已误，贾生哭奚为。","可怜日月轮，日夜争东西。"]},{"t":"早起","f":"五言律诗","c":["客心不能休，未晓辄欲起。","耳冻南山风，衣冰北溪水。","舍我一息劳，先行十馀里。","因知人之学，患不勉旃尔。"]},{"t":"昨日饯赵教授行会饮秀楚堂晚徙樱桃花下夜月上正夫设烛于花上光明焜耀昔所未见正夫因约赋诗","f":"七言古诗","c":["夜凉月色清如水，天静无风尘不起。","移酒近花坐明月，画烛横斜插花里。","月寒烛艳花淡薄，意思相疑不相似。","一下一高总能见，半白半红浑可喜。","时有幽香闇着人，更分疏影低临水。","密如云雾即成阴，团作珠玑看结子。","异时尚拟与君醉，景物更作今日比。","富贵功名是底物，人生百年行乐耳。"]},{"t":"再用前韵 其一","f":"七言古诗","c":["朝日薰酣晨露洗，中林入夜幽香起。","烛与花明月影中，月和烛照花阴里。","光华混杂不可认，刻画虽工难比似。","烛偏月下花亦别，疏影横从俱可喜。","使君白头衰久矣，空惜流年去如水。","作诗与花雪羞耻，多材自属佳公子。","青春九十今能几，不当祇作常时比。","莫令俗事一关心，可厌浩歌频到耳。"]},{"t":"再用前韵 其二","f":"七言古诗","c":["夜色清如水新洗，月上烛明栖鸟起。","灼灼其华散成绮，仙翁岸帻光明里。","公明如月非如烛，文华亦非花得似。","安危自以天下任，故与众人同笑喜。","手折芳枝嚼红蕊，临池想濯沧浪水。","芳菲肯付游人醉，知公爱民一如子。","月盈易亏花落易，直须催促公排比。","公看光阴去无止，欻如白驹过隙耳。"]},{"t":"次正夫登沛中歌风台","f":"五言古诗","c":["屹屹泗上城，隆隆沛中台。","登台不见人，祇见山崔嵬。","高祖汤武资，神明天所开。","潜龙已飞跃，乘马宁邅回。","倒戈与天旋，万国俱子来。","西楚殪封兕，东齐荡纤埃。","任使虽故人，萧曹亦贤哉。","功成思猛士，乐极自成哀。","如何古之人，懿德乃所怀。"]},{"t":"次正夫相寄佳句","f":"五言古诗","c":["朱橘大可围，白鱼阔盈尺。","掀林撷甘芳，舣岸披的皪。","我酒清且旨，于焉饯佳客。","鸿飞不知远，日暮寒云碧。","回澜祇如昨，不见舟行迹。","寄诗何遒丽，若见好颜色。","遥想翰墨挥，波涛泻胸臆。","维纚远林外，坐看晨风翼。","万物归一致，知公无不适。","人之与天地，同是为形役。"]},{"t":"次正夫宿留侯庙韵","f":"五言古诗","c":["龙飞景云从，林茂众鸟息。","真人翔灞上，多士生王国。","留侯豪杰士，乃独为所得。","韩亡竟不去，汉兴愈厉策。","不见马上功，奚多幕中画。","眇焉视婴布，若数百与亿。","鸿鹄已高飞，翩然敛归翼。","堂堂高皇业，屹立如磐石。","始卒如公者，是不惭庙食。","载瞻水边祠，老桧寒更碧。"]},{"t":"次正夫途中怀亲韵","f":"五言古诗","c":["动静非两途，久劳逸更好。","开门看白云，婉婉出山峤。","身闲亦已乐，言念亲及耄。","岂无青精饭，每食终不饱。","镜中发如漆，一夜成素葆。","言归采其兰，堂北种萱草。","日以五鼎食，不如綵衣老。","我今无此乐，感泣形已槁。","日夜思故乡，攲眠梦郊堡。"]},{"t":"次正夫途中蔬食韵","f":"五言古诗","c":["昔未与公游，同志不同居。","我宠居凤掖，公名专石渠。","醪醴赐上尊，膏膻给天厨。","彭城作逐客，事事秦越殊。","尚惭素餐诗，苦畏城旦书。","岂能万钱食，谬驾双轮车。","时时置杯盘，登眺随所如。","公行适在野，乃至歌无鱼。","人生一世间，百年实斯须。","无所不可安，何独贵纡朱。","饮河惟满腹，奚欠亦奚馀。","作诗促公归，去直承明庐。"]},{"t":"正夫卧疾予往访之正夫置酒因作是诗","f":"五言古诗","c":["来问清漳病，烦置东武酒。","敬窥石窌君，爱始士衡母。","大论窥道奥，禅关恣深叩。","是非弃糠秕，直与造化友。","人游于一世，万事俱非偶。","养疾先息念，息念他何有。","此言乃良药，不在砭石后。","长日从公游，径醉须五斗。"]},{"t":"再用前韵","f":"五言古诗","c":["从公饮辄醉，醉德非醉酒。","噬肯易子教，义应容拜母。","歌声清以长，发若金石叩。","予非多闻者，或似直谅友。","身世飘流并，神形条达偶。","万事实一梦，奚亡亦奚有。","是非可姑置，试俟千载后。","但愿酒不空，何庸印如斗。"]},{"t":"和君时","f":"词","c":["猗彼君子，笃志乎道。","道之云远，于焉慥慥。","猗彼君子，克诚其身。","匪禄是荣，日以养亲。","孰违孰从，曰吾从义。","孰去孰与，曰吾由礼。","温凊匪偕，云如之何。","得彼失兹，得失孰多。","吾斯未信，吾颜之厚。","重轻惟法，于尔何有。","尔旋尔车，不知其期。","我陟其冈，祇益我思。","凡人逐物，其力则倍。","苟知其养，是用无悔。","无悔无尤，是则养亲。","尔慎旃哉，以慰母心。","为山一篑，惧乎或止。","道之云远，曷云其已。","我田我田，以迟尔归。","何速于行，姑乐我私。"]},{"t":"寄君时","f":"楚辞体","c":["我脂我车，陟彼高冈。","母也吾怀，匪居或忘。","我帆我舟，汎彼大江。","母也吾忧，匪食或皇。","我池有鱼，亦可以羹。","何必鲔及鲂，叔兮其归哉。","我田有菽，苟可以食。","何必稻与粱，叔兮其归哉。"]},{"t":"寄君时","f":"楚辞体","c":["我思古人，克诚其心。","如陟于高，如临于深。","我处于中，而舍其偏。","我弃其零，而取其全。","勿谓道远，我至之难。","我勇以前，人孰我先。","勿谓过小，我姑为之。","千里之差，始于毫釐。","勇兮勇兮，子我所器。","子诚不已，我今所畏。","子能吾取，吾谁之匿。","子铭于盘，以视朝夕。"]},{"t":"寄君时","f":"楚辞体","c":["我灌我园，有采之心。","于以撷之，既有且多。","我游我庭，有菊之苗。","于以芼之，既旨且时。","我思昔人，亦采其薇。","我乐所安，奚愠其微。","仲兮仲兮，曷日汝偕。","以事以游，以慰予怀。"]},{"t":"元祐元年十二月庚子雪夏首莼湖结冰鹡鸰群集于上者至不可数感而作是诗也","f":"楚辞体","c":["宛彼鹡鸰，其乐孔群。","彼类维何，而有若于仁兮。","宛彼鹡鸰，爰集于冰。","彼至维何，而有冽其清兮。","宛彼鹡鸰，既飞且鸣。","彼行维何，而有笃其诚兮。"]},{"t":"寄宁和仲","f":"词","c":["凤山之泉，孔洁且长。","止而不流，是不如污潢。","凤山之木，可栋大厦。","舍而残之，是将与荆棘而并化。"]},{"t":"送张子固","f":"七言律诗","c":["吾少饮酒不知数，有如长虹吞百川。","老来畏酒饮辄醉，百事一无如少年。","瘦脚踉跄走病鹤，吟肠悲壮啼寒蝉。","夫君尚勇不宜怯，急上青云须着鞭。"]},{"t":"吴园杂咏十九首 其一 吴园","f":"五言古诗","c":["布夷韩彭诛，国夺名亦陨。","芮王独以正，百世荣如近。","至今园中草，欲践犹不忍。"]},{"t":"吴园杂咏十九首 其二 燕阁","f":"五言古诗","c":["高阁高入云，俛焉视冈阜。","老来更无事，宾至但饮酒。","阴功在其乡，更足燕尔后。"]},{"t":"吴园杂咏十九首 其三 书堂","f":"五言古诗","c":["藐视一籯金，独藏五车书。","高堂见古今，其乐亦只且。","以此燕子孙，吾谁数陶朱。"]},{"t":"吴园杂咏十九首 其四 集虚堂","f":"五言古诗","c":["室虚即生白，惟道在集虚。","诗书扫尘迹，仁义外蘧庐。","形忘心亦忘，万物同一如。"]},{"t":"吴园杂咏十九首 其五 觉轩","f":"五言古诗","c":["本觉不见觉，大梦非是梦。","觉梦梦非觉，其归理则共。","兔鱼亦既得，筌蹄自无用。"]},{"t":"吴园杂咏十九首 其六 山亭","f":"五言古诗","c":["飞檐截山出，碧瓦贴云齐。","水静见鱼乐，竹深闻鸟啼。","春风花落处，误认武陵溪。"]},{"t":"吴园杂咏十九首 其七 观德亭","f":"五言古诗","c":["男儿厥生时，弧矢射四方。","兹礼古所重，叹嗟今已亡。","典章可披寻，君试行一乡。"]},{"t":"吴园杂咏十九首 其八 思贤亭","f":"五言古诗","c":["大风无邪声，积雪不改色。","根方为龙去，实拟待凤食。","一日有不见，恍如岁三易。"]},{"t":"吴园杂咏十九首 其九 紫筠亭","f":"五言古诗","c":["青竹老出蓝，紫竹嫩施粉。","乐彼奇节并，岁寒不彫陨。","言如拾芥者，设意毋乃近。"]},{"t":"吴园杂咏十九首 其十 澡雪亭","f":"五言古诗","c":["尘土能污人，譬如衣匪浣。","窥临得清旷，其去已大半。","不必濯沧浪，神明自还观。"]},{"t":"吴园杂咏十九首 其十一 四并台","f":"五言古诗","c":["时将景共好，物与心相投。","旷览尽万物，分明一浮沤。","此台无不并，乐只台上游。"]},{"t":"吴园杂咏十九首 其十二 四曲池","f":"五言古诗","c":["大池方如矩，小池曲如钩。","方奚避污辱，曲不趋公侯。","时傍白莲叶，独行青翰舟。"]},{"t":"吴园杂咏十九首 其十三 眉寿堂","f":"五言古诗","c":["枝干上参天，长松不枯槁。","朱顶雪衣裳，仙鹤颜色好。","主人一千岁，似此松鹤老。"]},{"t":"吴园杂咏十九首 其十四 忘忧亭","f":"五言古诗","c":["徙竹种前林，栽松满幽岛。","主人无所忧，不用植萱草。","吐纳奚所事，忘忧自难老。"]},{"t":"吴园杂咏十九首 其十五 秋月楼","f":"五言古诗","c":["秋月如秋水，瑩澈万里流。","我欲挹其清，登彼百尺楼。","随时有佳趣，不但是中秋。"]},{"t":"吴园杂咏十九首 其十六 观稼亭","f":"五言古诗","c":["多稼为丰年，观言亦云乐。","秋云满原隰，漫不知厚薄。","帝力彼焉知，陶然饱耕穫。"]},{"t":"吴园杂咏十九首 其十七 戒得庵","f":"五言古诗","c":["众人贪徇财，种利不种德。","谁如之人心，白首能戒得。","以此风里闾，贪竞当自息。"]},{"t":"吴园杂咏十九首 其十八 秋香亭","f":"五言古诗","c":["岂不有春华，不如秋后香。","红紫不禁风，黄花耐雪霜。","几时登其亭，采采泛彼觞。"]},{"t":"吴园杂咏十九首 其十九 薰风阁","f":"五言古诗","c":["众山走蜿蜒，高阁立崔嵬。","流水横其前，时有薰风来。","聊可解吾愠，敢言阜民财。"]},{"t":"晨起祠先农道中","f":"五言古诗","c":["更阑烛花低，呼童起视夜。","问夜如何其，露落月未谢。","皇帝共神明，朝燕或为罢。","多仪礼有敬，少怠刑无赦。","今兹先农飨，上意在耕稼。","驾言投明起，不敢私安暇。","马蹄踏冰雪，雾露湿鞍马。","寒林月中影，十里开图画。","灯火望坛场，冠裳出次舍。","锵洋响金石，馨香纷彝斝。","百年礼乐中，万事无杂霸。","昏冥久尘土，今日闻韶夏。","心知至诚通，自可膏泽下。","清风吹菽麦，绿阴密桑柘。","人家实仓廪，得以时婚嫁。","四夷共安富，兵偃祭类祃。","山川百神宁，天子乐无假。","敢后秋冬报，还见击鼓御。","顾予真缺然，何以补漏罅。","尚堪逐农樵，击壤歌圣化。"]},{"t":"自吉泛舟入赣","f":"五言古诗","c":["我行欲从车，好风苦相招。","谓言困行役，厌此道路遥。","骎骎四骆马，终日在岧峣。","簿书更追随，精耗发欲焦。","乃复汎柏舟，锦幔兰为桡。","是时春始和，暖风秀兰苕。","彼柳已青青，彼桃已夭夭。","王事敢不修，我行歌且谣。","彼不知之者，谓我士也骄。","不知非所知，我兹以逍遥。"]},{"t":"胡雏","f":"词","c":["秃鬓胡雏色如玉，颊拳突起深其目。","鼻头穹隆脚心曲，被裘骑马追鸿鹄。","出入林莽乘山谷，凌空绝险如平陆。","臂鹰緤犬纷驰逐，雕弓羽箭黄金镞。","争血雉兔羞麋鹿，诡遇得禽非我欲。","莫怪小儿敏捷强，老宿胡人以此为风俗。"]},{"t":"六月自西城归","f":"五言古诗","c":["驾言将西征，呼仆问行李。","吾行无所苟，虽远亲则喜。","痴儿不知事，饮血泪如水。","忆昨唐许边，逋逃聚蜂蚁。","巅崖寄巢穴，绝险不可迩。","扑灭无先几，捕督误诏旨。","是时寡妻病，吾计或可止。","君曰无妾私，促装勉行矣。","妾病虽云危，姑慈有足恃。","是身如浮云，永诀或此始。","一马才登途，渠魁头挂市。","犹虞未宁归，走讣忽在耳。","羁栖二十年，粱肉饱有几。","单车行四方，岁月几万里。","私居乃如寄，方此还之彼。","爱君能知分，嗜苦同甘旨。","誓欲相厥成，完百无一毁。","中流即我弃，我恨无涯涘。","家贫未能去，顾惜尚壮齿。","含愁复于行，嗜禄祇自鄙。","悠悠涉清汉，欲往辕更柅。","沧浪照颜面，不与旧相似。","蓬鬓生雪霜，龟胸点泥滓。","骄阳恰中伏，旱魃方哆侈。","山川惜阴雨，我稼病未起。","高堂蔽重帘，捉扇衣屡褫。","乃兹趋长途，登降遍峛崺。","简书况有限，暮晚未担弛。","山名初外朝，岌嶪超众岿。","晴天出万象，扰扰谁经记。","滥觞一拳多，结构五丸累。","蛟龙跨鸿濛，殿阁耸碨礧。","或植如剑戟，或覆如釜锜。","或视而错愕，或行而迤逦。","或大而无当，或立而不倚。","干平七峰老，秀拔匪众比。","耆旧今所贵，瞻言但擎跽。","马息联八叠，培塿看冈屺。","篮舆劳攀牵，卒饿弗克仔。","肺声几成雷，背汗欲濡轨。","吾疲尚能徒，走骤托杖履。","岂不有林木，日昼方如燬。","晓行怯雾露，夜涉愁蛇虺。","屋颓茇穷阎，鱼馁饭乾米。","田功微粱稻，圃学蕃麻枲。","截筒户割漆，剥楮人抄纸。","千枫立青冥，万竹秀披靡。","时时得流泉，濯溉移日晷。","清音有可乐，往往中宫徵。","孰谓彼房陵，千家住清泚。","神仙隐九室，绰约如处子。","安眠费春秋，官爵弃敝屣。","宝公浮杯来，宴坐有旧址。","甘雨随众缘，凶年作蕃祉。","欲游嗟不遑，怅望祇悬企。","东西更多山，小大或亿秭。","未经夏禹凿，想待愚公徙。","横梯险相联，曲栈危半阺。","避就为俛眉，循缘或颠趾。","女娲高第一，仅去天尺咫。","黎明登其颠，星宿可俯视。","扶桑出晓日，洞彻及表里。","丘陵杂茧栗，草木浮糠秕。","补天闻故老，岂或有此理。","天之于空虚，一大器而已。","物或有不完，补之非天耻。","酒觞荐明诚，感叹至横涕。","留停仰妫墟，欲至更逶迤。","烟岚相薰蒸，闇黯常及巳。","杂民久薰陶，顽吏傲鞭箠。","令人愧满面，虞舜昔居此。","商洛不十舍，惄焉想黄绮。","奔驰浪南北，僶俛惭禄仕。","纷纷昨夜梦，慈母倚门俟。","愿骑双鸿鹄，更挟四騄駬。","言乘溪上舟，出宿城边址。","峰峦欲飞去，峭拔陵天委。","神奇杂鬼怪，巧绝非劂剞。","龙盘秦世松，玉滴尧时髓。","波澜杂云雾，莽苍在隐几。","平生贪幽胜，短桨行复舣。","一滩复一碛，却望无首尾。","崭崭边傍石，出没竞谲诡。","细垂一丝缕，大作十虎兕。","冲撞非雷霆，震荡岸欲圮。","鼋鼍不能游，蛟蜃得所恀。","悬流落千仞，急疾过发矢。","浮生真如叶，转足见生死。","篙工相号呼，熟视但如砥。","谓予且从陆，厥计亦非是。","吾生自有分，纤悉不在己。","缅思濠上鱼，载顾山梁雉。","未能脱缰锁，可恨讥炉锤。","孔卧弗煖席，禹行尚乘櫑。","所惭一无补，虚冒恩私被。","夜凉泛明月，不寐对潇洒。","凤林莽何处，草木秀嶷嶷。","槎头缩项鳊，不减河鲂美。","习池今可游，尊酒慰劳只。","鸿雁杳未来，将诗寄双鲤。"]},{"t":"寄君时","f":"楚辞体","c":["岂不有性灵，稍可学操缦。","公私足忧责，耗蠹几大半。","驰驱寝食废，真自残躯干。","叔兮识至理，真伪不可乱。","读书老不辍，夜坐频达旦。","特立无倚著，刚严实予惮。","岁时有多少，每复愁分散。","顾瞻鹡鸰飞，俛仰发浩叹。","安得桑麻田，谷粟粗可饭。","晨昏侍萱堂，綵服何粲粲。","箴切庶寡尤，诗书恣娱玩。","相从不相离，如彼鸿与雁。"]},{"t":"观画","f":"七言古诗","c":["少时驰驱走四方，马足遍踏无边疆。","北踰崦嵫薄扶桑，远陟羊肠上太行。","历参涉昴扪亢房，荡舟溟渤浮河潢。","五湖彭蠡窥沅湘，蛟龙出没鳞鬣苍。","大浪震叠钟鼓撞，怒蜃结搆珠瑶光。","游鱼鲦鲿鳣鲔鲂，鸂鶒沉浮旅鴐鸧。","大鹏一飞凌鹔鹴，中林荃蕙杂兰菖。","妖红曼绿艳靓妆，回溪曲覆秀筼筜。","老松怪柏号风霜，桂丹枫赤橘柚黄。","阆风仙人醉琼浆，前旆虹蜺骑凤皇。","云台曲璧络奇璜，缥缈天乐非宫商。","我欲从之匪暇遑，昨朝图画纷开张。","睥睨旧游心惚慌，南岭赤日西玄霜。","愁云不开雨雪雱，变化倏忽无经常。","隆楼杰阁郁相望，远峰截嵲插雕梁。","商人骑马儿牧羊，牛车鱼艇浮纤芒。","苍鹅无声浴沧浪，熟视却顾疑腾骧。","骅骝奚为弃路傍，骨骼虽老终轩昂。","重阳篱菊开煌煌，怪见桃杏争芬芳。","梅花一枝忽自折，半篱彷佛闻幽香。","文陛网户绿绮窗，中有美人岂媖媓。","流珠蛱蝶金鸳鸯，一盼少年犹断肠。","蓬莱宫中日月长，世界凡阅几炎凉。","悠悠彼乐未遽央，棋局未知谁子强。","庞眉老僧坐道场，手捉拂子据绳床。","似达至理言虑亡，惟我知彼真荒唐。","乃知画工匪其良，倒置高下玩阴阳。","鬼神丑怪不能藏，咫尺千里无准量。","屈折海岱留缣缃，物象涕泣愁斧戕。","贵家欲得心奔忙，背锦轴玉红绨囊。","君亦爱之未能忘，苟不溺心奚所妨。","我今与公陟高冈，坐视四海超八荒。","图史罗列耀文章，前有唐虞上羲皇。","左右孔孟从庄扬，朝莫见之心肃庄。","议论兴废评否臧，卑陋不肯数汉唐。","广莫之野无何乡，我与子乐奚其将。"]},{"t":"答蜀公谢寄酒","f":"五言古诗","c":["彼酒孰为之，湛然若天成。","为之非草草，纤悉中度程。","其香匹幽兰，色不减琼英。","采采白菊花，亦酌潭水清。","潭水取之源，择菊废枝茎。","我将飨明神，乃独以其精。","千里驰寄公，非将解公酲。","祝公百年寿，多益不为盈。","想公初饮时，瑩彻颜微赪。","幽吟倚岩石，缓步睨层城。","爰闻在阴鹤，载叹出谷莺。","我闻至人心，万物莫足撄。","存亡漫忧喜，泛然若无情。","此理公得之，奚藉醪醴并。"]},{"t":"方城与君时相别遇雨因寄是诗","f":"七言古诗","c":["五更赤晴平旦雨，愁云不开风劲怒。","霰雹夜落大如芋，日月不出愁乌兔。","兄曰嗟予季行役，道阻且修日云暮。","泥深一尺水交注，仆肩不任马蹄驻。","一车十牛不能御，晨征忽忽立乘遽。","恐汝悲啼不还顾，昔知为快今知误。","恨不赭阳一月住，人生百年惟所遇。","曲折万变皆归数，乾坤与人同寄寓。","扰扰眼前皆细故，慎勿动心悲景露。","九阪王阳犹叱驭，平明天晴卷云雾。","骅骝安稳行道路，一日千里如跬步。"]},{"t":"我行","f":"五言律诗","c":["我行日不休，行亦读吾书。","朝为忘机鸥，夜作不瞑鱼。","日月双跳丸，乾坤一蘧庐。","而吾于其间，扰扰亦自如。"]},{"t":"离家","f":"五言律诗","c":["离家一千里，十日不得书。","不怨天上鸿，祇恨水中鱼。","我行谷伯国，明日武侯庐。","慈亲发雪白，安否比何如。"]},{"t":"游岘首","f":"五言律诗","c":["去年冬少雪，二月春始晴。","南游岘首山，东下石头城。","揉蓝染江水，烂锦贴园英。","幽亭一杯酒，不用千载名。"]},{"t":"叔子祠堂","f":"五言律诗","c":["不折亭下柏，不采山头石。","羊公昔兹游，千载人爱惜。","焚香荐卮酒，一拜三叹息。","却汎岘水波，汪洋感馀泽。"]},{"t":"恒河","f":"七言律诗","c":["恒河世界浮沤上，漭漭众生久流浪。","老蚕作茧自纠缠，枯木生虫不相放。","止止灵泉风震荡，昭昭惠日云遮障。","却语诸人莫惆怅，烦恼菩提同一相。"]},{"t":"舟行","f":"词","c":["莫打桨，打桨惊鸿雁，鸿雁不慕鱼虾贱。","暮宿江湖昼云汉，我不见之其心乱。","莫鸣桹，鸣桹鸿雁飞。","鸿雁不是鸡鹜儿，我不见之心孔悲。"]},{"t":"送君时","f":"七言古诗","c":["思亲一日如三岁，去家十舍如万里。","投明叔也欲别我，枕上闻鸡泪如洗。","丈夫盖棺事则已，君虽白发犹壮齿。","奚惭折腰五斗米，三釜及亲胡不喜。","弧桑蓬矢射四方，男子生来志如此。"]},{"t":"高阳池","f":"五言律诗","c":["驾言之石城，爰至高阳池。","是时春始和，池水生渺瀰。","徒能踌躇顾，不及酩酊归。","令人忆山翁，倒著白接䍦。"]},{"t":"谷隐寺","f":"五言律诗","c":["楼台寄山巅，屹屹与云齐。","登临览昭旷，感慨发悲悽。","西顾隆中庐，北睨汉阴畦。","愿言脱樊笼，超然此幽栖。"]},{"t":"白马寺","f":"五言律诗","c":["老龙挟神机，变化无拘挛。","大作四海水，敛为一泓泉。","白露泛素液，黄金折嘉莲。","乐哉襄阳人，岁岁无凶年。"]},{"t":"春风破穷阴","f":"五言律诗","c":["春风破穷阴，草木争秀发。","纷敷作锦绣，晃耀映霜雪。","我行纵披赏，欲戴羞白发。","相看一杯酒，聊以酬佳节。"]},{"t":"寄十二十四弟","f":"七言律诗","c":["有弟有弟各一隅，万里不见徒嗟吁。","江湖春色又归矣，庭槛花枝还有无。","欲寄我声无鲤鱼，欲写我恨无酒壶。","开编一见鹡鸰诗，潸然泪落如真珠。"]},{"t":"秋风","f":"七言律诗","c":["晚来雨霁秋风颠，惊我枕上清昼眠。","四林荒凉好景气，万里晻霭皆云烟。","乳鸠深藏叫苦竹，苍鹘欻起摩青天。","花枝柳叶便凋陨，山上松筠径俨然。"]},{"t":"武冈路中","f":"五言律诗","c":["朝行黄茅冈，暮宿黄茅驿。","一冈复一冈，冈冈如络绎。","一驿复一驿，思亲头易白。","何时自此还，行李兼晨夕。"]},{"t":"城东行事去李简夫甚迩可以卜见而俱有往返之禁因戏为歌驰寄","f":"词","c":["故人咫尺水东头，我欲见之心悠悠。","有足欲往不自由，形骸静对莺花留。","我思肥陵昔之游，云雾密锁城上楼。","把酒待月生海陬，月到行午醉未休。","濡须南池水中洲，脱帽散发寻渔舟。","夕阳扶栏持钓钩，白蘋风起寒飕飗。","别来纷纷几春秋，彼此待尽栖林丘。","滴泪落水东争流，肺肝虽大不容忧。","残息乃复如悬疣，得官相望真如囚。","李夫子，借使复得把酒与子饮，其乐还如昔时不。","我今鬓发已丝志已偷，力不能前钝如牛。","泡浪亦悟吾生浮，尚壮欲以华簪投。","日月逐逐同传邮，何用自与身为矛。","我歌草草子须酬，欲读子歌销我愁。"]},{"t":"舟过当涂","f":"五言古诗","c":["悠悠章江柁，复自姑孰北。","此身与此水，日夜俱无息。","关关林中鸟，软语如相识。","杨柳枝叶长，青青祇如昔。","惟予鬓间发，种种添新白。","开尊泛溪水，宛转随山色。","四方本予志，夷险非我恻。","挂帆出长江，万里追鹏翼。"]},{"t":"阻风饮酒","f":"五言古诗","c":["系舟不能前，酌酒聊自慰。","异乡少亲友，市远无兼味。","惟兹佳山水，浑浑含正气。","旁皇无宾主，恣取不为费。","王事不为缓，简书实吾畏。","夜晴如何其，呼吏看星纬。"]},{"t":"癸未季秋偕子仲都官文渊节推子坚先辈同游东湖分题得东字","f":"五言律诗","c":["高山据西南，湖水自南东。","中有避汉人，如彼云中鸿。","一日克诸己，百世闻其风。","乐哉今日游，况有贤者同。"]},{"t":"和广汉见和东字 其一","f":"五言律诗","c":["驾言欲何之，于彼湖水东。","茫洋众游鱼，凌厉一归鸿。","嚼蕊挹飞泉，解带临清风。","寄声诗中伯，暇日倘来同。"]},{"t":"和广汉见和东字 其二","f":"五言律诗","c":["出处势不齐，譬若西与东。","在阴有鸣鹤，渐陆见飞鸿。","禹稷颜回道，下惠伯夷风。","故彼孺子者，亦庶与古同。"]},{"t":"与宁节推游聘君亭邂逅广汉同游分题得聘字","f":"五言古诗","c":["汉衰至桓灵，王室既不竞。","豪杰死党锢，奸嬖偷权柄。","娟娟彼孺子，德誉南州盛。","耕稼以自食，羞诣安车聘。","彼非硁硁者，而欲为奇行。","未能比禹稷，夫岂惭蘧宁。","我登斯亭上，悠悠发幽兴。","高山知仰止，池水不可泳。","鱼戏芙蓉花，凫杂参差荇。","嗟叹之不足，俛仰成讽咏。"]},{"t":"送宁秀才过溪口占","f":"五言古诗","c":["邂逅吾所乐，爰复惜分携。","系帆且少留，聊慰吾所思。","嗟我行老矣，志意非昔时。","鬓毛黑如漆，种种今如丝。","譬如七年牛，力乏气亦衰。","嗫嚅食青刍，欲往脚自迟。","爱子齿未壮，骨骼超等夷。","轩昂宇宙间，万里惟所之。","举足我即到，宁复论华夷。","行矣尚勉旃，卒慰吾所期。"]},{"t":"沐浴有感","f":"五言律诗","c":["去垢如去邪，不欲留毫分。","发不止一沐，身不止三薰。","如何迷本原，浴德不自勤。","区区养樲棘，俯仰愧前闻。"]},{"t":"答张天觉学士","f":"七言律诗","c":["庞蕴襄阳老精怪，辛勤欲挟山超海。","破除枉被马师瞒，扶起赖存灵照在。","最上一机终不传，喃喃谩自费罗干。","晚年遭值张居士，冷火寒灰更炽然。"]},{"t":"内乡先春","f":"五言古诗","c":["古寺前无廊，空林中有亭。","淅水为襟带，萧山作画屏。","仰高听流水，志体得所宁。","不能念羁旅，天地俱浮萍。","举首望飞泉，日暮未肯归。","夜凉多好风，明月有清辉。","一举随所之，不如鸿鹄飞。","思亲泪如雨，有露亦在衣。"]},{"t":"久雨","f":"五言律诗","c":["十日七日雨，十步九步水。","师徒宿蓁莽，宴坐吾亦耻。","其谁护封穴，未忍鸟鼠死。","天意若有谓，无人可言此。"]},{"t":"寄定州许资政","f":"五言古诗","c":["中行耀师宠，北顾宽上忧。","惠泽苏民瘵，威名闻鬼陬。","盐梅合调羹，帷幄聊运筹。","中山想可见，更登城上楼。","清患在未形，患形其计难。","父老不言兵，朝廷今久安。","贵侯弄丝竹，骑士矜绮纨。","念念须预防，壮士心为寒。","非公能知微，何敢矢此言。"]},{"t":"月夜示子文","f":"七言律诗","c":["喜见明月到池东，我时独与孤转同。","山光水色饮不尽，更烦佳木来清风。","浩歌一声志万里，飞飞欲到蟾蜍宫。","君家玉琴试借我，为君写尽丝弦中。"]},{"t":"招赵温甫饮","f":"七言古诗","c":["典衫买酒送春归，与春惜别无欢怡。","穷村荒凉物色薄，肥鸡绿笋皆出雌。","却思清谈醉我腹，愿君促驾无迟迟。"]},{"t":"和蒋深甫雷亭韵","f":"七言律诗","c":["巉岩巨石藏蛟龙，石破龙归旧迹空。","风生江面激惊浪，雨歇天涯横断虹。","高吟独据一老木，远望喜见双飞鸿。","踪步忽逢溪上叟，忘言疑是渭滨翁。"]},{"t":"赋朱令水渠","f":"七言律诗","c":["宣城貌古心亦老，自誇渠成非草草。","始挈孤忠犯众仇，此身弃绝甘夷岛。","异言塞尽流始通，大功成就民斯保。","天子虚心问民利，利如此渠亦须宝。"]},{"t":"谅闇闻笛","f":"七言律诗","c":["夜闻孤笛城头上，少年侧听成惆怅。","明月纷纷送忧咽，清风点点来悽怆。","鼎湖梦短飞不到，苍梧望断目几耗。","此身犬马贱徒劳，君德岳山崇未报。"]},{"t":"积德","f":"五言古诗","c":["积德由丝毫，扬名满天地。","古人成之难，今人败之易。","不知责己重，而独于人备。","天下此说用，无亦残风谊。","观物窃有得，作诗聊自志。"]},{"t":"有感","f":"五言古诗","c":["吾身本山林，艰难知备尝。","天寒负书橐，万里冒雪霜。","山川风借力，道路泥为浆。","瘦马鞭不前，悲歌自慨慷。","今也偶得禄，虽劳庸何伤。","念尔草野夫，百辈勤送将。","不惟风雪勤，无乃田畴妨。","素餐烦尔徒，心颜两愧惶。","作诗书诸绅，庶几久无忘。"]},{"t":"夜登竹亭","f":"五言古诗","c":["碧玉多朝风，萧洒不及夜。","沧溟月飞出，碎影如刻画。","爱君有素节，霜雪不凋谢。","无言静相对，似欲闻情话。","城上已三更，欲归犹未罢。"]},{"t":"轻舟","f":"五言律诗","c":["轻舟入深川，钝驹陟高山。","胡为弃安乐，轻去趋险艰。","一身事业荒，双亲鬓发斑。","思之不远虑，览照胡为颜。"]},{"t":"邻鸡","f":"五言律诗","c":["邻鸡号清晨，客子起长道。","二仪久风雨，百里生泥潦。","高山险难登，钝马行欲倒。","仆劳请休息，西北日尚杲。"]},{"t":"寒食","f":"五言律诗","c":["山川路崎岖，于此遇寒食。","冒雨虽甚苦，驱车不遑息。","敌愁酒无功，悦目花少色。","谁当逆旅思，独任清吟力。"]},{"t":"游子","f":"五言律诗","c":["游子何所之，上下山水中。","泛滥不系舟，飘飖孤飞鸿。","杨朱泣路歧，阮籍悲途穷。","我志非此流，高吟属春风。"]},{"t":"陟山登涧","f":"五言律诗","c":["此身何时休，终日镇衮衮。","才登涧之滨，又陟山之阪。","仆驽怯负重，马困忧途远。","道路亦常态，勉旃强餐饭。"]},{"t":"偶题","f":"词","c":["雍然凤之雏，杰然龙之驹。","九天无乱云，万里多坦途。","霜蹄风翮一朝举，疲驽燕雀安能俱。"]},{"t":"赠君俞茶盂","f":"五言古诗","c":["人心一何巧，得泥自山隅。","运泥置盘中，百转成双盂。","粹质淹雪霜，清辉夺璠玙。","精明绝隐匿，洁白无瑕污。","殷勤持赠君，意似生束刍。"]},{"t":"赋刘令公署双头芍药","f":"五言古诗","c":["花容人所怜，花意我独知。","雨露三月春，齐荣一纤枝。","并立无妒心，相逢况芳时。","长同白日照，不为颠风离。","世情正暌乖，因赋芍药诗。"]},{"t":"自诫","f":"五言律诗","c":["居方贵由礼，待物当竭诚。","诚亡鄙虑见，礼去骄心萌。","曾参日三省，杨子嗟四轻。","勉旃践此诚，蛮貊犹可行。"]},{"t":"寄春卿","f":"五言古诗","c":["相约童稚间，遂成岁寒图。","奈何离别多，各自东西隅。","我心明月轮，子志青松株。","明月千里光，岂为吴越殊。","青松四时心，岂为风霜枯。","相思不相见，作诗报区区。"]},{"t":"自谢","f":"五言古诗","c":["瘠田历水旱，畎亩多荒芜。","良农为锄耰，不岁成膏腴。","瘦木僵风雪，枝干皆蟠迂。","良工试刻斲，不日成盘盂。","在人虽不肖，蒙教当自殊。","重念贱子庸，仅同流俗愚。","学不达本原，行行无廉隅。","九思失孔戒，三省忘曾模。","背道而妄行，轻言以招辜。","一身旅焚巢，众目睽张弧。","奔驰今逝矣，玷圭可磨乎。","昼寝过甚微，圣门斥弗诛。","于今底荒唐，较彼尤昏逾。","尚赖君子仁，为包小人蒙。","未即远方屏，止于鸣鼓攻。","过愆苟不涤，忧虑环无穷。","归来讼丑迹，自欲鞭微躬。","父母遣汝来，期尔才德丰。","亲友壮尔行，思尔事业充。","不沿仁义流，反扇偷惰风。","固宜众人归，讵可多雷同。","犹愿追已往，从此图令终。","庶几谢颜子，自誓规缪公。","敢期白日光，重照幽谷中。","驱除困蒙吝，震荡迷复凶。","作诗代负荆，鄙诚实悾悾。"]},{"t":"衢州道中","f":"五言古诗","c":["登山复降山，仆膝良已酸。","出溪复入溪，仆衣未尝乾。","嗟余久羁旅，囊橐亦已殚。","无食充尔饥，无衣覆尔寒。","买酒聊一醉，行行莫长叹。"]},{"t":"冬日道中作","f":"五言律诗","c":["夜卧衾裯单，不敢嗟体寒。","晨餐蔬食微，不敢叹腹饥。","重念饥寒民，亦有甚我身。","我心若嗟吁，彼俗当何如。"]},{"t":"寄宁子文","f":"七言律诗","c":["相逢一笑东风前，相别一醉昌江边。","我来西山春正妍，未见君子心欲燃。","紫泥诏命鼎来矣，黄卷文章宜勉旃。","题柱相如知有志，著鞭无使祖生先。"]},{"t":"送蒋司勋赴河北漕使","f":"词","c":["于皇时宋，治定百年。","朝廷肃雍，以有多贤。","蒋侯孔硕，克明其德。","其立嶷嶷，其严翼翼。","英考是擢，以司邦直。","彼富贵不仁，人则惮之，侯曰吾治之。","彼孤有幼，人则侮之，侯曰吾绥之。","窜逐流落，江湖东南。","侯曰行哉，义岂吾惭。","皇帝思之，擢使于闽。","于淮于江，治绩升闻。","皇帝曰咨，朕宠尔勤。","俾相尔攸宜，莫如河朔。","往都漕事，以谋以度。","侯拜稽首，受命不敢居。","言秣其马，言脂其车。","其马騑騑，虽疾而仪。","其车轩轩，既博且闲。","蒋侯归止，觐于天子。","天子是喜，曰朕有贤卿士。","明明蒋侯，政事文章。","以明以将，当至庙堂，奚止河一方。","汝砺作诗，式赠其行。","俾人咏歌，以永厥声。"]},{"t":"送上官察院归闽中","f":"词","c":["南山幽幽，非可陵之丘。","渊渊其渊，非潢污之泉。","我徒以趋，君假我以车。","我泳而游，君载我以舟。","君行未至，我心非乐。","君去不迟，如之何勿思。","是用作歌，以告吾怀。"]},{"t":"某偷惰不强日陷罪恶元忠哀怜惷愚未忍诛绝赐诗为戒佩服弗忘韵险且长赓和未逮聊作短句以代负荆","f":"五言古诗","c":["小人无远虑，苟志怀与安。","富贵本浮云，百计图一完。","辰乎来之迟，玩弄如等闲。","其不为禽狄，不能分寸间。","故人哀怜之，投以药石言。","伏读夜达旦，颜汗肌骨寒。","顾惟壮盛时，气大力亦敦。","泰山陟其颠，不见宇宙宽。","荡舟绝溟渤，独自观其澜。","老大不自强，喑嘿甘素餐。","更欲盗恩荣，归取妻子欢。","自非仁人心，孰肯救此患。","过恶苟容改，勿惮提耳烦。","将大书诸绅，佩服永弗谖。"]},{"t":"蒋颖叔以广陵诗见赠次其韵","f":"七言古诗","c":["久病乘秋足寒热，欲巢高木藏营窟。","衰迟不是富贵人，便合买田投印绂。","荆溪大士简我诗，坐觉闇室阴云披。","垢尽清明入两目，忧忘喜乐生中脾。","缄縢扃鐍欲自私，不知半夜扬清辉。","儿童怪骇私问我，谓予蕴玉藏珠颗。","輶车近说足遐观，烟霞日夜生毫端。","楼台缥缈云中寺，众马不前君独至。","却跻双林跋提水，更登百丈大雄山。","游淮已擅中秋夜，落帽须分九日天。","茱萸准拟楼头会，终朝把酒千峰对。","杖藜徙倚望八荒，孤鸿飞出青云外。"]},{"t":"拟田园乐 其一","f":"词","c":["买田何须近郭，作屋却要依山。","青松共我终始，白鸟随人往还。"]},{"t":"拟田园乐 其二","f":"词","c":["春酒家家初熟，春花处处光辉。","看花更携酒去，酒醉却插花归。"]},{"t":"拟田园乐 其三","f":"词","c":["步月溪头置酒，野草不妨醉眠。","百岁独多暇日，万家共乐丰年。"]},{"t":"拟田园乐 其四","f":"词","c":["山色依云闇淡，溪声漱玉玲珑。","孤笛醉吹明月，扁舟卧钓秋风。"]},{"t":"拟田园乐 其五","f":"词","c":["霜寒禾黍初熟，日落牛羊自归。","乐事须还田舍，浮名不入柴扉。"]},{"t":"拟田园乐 其六","f":"词","c":["稚子骑牛横笛，老翁置酒高歌。","算来人生有几，莫问世事如何。"]},{"t":"送许屯田","f":"五言古诗","c":["君尝治浮梁，德爱均父母。","黎明令一出，百里无敢侮。","黠吏窜狐鼠，惠爱沾农亩。","浮梁巧烧瓷，颜色比琼玖。","因官射利疾，众喜君独不。","父老争叹息，此事古未有。","君尝速我饮，漓薄祇村酒。","君举长满觞，我畏不濡口。","京师晚相值，相笑俱老丑。","我欲提君名，四方为奔走。","君立掉头去，自谢吾无取。","移舟去都门，待水三月久。","不一诣权贵，挂席随南斗。","庐陵据艰险，狱讼成渊薮。","君以一目视，无恶亦无苟。","三年最课上，坐冠江西部。","我来君及瓜，欲荐嗟掣肘。","有才使如君，未见终不售。","即听宣室诏，莫爱潮阳守。"]},{"t":"马粹老谒黄龙祖心云得趣向处除烦恼矣因以偈谒之","f":"五言律诗","c":["门门赵州门，路路曹溪路。","此间无向背，云何说向趣。","佛游五浊世，不说无烦恼。","此心即是佛，云何说除埽。"]},{"t":"大暑道中","f":"五言律诗","c":["高堂卧清风，顾我岂不欲。","王事不可缓，驱车冒炎酷。","赤日暴形骸，毛发几焦秃。","义命有固然，勤劳不为辱。"]},{"t":"小舟过陂口","f":"五言古诗","c":["轻舟落陂漘，脱去如一叶。","篙工习攲险，振呼矜巧捷。","急水生凉风，盛暑熨汗浃。","涉远虽力壮，临危固心怯。","不如山居安，魂梦亦妥帖。"]},{"t":"大暑息林下","f":"五言律诗","c":["溪流转东西，日色不可障。","水风鼓炎热，如坐蒸炊上。","幽林隤山谷，弛楫没清旷。","行矣难少留，白云在吾望。"]},{"t":"老母德安县君生辰颂时湖南奉使途中作","f":"词","c":["有节维冬，有载维春。","维时斯成，惟诞斯辰。","妇妾祇祇，儿女诜诜。","是笑是言，是祝是虔。","其德维何，维厚之坤。","其福维何，维北之山。","嗟尔小子，不克骏奔。","靡不肃雍，维我母贤。","无有申之，有永其年。"]},{"t":"自勉呈尊叔","f":"五言律诗","c":["欲成九层台，不敢宁厥居。","昨朝雨暴至，圮败祇须臾。","百年养不足，一日毁有馀。","非叔有至言，吾终小人徒。"]},{"t":"和君时城上乐字韵","f":"五言古诗","c":["吾衰寡所欣，惟子足与乐。","爱君凌云气，更老更充扩。","危城纵登眺，万里见澄廓。","中林韵秋风，往往中宫角。","琼液白玉浆，十分许君酌。","是非等毫发，未足烦商搉。","贪徇终不还，彼哉世人错。"]},{"t":"长芦阻风","f":"五言古诗","c":["纵目江南路，系船淮上村。","长芦云作阵，高柳石为根。","浪逐江风急，潮连海水浑。","雪霜千骑散，钲鼓万兵屯。","蒲藻鱼游处，泥沙鸟篆痕。","参差邻画舫，咫尺想空门。","贝叶有秘语，韦编无近言。","漫瞻双去翼，空饰两朱轓。","好在弥天释，何如炙輠髡。","浊清罗酒斝，南北看风幡。","敬信无非事，精微讵可论。","孤忠天未弃，尚合辱垂恩。"]},{"t":"路人有弃其子者因作是诗予时奉使湖外","f":"词","c":["彼呱呱者，其孰弃之。","彼嬛嬛者，其孰收之。","彼禽何知，能字其雏。","飞前则顾，饥啄则呼。","孰谓斯人，禽之不如。","彼雏之微，皆得所依。","婉娩其音，婆娑其衣。","孰谓斯人，乃独无归。","我号斯言，以告采诗。"]},{"t":"和君时弟韵","f":"七言古诗","c":["流火退缩金盛强，郊原日夜生寒凉。","梨垂栗皱橙柚香，田家笑语炊黄粱。","山水秀彻摇秋光，重岩细菊斑斑黄。","万象呈露无遁藏，时和岁丰辰亦良。","脂车与子游上方，吐论纵横气轩昂。","书帙罗列图画张，睥睨孔孟窥虞唐。","偃息道奥缘禅床，苒苒定看移星霜。"]},{"t":"不寐","f":"五言律诗","c":["吾行不能休，中夜或不寐。","悠悠此时心，往返遍万类。","鳏鱼固不瞑，梦蝶亦无事。","纷纷尔何为，百虑终一致。"]},{"t":"和叔宜弟 其一","f":"五言古诗","c":["悠悠白云飞，戚戚感我情。","白云行四方，顾我岂惮行。","投袂起番水，荷担指宜城。","所怀再踰秋，计以顷刻成。","远装有书帙，贫囊无金籯。","马羸半徒步，仆瘦复兼程。","天寒雪频飞，山阻路少平。","林端虎豹迹，驿后豺狼声。","我行有所怀，虽壮如孩婴。","入门旅愁破，侍席春风生。","丁宁道怀感，恻怛一坐倾。","我今授汝记，汝当以孝名。","孝能事其亲，荣亦及乃兄。","乃兄久衰矣，山川倦遐征。","归与治尔田，我归耦而耕。"]},{"t":"和叔宜弟 其二","f":"七言绝句","c":["泪痕如雨欲垂垂，知汝心诚系綵衣。","江外若逢鸿雁过，时将音问寄庭帏。"]},{"t":"答张知常 其一","f":"七言律诗","c":["曰归去上凤凰台，已见云中鸣雁来。","携酒几时窥北海，采兰三月去南陔。","山间鼠窃不为盗，屋上鹳巢无妄灾。","但喜朝廷容正直，更须郡守择贤才。"]},{"t":"答张知常 其二","f":"七言律诗","c":["两鬓萧条今更衰，茱萸祇似去年时。","甘从彭泽渊明醉，未肯牛山丘据悲。","泛菊想公多乐事，及瓜如我有归期。","须穿略彴行松径，尚见芙蓉出槿篱。"]},{"t":"游西山","f":"楚辞体","c":["我少及长从公游，我今老矣公白头。","渊明彭泽不归去，太史周南方滞留。","爱山兴与精神聚，形骸自笑縻圭组。","欲骑马去陟彼砠，空羡鸿飞在于渚。","西山第一列洞天，别有日月无岁年。","洪崖已成丹灶药，瑶池每赋白云篇。","嘒嘒蝉噪竹枝露，斑斑豹宿颠崖雾。","伯兮伯兮归勿遽，人间旱岁须霖雨。","秋雨辛勤开菊花，春风取次生兰芽。","我虽调公不敢易，龙驹会去超胡沙。"]},{"t":"爱山楼歌","f":"楚辞体","c":["山隆然兮为屏，楼缥缈兮浮空。","朝阳起兮辉辉，白云宿兮溶溶。","乔木兮阴阴，泉飞兮珑珑。","花香兮春雨，鹤唳兮秋风。","企望焉兮徜徉，横四海兮无穷。","气飘浮兮欲仙，嗟势利兮樊笼。","归去来兮何为，从公游兮山之中。"]},{"t":"和彦衡直讲 其一","f":"五言古诗","c":["日隐天北角，月飞海东头。","清晖到堂除，转觉夜气幽。","睥睨天地间，无物奚为忧。"]},{"t":"和彦衡直讲 其二","f":"五言绝句","c":["是身如芭蕉，况复身外名。","至人本无心，肯为宠辱惊。"]},{"t":"和彦衡直讲 其三","f":"五言律诗","c":["风随月明来，终夜共清白。","先生静无语，独看庭前柏。","冠带褫客衣，诗书倦尘迹。","好风此时来，应与君相识。"]},{"t":"和彦衡直讲 其四","f":"五言绝句","c":["照月槐影碎，吹风柏声繁。","悠悠此时心，可乐不可言。"]},{"t":"使虏有怀","f":"七言律诗","c":["长年日戏老莱衣，不忍此身终日违。","今日马头燕北去，不堪频望白云飞。","白云汝飞去何许，悠悠会到江南路。","朔风吹洒泪大河，直与波澜竞东注。"]},{"t":"芦花","f":"词","c":["风起芦花散雪，纷纷故着枯槎。","晓日曚昽照处，十分认作梅花。"]},{"t":"沙柳","f":"词","c":["沙陀祇见尘土，柳色如逢故人。","忆着千条万叶，金明驰道青春。"]},{"t":"韩氏周宣王时为侯尝入觐而归显父饯之尹吉甫作诵今司空康国公既老元祐丁卯朝京师戊辰春还许天子赐燕某赋是诗","f":"词","c":["在昔韩侯，受命有周。","绍嗣禹功，以续祖考。","韩侯入觐，玄衮介圭，有淑其旆。","韩侯归止，显父是饯。","笾豆有践，奏鼓衎衎。","韩侯燕喜，既多受祉。","施于子孙，为宋柄臣。","有子且贤，长则上公。","亦似前人，有赫厥庸。","公老许田，载见式时。","朝有大疑，公为蓍龟。","公去不留，天子是思。","薄言维之，旟旐有辉。","都人咸喜，祝之千岁。","国有元老，邦家是赖。","康公之德，寅亮孔硕。","利泽在民，功在社稷。","孰能诗之，以继韩奕。","诞发其声，施于罔极。"]},{"t":"舟中偶言","f":"五言绝句","c":["水聚即为沤，沤散还为水。","祇这聚散中，便是真如理。"]},{"t":"和瑛师","f":"五言律诗","c":["去来的的然，莫道无来去。","烟萝宝峰境，风月清源路。","雨涨没沧洲，云归出孤屿。","风便水亦便，非讼亦非诉。"]},{"t":"题本觉庵","f":"五言绝句","c":["本觉非今觉，今觉如本觉。","悟得本觉时，非觉非非觉。"]},{"t":"皇帝郊祀礼毕诣景灵恭谢次履中学士韵","f":"七言律诗","c":["黎明驾出告熙成，朝野人呼万岁声。","日上天门春意近，雪残宫瓦晓寒生。","六龙宠护随天仗，三爵恩容醉御觥。","德似丘山纤未报，白头知愧不知荣。"]},{"t":"皇帝郊丘从驾次履中学士","f":"七言律诗","c":["今岁郊丘上始躬，宿斋初出未央宫。","百年礼乐星辰烂，万国衣冠锦绣中。","精意与天相应接，人心如水自流通。","圣时好作休成记，今日谁为太史公。"]},{"t":"次韵履中学士宴集英殿","f":"七言律诗","c":["衮衣玉色殿中央，簪佩参差万翼张。","和气每窥天一笑，晬容时见日重光。","九成乐奏蓬山近，百和香焚黼座傍。","鱼跃鸟飞应自喜，君仁三倍胜岐昌。"]},{"t":"次履中学士正月十一日迎驾大庆殿","f":"七言律诗","c":["瑞雾苍茫杳霭间，迟明催立大庭班。","禁林草木青春近，秘阁文书白日闲。","华盖荧煌天帝座，蓬莱缥缈道家山。","金舆玉乘归何晚，乐奏钧天梦未还。"]},{"t":"考试阁下次子由韵","f":"七言律诗","c":["省曹祇有西曹要，官府无如宪府严。","国论于今须汲直，人才自昔畏由兼。","斧斤准拟栋梁得，尘土吁嗟圭璧淹。","万事调和归适可，诸公闻望在梅盐。"]},{"t":"赠去华学士","f":"七言律诗","c":["射策熙宁第二人，十年青绶困京尘。","声名未误如椽笔，宠辱何疑是梦身。","壮志自能探虎穴，危言更看逆龙鳞。","美才何但膺门客，观国今时正利宾。"]},{"t":"岩夫庭佐欲归出长安以诗邀游后圃","f":"七言律诗","c":["马蹄容易去吾东，行李纷纷计已匆。","还使寸肠随夜月，不知一泪落春风。","双飞露草看原鹡，独宿云溪念塞鸿。","更约藏舟今日饮，百壶清笑慰飘蓬。"]},{"t":"奉答诸兄弟诗韵","f":"七言律诗","c":["饥渴相期侍板舆，途中千万数脂车。","浮生本自云无定，白发新来雪不如。","原上脊令知望汝，洲前鹦鹉看题书。","愁肠日有平安信，祇问江头双鲤鱼。"]},{"t":"得至郢州寄知郡朝议","f":"七言律诗","c":["襄阳曾赋赠行诗，邂逅扁舟得所期。","胜迹好寻梅福宅，真游稍记习家池。","郢中白雪今谁和，汉上仙槎恰是时。","冰酒直须多准备，寄声先报主人知。"]},{"t":"寄和仲","f":"七言律诗","c":["日月其除如掷梭，老来衰疾转添多。","苦心不祇荼毒似，短发无如霜雪何。","毕竟行藏浑有定，寻常聚散亦非它。","欲知日暮相思意，牛首山前湖水波。"]},{"t":"奉怀深父学士友兄 其一","f":"七言律诗","c":["泛泛公舟何所之，江湖不似月相随。","关西夫子吾所畏，河上丈人今所思。","蓬发白如相别日，菊花黄似去年时。","看花欲饮竟无味，不是贫家缺酒卮。"]},{"t":"奉怀深父学士友兄 其二","f":"七言律诗","c":["看山更饱更无厌，野色虽寒亦不嫌。","风作浪头高突兀，云埋雨脚细廉纤。","一双远岸钓鱼艇，三尺近村沽酒帘。","海上浮舟忆彭蠡，门前栽柳旧陶潜。"]},{"t":"奉和施禽鱼食复赓一章","f":"七言律诗","c":["南方有国号清凉，人好禽鱼性亦良。","在藻日分香积饭，衔花时绕净明床。","濠梁孰谓安知乐，大泽吾能不乱行。","但得养鱼如养己，相濡仍不似相忘。"]},{"t":"江上寄广汉屯田丈","f":"七言律诗","c":["白首扁舟西复东，沧江时对百花丛。","山光缥缈云霄外，水气溟濛烟霭中。","似酒鹅儿随暮雨，于飞燕子语春风。","一杯欲饮终无绪，想望邻家鹤发翁。"]},{"t":"和瑛师","f":"七言律诗","c":["江湖日夜著东流，水上乾坤一点浮。","隔浦云山随客步，近村花竹慰人愁。","同舟自有林宗在，结社还须惠远游。","酒兴正酣归更懒，坐看凉月上沧洲。"]},{"t":"兵部敏叔颁示佳句谨依原韵","f":"七言律诗","c":["遍瀰川泽压冈峦，万室清明更可观。","麦上早春谁漏泄，梅边穷腊自凋残。","阴阳顺适天时好，高下均平地泽宽。","岁岁丰登今以始，都人切勿怨祁寒。"]},{"t":"次去华学士韵","f":"七言律诗","c":["九衢尘土暴秋阳，宫殿深沉早自凉。","庭柏染霜千丈碧，篱花著雨一番黄。","天边河汉波澜阔，海上蓬莱日月光。","文物岂惟淹汉魏，太平久矣四三皇。"]},{"t":"寄君时弟","f":"七言律诗","c":["日夜风前听好音，书来一读一伤心。","泪摇眼尾催花发，愁结眉头见雪侵。","秋径自栽彭泽菊，夜堂时奏武城琴。","事多不废看书否，白首知君惜寸阴。"]},{"t":"送祖道朝奉","f":"七言律诗","c":["二月同舟出宋都，转头即是十年馀。","可怜老大犹为客，莫怪寻常不作书。","蜡屐阮孚人不会，鲈鱼张翰子何如。","寄声莫污清风地，留与先生作隐居。"]},{"t":"送吴县丞","f":"七言律诗","c":["四十青衫似老翁，作官不似作诗工。","身追鸿鹄云霄外，手缚鲸鲵波浪中。","俊敏今非无李白，沉深古自有扬雄。","和声直可奏宗庙，叹息无人知爨桐。"]},{"t":"送叶亨仲","f":"七言律诗","c":["太学声名二十年，词场少以一当千。","王良仅可使执辔，祖逖岂容争着鞭。","文字莫愁蒙酱瓿，功名欲看勒燕然。","故人相见如相问，为说萧条雪满颠。"]},{"t":"四月七日出城西见河中资政侍郎遇中叔联骑入池南门行东北隅以归各赋一首","f":"七言律诗","c":["一过西城首一回，经年欲往限尘埃。","蔷薇露湿春犹在，杨柳烟深晓未开。","雨后波光浮渤澥，云中山色隐蓬莱。","与君驰马竞东北，也道曾来池上来。"]},{"t":"和美叔学士","f":"七言律诗","c":["早日清明气郁葱，翠舆朝出建章宫。","光回鹭羽云霄外，翠滴荷衣雨露中。","苦爱平心似崔郾，预愁启事愧山公。","酬诗自笑才悭涩，不似清微长养风。"]},{"t":"和彦常侍郎","f":"七言律诗","c":["濯濯威灵赫赫光，天颜咫尺在岩廊。","图功未肯兄三古，较艺何嫌弟寸长。","鼓舞雷风驰汉诏，昭回云汉见尧章。","酒樽更有论文乐，一笑令人万事忘。"]},{"t":"再和彦常侍郎","f":"七言律诗","c":["天上九重开禁闼，云间千步见修廊。","仙源水近漂花急，化国人闲爱日长。","较艺过旬窥锦绣，赋诗终日听韶章。","时沾好赐终何报，自许馀忠老未忘。"]},{"t":"送池须文长官","f":"七言律诗","c":["龙渊虎穴少穷探，老大生涯一剑镡。","曲沼鸳鸯多白发，雕笼鹦鹉久青衫。","能知令尹三无愠，正似嵇康七不堪。","见说明朝好天色，鹏程从此稳图南。"]},{"t":"刘生适中初业儒稍能文词气勇而不暴甚得乡士人心连蹇不得志以医游四方元祐七年来京师予与乔给事公权丰侍郎相之荐于朝入翰林为医官孙待制传师帅渭辟以从予哀生之志未得而喜其得贤主人以归也作是诗以送之","f":"七言律诗","c":["短衣瘦马去从军，辛苦知君祇为贫。","丝绶戏拈五两去，桂华志取一枝春。","持书关内大丞相，寄语渭滨贤主人。","种种别时双鬓发，萧条今日总如银。"]},{"t":"送蒋和父赴代州教授","f":"七言律诗","c":["十年场屋饱声名，落笔从容一坐倾。","馀泽未能沾万物，绪言聊复启诸生。","青衫簿领当时态，白首诗书足义荣。","得失已知君不恤，春风谈笑入边城。"]},{"t":"丰湖 其一","f":"七言律诗","c":["漫漫平湖十里赊，南州今作画图誇。","波澜雨过鱼儿出，草木春归荔子花。","山近冷光摇几席，地平馀润入桑麻。","使君恩德还如水，长满罗浮十万家。"]},{"t":"丰湖 其二","f":"七言律诗","c":["仙阁玲珑高出云，画桥缥缈净无尘。","满分江海千年润，平占蓬瀛十里春。","照浦蠙珠应自复，随舟鸥鸟会相亲。","使君爱物能如此，闾巷当时合借恂。"]},{"t":"和深父学士","f":"七言律诗","c":["故人气分比松筠，凌雨霜风转更新。","暇日莫辞三斗酒，浮云便是百年身。","今来古往祇如此，弟唱兄酬莫厌频。","雪霁拥炉须酩酊，月明分手更逡巡。"]},{"t":"和侯利建运使朝请","f":"七言律诗","c":["当年置酒岘山亭，公作新诗我载赓。","疾病尚怜忧似醉，文章还看美如英。","伤哉无复老莱戏，久矣不闻韶乐声。","饥鹄欲飞嗟已老，谬烦江汉借修程。"]},{"t":"和通判朝奉宋丈 其一","f":"七言律诗","c":["尘事如毛日日生，故园久拟问归程。","飞鹏怒薄扶摇上，病骥饥寻巀嵲行。","绿野尽头迷汉水，白云深处是樊城。","私怀借问何其似，祇看摇摇车上旌。"]},{"t":"和通判朝奉宋丈 其二","f":"七言律诗","c":["未忍田间老此生，衰迟已觉怯修程。","频频彼似鸒斯党，踽踽吾非杕杜行。","云影昼迷芝岭路，水声夜到凤林城。","仆夫不见人忧思，未晓匆匆已抗旌。"]},{"t":"再呈通判承议 其一","f":"七言律诗","c":["山边置酒水边行，鱼鸟于人各有情。","终世果能著几屐，此时聊可濯吾缨。","启期拍手誇三乐，渔父张颐笑独清。","四海一舟归未得，低徊长恐负平生。"]},{"t":"再呈通判承议 其二","f":"七言律诗","c":["南头如送北头迎，祇有溪山不世情。","少日激昂投耒耜，老年辛苦畏簪缨。","长松根脚龙蛇蛰，老鹤精神玉雪清。","会得无生浑自足，还容款曲问长生。"]},{"t":"呈通判朝奉宋丈 其一","f":"七言律诗","c":["昨日南阳今淅川，驰驱不敢恨华颠。","久披褐布是居士，时着斑衣犹少年。","系屧记寻幽径竹，泛舟忆近碧池莲。","笑君与我浑相似，目病鳏鳏夜不眠。"]},{"t":"呈通判朝奉宋丈 其二","f":"七言律诗","c":["经时山川浪跋履，半夜衣裳时倒颠。","尘土最能催白首，风波祇会送流年。","寂寥彭泽门栽柳，萧洒东林社结莲。","语及故乡归未得，看云步月欲忘眠。"]},{"t":"持正率和中丞诸公喜雨 其一","f":"七言律诗","c":["昊天旋日照宸忧，灵雨崇朝遍舜州。","云起山川初一点，水倾河汉欲交流。","欢愉散入舆人诵，润泽浑供万物求。","遥想玉山禾粒熟，来仪还见凤凰秋。"]},{"t":"持正率和中丞诸公喜雨 其二","f":"七言律诗","c":["盛德无烦百姓忧，分明灵贶厚齐州。","精神散接诸天远，润泽横随四海流。","玉色晬温知有喜，渊衷澄寂本无求。","史官屡得丰年事，还记熙宁第十秋。"]},{"t":"奉寄深之学士子开侍郎","f":"七言律诗","c":["万国承平道更尊，君王取士夙临轩。","雕虫立废贾马赋，发策跂闻晁董言。","兰艾同荣春霭霭，鱼龙欲化海浑浑。","风流想见东华路，夹道传呼看状元。"]},{"t":"时在集英幕中呈诸公学士","f":"七言律诗","c":["衰病从来饭亦慵，不堪锁宿似南宫。","夜凉月满重帘外，春雨花开一梦中。","轩陛直言尊董氏，朝廷故事问胡公。","文章久怪无新语，议论初欣有古风。"]},{"t":"和范学士韵 其一","f":"七言律诗","c":["大府池台能近郭，邻家花木巧当颜。","丛篁著雨初成径，巨石浮烟恰是山。","御气即能驰碧落，战文谁敢敌黄间。","乐天自得三无愠，易地何殊五不还。"]},{"t":"和范学士韵 其二","f":"七言律诗","c":["先生亡子众推贤，号慕今犹似恸颜。","西竺尝言空是色，南华亦笑泽藏山。","由来世事无穷处，毕竟人生在几间。","看著江流长泛泛，可言逝水不知还。"]},{"t":"和范学士韵 其三","f":"七言律诗","c":["日华苒苒在波澜，水色依依照面颜。","汉上仙槎浮八月，海中金阙隐三山。","芙蓉开席成阴处，杨柳维舟倒影间。","景物向人情不浅，频将风月送公还。"]},{"t":"和范学士韵 其四","f":"七言律诗","c":["清香一炷意超然，万事无缘更动颜。","野鸟衔花来丈室，烟萝招月出遥山。","居方不碍游方内，住世还如出世间。","却笑晚年贪著事，野边湖外夜忘还。"]},{"t":"和范学士韵 其五","f":"七言律诗","c":["南阳五月饱偷安，报政无闻祇汗颜。","平日髡钳盈狴犴，丰年盗贼出丘山。","簿书细碎晨昏事，弦诵寂寥庠序间。","但见颍川多凤集，仍知合浦有珠还。"]},{"t":"和范学士韵 其六","f":"七言律诗","c":["岂有微功答谬恩，尚思荣禄慰慈颜。","心诚似水知宗海，事责如蚊欲负山。","资性仅同中以下，行能未及二之间。","木桃每屈言为赠，祇恐琼瑶未足还。"]},{"t":"和范学士韵 其七","f":"七言律诗","c":["南阳虽好远江干，襄沔归来失病颜。","雨霁远浮清汉水，云归深见上方山。","伤心蜀主君臣际，回首庞公父子间。","薄暮楼头待明月，笛声时见钓舟还。"]},{"t":"和范学士韵 其八","f":"七言律诗","c":["起照青铜已鬓斑，早衰不似旧容颜。","尘埃苒苒行其野，霜雪纷纷陟彼山。","稍忆辍耕栖垄上，不堪待罪久行间。","阳台自笑云无定，华表应疑鹤未还。"]},{"t":"和范学士韵 其九","f":"七言律诗","c":["风雨先催十月寒，顾瞻言迈祇悲颜。","二天旧泽流淮水，五色新文照楚山。","我病欲归虏使重，君行合在侍臣间。","颍川莫厌次公去，宣室方思贾谊还。"]},{"t":"和刘舍人","f":"七言律诗","c":["剪綵微茫比丝发，雕金焜晃映蝉貂。","鹓鸾破晓趋丹禁，雨露迎春下九霄。","花映上尊非索寞，雪侵馀鬓自萧条。","读书终日不知味，恰似在齐闻舜韶。"]},{"t":"和执中寄师厚同年 其一","f":"七言律诗","c":["千载风云庆一逢，枯荣相望百年中。","雪霜松桧材先老，泥土骅骝路未通。","颜子奚惭一箪食，阮生不是哭途穷。","春游取次吟花药，枉负灯窗翰墨功。"]},{"t":"和执中寄师厚同年 其二","f":"七言律诗","c":["日暮相忘城上亭，云深祇见数峰青。","傅岩可独为霖雨，荀里还归聚德星。","汉水溯风增浩荡，兰花着雨长芳馨。","啸吟久不过诸葛，丰度今谁似九龄。"]},{"t":"招执中看酴醾","f":"七言律诗","c":["恰是酴醾初盛时，清香终日在尘衣。","参差正对金沙拆，散漫更为蝴蝶飞。","日暖绿云长闇淡，春深白雪更霏微。","急来相就花前醉，看尽此花春欲归。"]},{"t":"寄正夫判官","f":"七言律诗","c":["数竿严濑钓鱼纶，一幅渊明漉酒巾。","天上旧传公子贵，汉阴今见丈人真。","登山临水能胥宇，问舍求田待卜邻。","欲作独清无已甚，时将数字寄埃尘。"]},{"t":"送宗文先辈","f":"七言律诗","c":["夫子声名二十年，尘埃叹息欲华颠。","相如旧有凌云赋，靖节今无种秫田。","南国寂寥归见雁，北风悲壮屡闻蝉。","思量世事真如幻，合置穷愁顿酒边。"]},{"t":"和子仲都官徐孺亭","f":"七言律诗","c":["已矣斯人不可从，风流今见一亭中。","云藏洲渚秋长碧，日在波澜晚更红。","旱岁会为岩际雨，贪夫亦畏海濒风。","于今未见如公比，叹息陈蕃榻亦空。"]},{"t":"和颖叔寄佛印 其一","f":"七言律诗","c":["有客寄诗南雍州，清新全占岘山秋。","官名便据非常宠，文学元居第一流。","云近蛟龙朝丈室，夜寒星月宿重楼。","知公有勇断鳌足，到彼不须骑虎头。"]},{"t":"和颖叔寄佛印 其二","f":"七言律诗","c":["忆留铁瓮城经夏，却泛金山寺看秋。","钟梵去随沧海远，楼台低涌大江流。","波澜隐约开龙国，烟雾分明见蜃楼。","他日上方容听法，不应疑我皱眉头。"]},{"t":"又寄佛印","f":"七言律诗","c":["神仙苒苒在蓬壶，更得诗来慰索居。","天上楼台开佛国，日边香火读天书。","篮舆独往公今尔，蜡屐他时我亦如。","彼是此非无足问，悠悠同是一空虚。"]},{"t":"途中久雨","f":"七言律诗","c":["我征徂西今复东，分明身世如飘蓬。","岁华便是百年半，日气恰当三伏中。","山谷无情频送雨，园林何事急招风。","浮生所遇皆知分，未用纷纷论色空。"]},{"t":"滩上","f":"七言律诗","c":["片帆逆水过溪山，吾贱能谙世路难。","小雨作云迷涧谷，急风吹雪上波澜。","草根已定春来意，梅蕊犹含腊后寒。","渐老岂能支道路，扁舟欲去老渔竿。"]},{"t":"送正孺","f":"七言律诗","c":["离筵冰冻樽中酒，行路雪沾身上衣。","游子思乡梦先到，老人惜别涕交挥。","昔年终军弃繻去，今日买臣怀绶归。","昼绣奚为公不乐，祇应愁见白云飞。"]},{"t":"答执中见和","f":"七言律诗","c":["枉费山公席上珍，看书转忆笑言亲。","旧时香积厨中饭，新得金莲社里人。","传语簿书聊借日，寄声风雨莫催春。","须容饱饫先生馔，可便闲防异姓宾。"]},{"t":"和伯钧节推","f":"七言律诗","c":["昔年相见蜀山隈，落落知君匪众材。","白发今时俱老大，青山何日盍归来。","烟尘草草驰军檄，风雨匆匆把酒杯。","万事欲言终不尽，诗成悽怆有馀哀。"]},{"t":"东流寄天保弟","f":"七言律诗","c":["湖山高下绿参差，目断东流此一时。","日久不闻鸿雁信，春来初见棠棣诗。","草根二月蒌蒿熟，沙外数家杨柳垂。","恰是去年相送处，酒樽还忆数追随。"]},{"t":"寄君时弟","f":"七言律诗","c":["正直多疑势易孤，官情时态近何如。","应知秋后无穷事，未得冬来第一书。","忆汝愁闻洞庭雁，作诗欲寄武昌鱼。","江湖此别何其久，日月居诸又岁除。"]},{"t":"使辽","f":"七言律诗","c":["北行未始过陈桥，仗节今朝使大辽。","寒日拥云初漠漠，急风招雪晚萧萧。","江湖梦寐时之楚，象魏精诚日望尧。","孤驿夜深谁可语，青灯黄卷慰无聊。"]},{"t":"古北口杨太尉庙","f":"七言律诗","c":["将军百战死嵚岑，祠庙岩岩古到今。","万里胡人犹破胆，百年壮士独伤心。","遗灵半夜雨如雹，馀恨长时日为阴。","驿舍怆怀心欲碎，不须更听鼓鼙音。"]},{"t":"过虎北口始闻鸡","f":"七言律诗","c":["雪馀天色更清明，野店忽闻鸡一声。","地里山川从禹画，人情风俗近燕京。","渔阳父老尚垂涕，燕颔将军谁请缨。","容覆不分南与北，方知圣德与天平。"]},{"t":"塞外冬至","f":"七言律诗","c":["今年至日是今朝，日影方长路更遥。","霜雪辛勤白榆塞，鹓鸿怅望紫宸朝。","阴冥丘壑云长暗，阳触渊泉冻欲销。","欲问春来消息近，几多垂柳在溪桥。"]},{"t":"闻驾幸太学","f":"七言律诗","c":["四海承平正右文，君王昨日幸成均。","三千缝掖星辰拱，十二旗常日月新。","万里去持山国节，六龙阻望属车尘。","上心直欲窥尧禹，咫尺谁能席上珍。"]},{"t":"寄君时宿直","f":"七言律诗","c":["天寒不归汝安否，日暮有怀如此何。","丈室全如在林壑，重云漫不见星河。","高风侧听雍雍雁，濡露长悲蓼蓼莪。","不是不知诗废事，相思不寐自成歌。"]},{"t":"雁池","f":"七言律诗","c":["池水人言是雁池，池边兀坐久忘归。","蓬瀛仙子红莲出，湖海幽人白鹭飞。","杨柳垂阴留客佩，沧浪泼翠点人衣。","故园一别头今白，目断江边旧钓矶。"]},{"t":"万安道中","f":"七言律诗","c":["上下鸡笼牛口滩，滩头濯濯雨声寒。","气蒸晓日云无间，波漾春风雪未乾。","落絮并花浮远水，飞鸥随鹭落惊湍。","扁舟稳泛沧浪远，珍重严陵一钓竿。"]},{"t":"和佛印","f":"七言律诗","c":["供佛堂中香积饭，度人门外白牛车。","参禅长老或雪涕，说法虚空时雨花。","灵鹫御风朝海渎，飞翚撒水抗烟霞。","老师住处即安乐，祇恐卧龙生叹嗟。"]},{"t":"执中学士以蔬菜见贶戏寄小诗","f":"七言律诗","c":["贷粟监河公自贫，蔬菹投我觉情亲。","不须乞饭去香积，谁会献芹如野人。","维笋及蒲全似古，式歌且舞恰当春。","投闲即拟同公醉，莫道无鱼可及宾。"]},{"t":"与文渊游聘君亭分题和文渊亭字韵","f":"七言律诗","c":["东湖九日水如冰，画舫还寻孺子亭。","雨后断云归冉冉，天寒孤雁去冥冥。","兰苕散漫池塘远，松竹参差岛屿青。","贪惜上恩归未得，自怜双鬓欲垂星。"]},{"t":"内乡","f":"七言律诗","c":["山谷生云作风雨，楼台映日贴烟霞。","危峰熊耳倍千丈，废堞虎遥今数家。","野外小桥丹作水，潭边仙菊雪开花。","隆寒大热三经涉，世事催人早鬓华。"]},{"t":"送子开侍郎出守徐州","f":"七言律诗","c":["彭城事事似南都，顷岁曾分刺史符。","吏治甚惭前有召，民谣更愧昔无襦。","最思凤沼凤凰集，还见雁池鸿雁孤。","万事我今无一乐，扁舟归梦满江湖。"]},{"t":"和蜀公家居","f":"七言律诗","c":["平湖三月水犹寒，霜鉴冰壶照玉颜。","柳暗何如江上路，云深不碍海中山。","春风凫雁窥青琐，晚日波涛在白间。","景物会招山简醉，时时倒着接䍦还。"]},{"t":"西湖","f":"七言律诗","c":["篇章芜漫不中看，误得先生一解颜。","明月何为投暗室，阳春不意在穷山。","平时借以齿牙论，今日见之眉睫间。","自笑鸤鸠为计拙，谁知鸿雁及时还。"]},{"t":"答蜀公奉酬 其一","f":"七言律诗","c":["叠石栽花作小园，庭柯顾盼足怡颜。","尽捐势利随流水，多占声名似泰山。","细雨凫雏浮水际，微风燕子语梁间。","竹冠筇杖篮舆好，认得公从湖上还。"]},{"t":"答蜀公奉酬 其二","f":"七言律诗","c":["逍遥今是地行仙，无事全胜药驻颜。","早岁风流都翰苑，他时文字出名山。","修竿养竹千馀亩，小屋诛茅八九间。","颍水可怜归未得，不如云鹤会飞还。"]},{"t":"答蜀公奉酬 其三","f":"七言律诗","c":["丛条润泽无瞋胆，芳杜将迎失厚颜。","陶令葛巾曾漉酒，谢公蜡屐惯寻山。","观鱼恰似濠梁上，结宇浑如冈曲间。","楚醴满觞知意惬，胡香细炷觉神还。"]},{"t":"途中奉寄","f":"七言律诗","c":["水涉山行歧路长，思亲一夜鬓毛霜。","纷纷枝上慈乌宿，肃肃云中鸿雁行。","活计一行随梦幻，生涯好去老耕桑。","知君合续南陔赋，万里因风数寄将。"]},{"t":"武冈路中","f":"七言律诗","c":["复岭重冈烟霭深，晚年多病觉难任。","他乡一日如三岁，远路家书抵万金。","流水可怜君未息，白云谁似尔无心。","天寒日暮双飞鸟，寂寂归栖只旧林。"]},{"t":"答张大夫友兄","f":"七言律诗","c":["尘土无人慰病怀，篇章一见觉心开。","风高昨夜冥鸿去，水涩何时画鹢来。","天上旧传公子贵，江东还见步兵才。","老成合有言为赠，倚马相望故凤台。"]},{"t":"送周朝议赴郢 其一","f":"七言律诗","c":["岩石沧洲一水涯，画船几夜宿芦花。","芭蕉山谷灵峰寺，龟鹤池塘梅福家。","今日岂应无白雪，当时亦未见皇华。","兵厨且善为冰酒，当为公浮八月槎。"]},{"t":"送周朝议赴郢 其二","f":"七言律诗","c":["驱马悠悠何所之，岘山南去习家池。","莲花可爱肌如雪，鸥鸟何为鬓亦丝。","一叶林头秋到处，片云溪上雨来时。","公方紫绶金章贵，可要山公白接䍦。"]},{"t":"城上","f":"七言律诗","c":["孤城纵目尽南东，山转溪回翠且重。","云际静浮滨汉水，林端清送上方钟。","今时汉北无雏凤，当日襄南有卧龙。","万事废兴无足问，登临吾乐正从容。"]},{"t":"代人答周朝议生辰赠章","f":"七言律诗","c":["我辰邂逅得朱明，一离阴邪一点生。","蓬矢尚存随薄宦，龙驹已老怯修程。","鬓毛久似安仁白，神气初惭卫玠清。","南郭丈人慈爱并，远分珠玉助光荣。"]},{"t":"谷城溪亭","f":"七言律诗","c":["谷国有亭溪水边，税车安寝不无缘。","芰荷苒苒双飞鸟，芦苇深深一钓船。","故国寄声无去雁，他乡催泪有啼蝉。","江山亦为行人动，六月寒风正凛然。"]},{"t":"答孙荆州颃","f":"七言律诗","c":["凤林清淑郁扶舆，五马当年数驻车。","故老作歌今未已，大贤为政法何如。","二碑岘首窥馀烈，一纸荆州得近书。","缩项槎头知未羡，龙州闻说更多鱼。"]},{"t":"病中寄君时","f":"七言律诗","c":["可怜平生不堪处，未有一朝无病时。","患难寻常心欲折，尘埃四十发如丝。","倦游司马多闻友，现病维摩大导师。","筋力尚堪游乐在，不应空废百花期。"]},{"t":"寄孙元忠","f":"七言律诗","c":["离群已是四年秋，昔是少年今白头。","旧日雁池应好在，多情睢水会东流。","更贫尚有箪瓢在，已见谁能度数求。","三径渊明多种菊，五湖范蠡有归舟。"]},{"t":"戏呈叶提举","f":"七言律诗","c":["自笑肩舆钝似椎，不如马足快如鵻。","驱驰祇似江西日，懒病全非年少时。","熟睡疑空净石室，沈思若下董生帷。","道途不独输公敏，凡事相方总较迟。"]},{"t":"和马太守五首 其一 寒林","f":"七言律诗","c":["平林十里看深秋，疏影横斜翠欲流。","日晚小舟维别浦，天寒飞鸟浴沧洲。","傍山畦径村村远，近水轩楹事事幽。","欲赋祇惭非太白，酒卮独觊一朝酬。"]},{"t":"和马太守五首 其二 翠玉","f":"七言律诗","c":["平湖如鉴见寒林，谁作高亭据静深。","到海水源终有本，从龙云影自无心。","芰荷一片随幽赏，鸂鶒双飞近醉吟。","顾我倦游归欲早，寒门独觊数窥临。"]},{"t":"和马太守五首 其三 水云","f":"七言律诗","c":["万竹娟娟一径开，禅师当日为谁栽。","本支间出为龙去，秀实长留待凤来。","挥袂好风能应接，杖藜栖鸟误惊猜。","公游岂得如嵇阮，禁省方归治剧材。"]},{"t":"和马太守五首 其四 五老峰","f":"七言律诗","c":["不到匡庐今几年，幽亭纵目意茫然。","苍颜想像重湖外，翠色参差落照前。","润泽为霖功及物，坚高作柱势参天。","使君笔墨真能赋，不必须凭绘画传。"]},{"t":"和马太守五首 其五 澄心亭","f":"七言律诗","c":["逸老初开池上亭，使君钟鼓乐新成。","宝林自有湖山助，定水何曾风浪生。","雨过淡云迷岛屿，日长幽鸟下檐楹。","扁舟远泛沧浪碧，可避时人笑独清。"]},{"t":"和念一弟","f":"七言律诗","c":["冈陵盘泊土湖深，蛟蜃伏藏山鸟吟。","大雪埋云冬寂寞，乔松夹竹昼阴森。","百年身逐无涯智，万斛愁中方寸心。","昨日汝诗催泪落，暴添溪水两三寻。"]},{"t":"临江道中人家多植竹","f":"七言律诗","c":["远远平山浅浅溪，人家栽竹当藩篱。","雪霜尽腊青如昨，风月乘春绿更滋。","淡薄冷光浮莽苍，招摇清影落涟漪。","故园所富今几顷，会有归来筑隐时。"]},{"t":"和毛正仲","f":"七言律诗","c":["风雨登危奚壮哉，见书三赋彼崔嵬。","细缘狗脊仆肩病，曲转羊肠车辙摧。","晨鹊卜知书信到，夜星占见使华来。","爱君最识思亲意，取次枯肠夜九回。"]},{"t":"寄提举朝议丈","f":"七言律诗","c":["安稳青云喜得舆，寂寥穷巷忆回车。","灌畦搰搰知同病，游刃恢恢想自如。","暇日会驰千里驾，好风时寄一行书。","爱公有似能鸣雁，顾我还同喣湿鱼。"]},{"t":"河东桥亭以久废置不用欲移菜畦以为老之游息之地因以诗就公权乞之","f":"七言律诗","c":["全家归住白云中，旧地新成半亩宫。","簇簇要添垂柏翠，纷纷已出小花红。","自知北海恩怀厚，况是东邻路径通。","到得落成应不负，携壶先约醉春风。"]},{"t":"杂咏一首","f":"七言律诗","c":["小林幽径自春华，不似城头望处佳。","山色倚云千万里，蓬门穿水两三家。","声闻翠筱纷纷叶，香落寒梅细细花。","更上幽亭望南北，欲随幽鸟到天涯。"]},{"t":"病告诗上侍读","f":"七言律诗","c":["诗句亲题慰下僚，清心洗尽渴心焦。","云移星月来幽隐，风转英茎下寂寥。","肝胆尘生知几日，齿牙病久起今朝。","篇章尽出樵苏鄙，不识鳌宫路径遥。"]},{"t":"寄史司理","f":"七言律诗","c":["日就妻孥问药囊，镜中自笑鬓毛苍。","诗编欲乞闲方记，茶面亲题病未尝。","饮量无涯倾北海，风情不薄念东阳。","终篇未尽相望意，洗耳风前迟报章。"]},{"t":"睦仲乞诗用其韵谢之","f":"七言律诗","c":["郁郁胸怀百未伸，道途容易学参辰。","桂科今日须吾子，鼎食当时况所亲。","景物依依吟晓色，讴谣细细问途人。","春风写寄南淮地，萧洒文章自细陈。"]},{"t":"和济叔兄书斋言志 其一","f":"七言律诗","c":["子夏今为河上居，诸生从此望夷涂。","圣贤事业长难合，仁义生涯未至迂。","盛德固能苏弊俗，明时安忍作潜夫。","鞭驽欲副新诗念，争奈曾参性质愚。"]},{"t":"和济叔兄书斋言志 其二","f":"七言律诗","c":["常因多病泣途穷，性命于今亦少通。","贵贱固宜常厥德，死生岂足动吾中。","游心自有诗书学，扶病须凭药石功。","否剥亦留归泰复，天时安得久屯蒙。"]},{"t":"和济叔兄书斋言志 其三","f":"七言律诗","c":["旅人汲汲赴前程，奔走川途不暂停。","踪迹无如今困蹇，才谋不似旧精灵。","雍容可羡云中雁，浩荡来随水面萍。","富贵功名皆外物，艰难险阻亦须经。"]},{"t":"和济叔兄书斋言志 其四","f":"七言律诗","c":["未得临流一醉观，江山应是怨无端。","苦吟夜月横诗笔，烂醉秋风把钓竿。","溪濑最宜霜后听，峰峦曾向雨中看。","输君瞬息穷千里，苒苒羁怀几万般。"]},{"t":"寓学芝山","f":"七言律诗","c":["鲸鹏未得遂南飞，翻学鹪鹩寄一枝。","翠石碧泉无尽处，冷蛩鸣雁不胜悲。","驱除穷困知何计，收拾功名竟几时。","穹昊不言难遽问，性情无奈祇吟诗。"]},{"t":"初秋晓起","f":"七言律诗","c":["云影冥蒙雨细飘，风传秋意又经宵。","苍溪岸侧千峰翠，高树枝头一叶凋。","病久亦伤光景速，起来尤爱暑威销。","徐徐步向亭中立，逸兴飘浮酒气骄。"]},{"t":"舟中作","f":"七言律诗","c":["晓日新晴三月天，征途令我一悽然。","谋身独愧声名浅，得地安辞道里千。","匹马荒山嗟困矣，扁舟浊水喜安然。","桐庐虽远今伊迩，魂梦先归绛帐前。"]},{"t":"寄张子直 其一","f":"七言律诗","c":["常愿从君授古书，血诚沥尽更无馀。","漂流岂意来深野，系滞无由后从车。","踪迹浸违南郡帐，梦魂长绕武侯庐。","仁人有意收庸贱，时寄声音一起予。"]},{"t":"寄张子直 其二","f":"七言律诗","c":["性质迂回趣向卑，此身敢望圣门归。","趋时已愧雕虫陋，学古还忧画虎非。","材近蓬蒿难自立，目无松柏竟谁依。","重嗟踪迹匏瓜系，翻羡苍蝇附尾飞。"]},{"t":"子直见和前韵因复之 其一","f":"七言律诗","c":["平时祇畏才无敌，今日方知器有馀。","一第已多新宦况，潜思犹入旧田庐。","凤凰固合栖阿阁，骐骥谁令驾鼓车。","千里青云今至矣，愿倾深画尽传予。"]},{"t":"子直见和前韵因复之 其二","f":"七言律诗","c":["淹延未得共山居，愁积胸肠万斛馀。","致远自伤无巨翮，临危谁肯借安车。","油幢金印男儿事，碧水青山隐者庐。","穷达计谋今已决，故人天际亦思予。"]},{"t":"戏呈子直","f":"七言律诗","c":["步入松筠水石间，回眸方觉世途难。","蒙茸草色萦行径，淩乱花阴覆钓湾。","暇日还能邀我醉，清时未肯纵君闲。","烹鲜酌酒且行乐，北圃春容今又残。"]},{"t":"寄献教授友兄","f":"七言律诗","c":["焦心犹觊就功名，痛惜长为疢疾婴。","欲起病躯思扁鹊，未知穷命问君平。","道途辽邈何由及，田壤萧条不复耕。","好学岂能几亚圣，受经从此愧丘明。"]},{"t":"千乘先生有草堂之吟而人或讥之因次其韵","f":"七言律诗","c":["世俗无轻好遁讥，先生岂是爱山扉。","圣人固重潜龙诫，君子安为即鹿非。","白水会来朝草径，红尘不敢傍麻衣。","金舆应有商岩梦，即听东南一诏飞。"]},{"t":"次道济韵","f":"七言律诗","c":["吾材未及明时用，来傍师门静养蒙。","多病因知妨力学，潜思犹是觊成功。","松心并老凝寒后，玉色相看烈火中。","天意欲令更患难，诗辞何必议穷通。"]},{"t":"病居婺女","f":"七言古诗","c":["荡漾扁舟冒晓征，此身何日得安停。","穷途敢恨身无托，多病惟思药有灵。","气谊腹心双古剑，江湖踪迹一浮萍。","尘埃易使羁容黑，仁义难邀俗眼青。","乡思浪凭歌笑解，微辞不是楚骚经。"]},{"t":"寄子直友兄秘书","f":"七言律诗","c":["碧水青山一万寻，不量无力强登临。","辛勤亦觊功名就，痛惜长为疾患侵。","憔悴已成今日态，英豪不复旧时心。","归期未遂家千里，空对秋风泪满襟。"]},{"t":"元夕与莘老俱宿斋因寄莘老","f":"七言律诗","c":["零雨其濛春始和，明星有烂夜如何。","笙篁故与风声远，灯火疑添月色多。","渐老自能忘世味，欲明更起看天河。","定留太一青藜照，愿寄荆人白雪歌。"]},{"t":"知常三十一致其政迁通直郎遇郊恩以亲之封封其祖父母以妻之封封其父母其外舅知府龙图安中以诗美之提刑大夫信叔和之俾某属和","f":"七言律诗","c":["立节秉心诚与俱，至诚少日慕颜徒。","荣名及祖亲仍与，盛事超今古亦无。","番国山川元润泽，吴园鱼鸟亦驩虞。","冰翁星使诗酬唱，在昔尝闻德不孤。"]},{"t":"承臬山毅夫提点学士有游会庾楼因用元韵","f":"七言律诗","c":["拥旃昔过赵州关，剖竹今邻四祖山。","问法几生成密记，焚香曷月礼慈颜。","知天稍似三无愠，易地何如五不还。","邂逅晦堂聊寄意，而今事事祇如闲。"]},{"t":"按涝","f":"七言律诗","c":["瘦马扁舟迹已勤，三乡行尽独伤神。","湖边围涨鱼龙富，野外田乾燕雀贫。","岂有异能裨此理，试留馀泽遗斯民。","东南步武丰凶别，却笑天心似未均。"]},{"t":"寄钱穆父","f":"七言律诗","c":["忠义文章见一门，风流窃喜得诸孙。","古人事业非无意，天下几微定有言。","寒斗雪霜松老大，高飞霄汉凤腾轩。","治功今日俱无补，尘土相看畏素飧。"]},{"t":"忆程公权","f":"七言律诗","c":["游从邂逅值王孙，万事无穷寄一真。","倾盖异时心似旧，望尘今日味如新。","清风遂别江山晓，润泽空馀草木春。","欲寄赠言终少取，独为瞻慕共斯民。"]},{"t":"尝约谊父同游龙泉奔走失期故作是诗奉和元韵","f":"七言律诗","c":["野寺幽幽隐翠岚，山川形势尽东南。","吟随野竹吾怀惬，醉啜溪泉此意堪。","乐事难并真可惜，登高能赋亦曾谙。","游从欲尽林间胜，雨气浑浑满古潭。"]},{"t":"古木","f":"七言律诗","c":["雨湿路岐泥滑滑，风吹江海水茫茫。","壮心弦直值吾道，孤宦蓬飞各异乡。","诗句好吟江上碧，酒卮已负菊边香。","丰年谁及农家乐，老稚驩讴自涤场。"]},{"t":"得庭佐岩夫二弟二书","f":"七言律诗","c":["十年翰墨共萤窗，万里忧勤鬓欲桩。","薄宦鹿埃寄南国，归心日夜度重江。","春风喜咏棠阴秀，夜月愁看雁影双。","病眼相望劳不彻，书来聊得此心降。"]},{"t":"贺兄长有子","f":"七言律诗","c":["鳷鹊曾将喜信来，奇祥昨夜出珠胎。","一枝始得龙孙贵，万里看成骥子材。","道路笑临诗首首，庭帏欢上酒杯杯。","风吹消息归江国，老稚应须眼为开。"]},{"t":"欲雨马上寄兄长","f":"七言律诗","c":["去马惊尘犯客襟，喜看云影聚轻阴。","雁飞浅草风声疾，蚁斗枯梨雨意深。","亭外见山输独啸，林边上马强清吟。","一声误认齐蝉晚，叫起肥陵夜夜心。"]},{"t":"暑雨","f":"七言律诗","c":["暑热炎炎起道途，霆雷一阵出山隅。","雨吹细点沾须鬓，风卷轻寒上发肤。","但使田畴终润泽，敢言车马久泥涂。","天时信有丰年意，笑语轻便共野夫。"]},{"t":"过紫金山","f":"七言律诗","c":["薄晚迟留问旧山，尘埃敢意紫金丹。","云生石眼千年润，风出云稍五月寒。","下蔡涂泥沾马足，长淮风浪触渔竿。","八公更有威灵在，簿领应须笑贱官。"]},{"t":"拟赏花钓鱼诗 其一","f":"七言律诗","c":["晴云扶日上昭阳，翠辇鸣鞭下建章。","化国楼台天半际，瀛洲殿阁水中央。","鱼游自并龟龙国，花气浑如薝卜香。","拟学华封人作颂，千秋万岁奉君王。"]},{"t":"拟赏花钓鱼诗 其二","f":"七言律诗","c":["琉璃宫殿云深处，锦绣池堂雨过时。","鱼跃定名千岁鲤，花开多是万年枝。","恩流河汉波澜阔，春在蓬瀛日月迟。","三十馀年无此会，今朝会见柏梁诗。"]},{"t":"拟赏花钓鱼诗 其三","f":"七言律诗","c":["孔雀横斜宝扇回，雕龙浮动翠舆来。","鱼知迎日争先跃，花会留春独后开。","法部方将九成乐，侍臣迭送万年杯。","太平恰似唐虞际，臣主从容赋起哉。"]},{"t":"拟赏花钓鱼诗 其四","f":"七言律诗","c":["翠跸雕舆下未央，禁林春色秀天芳。","帝居便是蓬莱胜，花气浑如薝卜香。","五色灵池鱼拨剌，九苞阿阁凤徊翔。","神仙世界光阴别，比着人间一倍长。"]},{"t":"拟赏花钓鱼诗 其五","f":"七言律诗","c":["日暖鱼游百子池，雨馀花折万年枝。","微风静觉丝缗远，暖日徐看淑景移。","九奏高张洞庭乐，七言遍赋柏梁诗。","吁俞不忘几微戒，恰似唐尧虞舜时。"]},{"t":"拟赏花钓鱼诗 其六","f":"七言律诗","c":["甘雨祈祈兆岁丰，君王暇豫与人同。","晴阳鱼跃烟涛外，暖日花开锦绣中。","更有灵龟千岁绿，仍多陈粟万仓红。","便知岂乐歌颁首，不比飞扬赋大风。"]},{"t":"拟赏花钓鱼诗 其七","f":"七言律诗","c":["百子池塘春复还，五云楼阁晓犹寒。","蛟龙影上黄金辇，锦绣香浮白玉盘。","宿蕊万包开雨露，修鳞五色跃波澜。","太平既醉恩无报，白首侵寻畏素餐。"]},{"t":"拟赏花钓鱼诗 其八","f":"七言律诗","c":["槛外幽花暖欲然，池边弱柳困初眠。","风晴莺戏长杨日，水净鱼游太液天。","玉斝酒深浮湛露，宝炉香聚引长烟。","云章光绝无能继，但颂南山亿万年。"]},{"t":"拟赏花钓鱼诗 其九","f":"七言律诗","c":["霁色苍茫杳蔼中，玉舆朝出大明宫。","修鳞戏跃神池日，宿蕊争开禁籞风。","韶乐大恩流动植，灵台馀泽入鱼虫。","龙光所被何其厚，欲报惭无尺寸功。"]},{"t":"拟赏花钓鱼诗 其十","f":"七言律诗","c":["九重殿阁五云中，閒暇君臣燕乐同。","芳卉便成金色界，游鳞如在水晶宫。","承云乐见太平象，湛露诗成王者风。","从幸甘泉能献赋，愧无人可似扬雄。"]},{"t":"题醒心亭","f":"七言律诗","c":["红尘万里困征鞍，喜向幽亭一倚栏。","日夜水声趋涧曲，西南山色上云端。","窗横古木秋阴老，槛逼苍崖雨气寒。","搜尽肺肠吟不竟，欲君亲置画图看。"]},{"t":"谨次知县奉议","f":"七言律诗","c":["早日苍茫杳霭中，绣衣綵旆照花骢。","路从古汴聊分北，家在琅琊更近东。","大野晓行千嶂月，长河朝济一帆风。","赐环不独邦人愿，名字从来重两宫。"]},{"t":"次来韵","f":"七言律诗","c":["山川不见石泉城，风日摇摇想旆旌。","鸑鷟老寻丹穴宿，骅骝饥上赤霄行。","隆冬霜雪伤萍泛，末路埃尘忆盖倾。","父老祇知荣衣绣，乡人未会贵登瀛。"]},{"t":"拙句送通判学士正夫","f":"七言律诗","c":["山谷冥冥多雪霜，人情随处不悲凉。","綵衣公独有老母，乔木我今思故乡。","行酒赋诗不忍别，登高临远便相望。","故乡虽好莫留滞，日月其除行路长。"]},{"t":"长沙道中寄君时","f":"七言律诗","c":["少时惜别惟男女，老大相思味尤苦。","时节愁深聚作云，道途泪落纷如雨。","梦魂章水去无时，书信蒲山来有数。","几时与汝归去来，綵服相看老农圃。"]},{"t":"和文渊游馀干山寺","f":"七言律诗","c":["爱山终日在山巅，山径迟留几屐穿。","涧水曲流随步屧，炉香深处作云烟。","峨峨健马横岩石，漠漠苍龙宿旧渊。","为语琵琶洲上路，几时容我系归船。"]},{"t":"道中每至山寺辄迟留久之","f":"七言律诗","c":["杖屦徜徉信所之，偶逢佳致即忘归。","舟帷不系东西去，云似无心在处飞。","岁月漫能催我老，江山可复与人违。","一廛未足南陔志，静笑浮生事事非。"]},{"t":"武冈驿","f":"七言律诗","c":["行路萧条伤客心，黄云不动祇阴阴。","天寒独鹤飞平泽，日暮慈鸦归故林。","鳞翼不将一字至，雪霜莫怪二毛侵。","拥炉更饮钟陵酒，抱膝漫为梁甫吟。"]},{"t":"依韵和萧推官见贻推官字子方知桂州修撰字子善相及喜论兵尝见于鄱阳","f":"七言律诗","c":["晚年相遇更堂堂，祇似当时鄱水阳。","物论固非低阀阅，家声元自满湖湘。","风回獠俗归陶冶，囊括蛮州入井疆。","使指质成非有用，赠言虚自辱圭璋。"]},{"t":"寄佛印","f":"七言律诗","c":["菩萨化成瑶象车，超腾倏忽到云居。","提携满钵雕胡饭，供养一箪明月珠。","称我姓名日专甲，问师安否近何如。","即今无病无言说，还有人能致问无。"]},{"t":"清江闻提举承议先行驰寄小诗","f":"七言律诗","c":["一水相忘复此时，世情岂故与人违。","江湖雨涨潜鳞去，霄汉云深画鹢飞。","晓月正思公共载，春风好与我同归。","别来道味知何似，丹灶黄芽想更肥。"]},{"t":"走笔和萧推官迎提举承议 其一","f":"七言绝句","c":["青山远远水回回，初见钟陵城上台。","将迎不独儿童喜，杨柳看人亦眼开。"]},{"t":"走笔和萧推官迎提举承议 其二","f":"七言绝句","c":["画舫急随江上鸥，犹嗟不及水先流。","欲知今日陈雷社，不数当时李郭舟。"]},{"t":"又和治居许昌诗 其一","f":"七言律诗","c":["事与心违即挂冠，逍遥芝朮长童颜。","黄金晚去云中阙，员峤深游海上山。","平日以身当国论，老年将梦比人间。","文章气力终豪健，四韵诗来倚马还。"]},{"t":"又和治居许昌诗 其二","f":"七言律诗","c":["闻说当年鹓鹭班，谏书无数慰龙颜。","水横颍首归新第，云断峨眉忆旧山。","漫有新诗名海内，曾闻雅乐献河间。","西湖今日春应好，想见扁舟载月还。"]},{"t":"途中寄君时弟 其一","f":"七言律诗","c":["邮亭车马日纷纷，可遂尘埃老此身。","燕子恰如曾宿客，雁奴犹是未归人。","晚云明灭初收雨，朝日阴晴拟放春。","花木一时浑自好，寄声华发莫争新。"]},{"t":"途中寄君时弟 其二","f":"七言律诗","c":["天晴日驭去迟迟，恰是春风中半时。","柳色笑花须似锦，雨声欺雪故如丝。","迁乔他日吾求友，发药明朝汝得师。","乐事信知人不及，异乡同有拜亲期。"]},{"t":"次君时韵","f":"七言律诗","c":["牙弦不愿世人知，末路论心有子期。","万物参差为我与，三人邂逅得吾师。","更贫未乏扬雄宅，已会谁悲墨子丝。","欲说本来时节事，直须会得未来时。"]},{"t":"寄检法奉议","f":"七言绝句","c":["长春月月与玫瑰，烦近萱堂仔细栽。","却语花开无造次，老亲寒食以前来。"]},{"t":"老儿挈幼小将及邓因寄君时弟 其一","f":"七言律诗","c":["莫言法法与尘尘，祇论而今见在身。","婆子台山能护物，厮儿临济最疑人。","阿那含果多生叶，优钵罗花别样春。","须认铁牛楼上语，一回几看一回新。"]},{"t":"老儿挈幼小将及邓因寄君时弟 其二","f":"七言律诗","c":["长年骑马走风尘，扰扰犹知梦幻身。","野柳最怜青绶客，山桃莫笑白髭人。","照溪七里亭边晚，近郭百花洲上春。","捉麈即从君道旧，浮蛆更许我尝新。"]},{"t":"和范学士 其一","f":"七言律诗","c":["红尘投老倦征鞍，梦寐清规祇厚颜。","论德每疑观大水，言诗曾赋仰高山。","退之自处轲雄后，甫也当居扬马间。","知止旧风衰久矣，只今须合为公还。"]},{"t":"和范学士 其二","f":"七言律诗","c":["酒榼棋枰足燕闲，市朝愁复抗尘颜。","曾非学道随东鲁，可怕移文累北山。","花烛园林春半际，烟波亭榭水中间。","篮舆想见公游处，颍水何时听我还。"]},{"t":"寄致政侍郎","f":"七言律诗","c":["孔门弟子数三千，用舍行藏独与颜。","委曲百川终至海，辛勤一篑欲为山。","是非扰扰俱身外，生死悠悠亦梦间。","漫爱隐居多气味，扁舟今欲与公还。"]},{"t":"又书怀","f":"七言律诗","c":["锦江蟠泊落云端，秀气全分在尔颜。","少日大鹏飞北海，清时片玉出昆山。","心存魏阙安危际，名在丹台伯仲间。","昨夜泸渝初奏捷，巅崖谁为勒铭还。"]},{"t":"中丞温伯杂端持正与其僚出祖正孺端伯于刘元忠宅某即席赋诗","f":"七言律诗","c":["蜀山想见去程兼，满眼春风别兴添。","光动酒船浮玉雪，味调羹鼎足梅盐。","竹枝堕影低垂砌，花叶吹香细入帘。","更欲稍留山简醉，应须少霁弱翁严。"]},{"t":"翌日景繁察院公初叔明推直谦父主簿复会某晚至即席用前韵 其一","f":"七言律诗","c":["鼎食参差海陆兼，炉烟浮动麝兰添。","纷纷不及同朝饮，草草犹能共暮盐。","最爱梅香频倚槛，欲留槐影更褰帘。","驿途即折垂杨别，酒令毋嫌细柳严。"]},{"t":"翌日景繁察院公初叔明推直谦父主簿复会某晚至即席用前韵 其二","f":"七言律诗","c":["银鱼朱绂綵衣兼，稍觉公行气象添。","白水长时云似雾，青泥三月雪如盐。","诗成曷日传邮置，书就他时奏陛帘。","更为朝廷问幽仄，人材岂遂乏杨严。"]},{"t":"送桂阳令臧祖道","f":"七言律诗","c":["莫笑长官权势轻，所怀端可及生灵。","勤忧每见朝尝胆，劝恤遥知夜戴星。","礼节但能坚玉石，清名亦合上丹青。","饯行欲以言箴赠，留作君家座右铭。"]},{"t":"中丞温伯杂端持正约同饯夷仲不克某独出城重阳后一日","f":"七言律诗","c":["宛转平林十里开，天晴更喜少风埃。","桃花笑摘篱边菊，竹叶惭无马上杯。","更欲看君横奋迅，不应如我久低徊。","闾阎蛰蛰忧昏垫，侧耳乘骢御史来。"]},{"t":"和提点少卿诗韵","f":"七言律诗","c":["文场俱是出群雄，曾颂鸿毛遇顺风。","稍记螭头初赐第，渐惊鹤发欲成翁。","老年翰墨才仍敌，故国溪山路更同。","存殁感怀浑梦寐，会须推付酒樽中。"]},{"t":"和提点少卿喜雪诗韵 其一","f":"七言律诗","c":["曲岸沧洲一水涯，轻舟欲访戴逵家。","城隅寂淡梧桐月，溪岸萧骚芦苇花。","润泽便知年事足，清明更爱晓晴佳。","园林已有春来信，笑看浮生鬓欲华。"]},{"t":"和提点少卿喜雪诗韵 其二","f":"七言律诗","c":["同云漫不见津涯，雪雾参差似一家。","辛苦宋人成楮叶，殷勤驿使寄梅花。","润沾南亩从横阔，寒助西山晓夕佳。","三白更同千乘喜，屡丰吾亦有光华。"]},{"t":"久雨和张季友寄程德林时季友得环倅程受婺源未赴","f":"七言律诗","c":["寂寂不闻车马声，泥途无亦畏逢迎。","引觞自放连朝醉，挥麈遥思一座倾。","傅野好为三日雨，杜陵莫醉百忧行。","西南俱说催征辔，却愿双轮四角生。"]},{"t":"和张季友正夫归因为诗寄","f":"七言律诗","c":["曲曲幽林远远山，归与谁得似公安。","定为五柳先生传，应笑三年博士官。","上国尘沙随马箠，长溪风浪属渔竿。","秋风喜得音声到，起对青灯子细看。"]},{"t":"寄妻兄宁文渊时广西方用兵而文渊谪官在广东","f":"七言律诗","c":["有客迟留瘴海边，白头想见欲潸然。","淹留每笑犹千里，芘藾遥知有二天。","行听伏波平岭峤，已闻下濑济楼船。","几时幽谷灵芝路，水石相看稳昼眠。"]},{"t":"送郭知章宰浮梁 其一","f":"七言律诗","c":["万室喁喁望已深，临流不敢重分襟。","闾阎早觉春风到，岩谷遥思昼日临。","制御古非无至策，爱调人自有良心。","笑言已得公才敏，侧耳风前听好音。"]},{"t":"送郭知章宰浮梁 其二","f":"七言律诗","c":["仕宦悠悠今几年，初分一邑走江边。","凤飞远水颠崖地，鹤唳清霜皓月天。","潇洒渊明多种秫，从容子贱数鸣弦。","秋风坐看车辕速，一梦归争鸟翼先。"]},{"t":"和李潜夫同年并简宁文渊时二君在鄱阳","f":"七言律诗","c":["我贱无庸如子何，白头相望欲悲歌。","少年策在英豪腹，清世名专守相科。","薄宦从容忧自少，故人邂逅乐应多。","秋风不见北归信，东顾苍茫临大河。"]},{"t":"送徐望之郎中提举舒州灵仙观","f":"七言律诗","c":["江濒远别几秋萤，汴曲相逢眼更青。","予志自能同豹变，弋人安得望鸿冥。","风流绿蚁千钟酒，香火黄庭一卷经。","祇恐诸公还荐鹗，未容轻去老岩扃。"]},{"t":"送提点少卿丈还鄱阳","f":"七言律诗","c":["秋风吹雨响梧桐，南岸遥山翠几重。","稍爱楼台足清旷，可怜樽俎未从容。","三溪天外横新水，五老云间出旧峰。","邂逅一舟吾亦往，登临还复与公从。"]},{"t":"奉和提点少卿来章","f":"七言律诗","c":["场屋当年翰墨亲，故乡相别九年春。","相如旧有凌云赋，居士今惟净法身。","素节直须深爱惜，高材未必竟沉沦。","祇疑龙去须为雨，不似区区尺蠖伸。"]},{"t":"呈运判学士 其一","f":"七言律诗","c":["邂逅江滨宿使航，五更窗外月犹黄。","因陪谈麈殊优远，自反机心愈渺茫。","老马但羞千岳阻，病翰孰与九皋翔。","明时赖有吾宗在，敢学西邻便涕伤。"]},{"t":"呈运判学士 其二","f":"七言律诗","c":["相望冰壶江水滨，渴心枯涸欲生尘。","忽逢使节何胜喜，又说宗乘得愈真。","鬓里雪霜经岁有，眼前风浪与时新。","茫然未有归田计，愧以穷通问故人。"]},{"t":"和十二法曹","f":"七言律诗","c":["秋来初得兔园书，更有诗来慰索居。","出宿几时吾税驾，归宁何日尔脂车。","贫如原宪元非病，懒比嵇康老更疏。","鸿雁池边知可乐，鹡鸰原上正相胥。"]},{"t":"次韵晦之沿牒楚泗二州","f":"七言律诗","c":["鹢首争先鸟翼飞，宦游容易即天涯。","渐生世事无由尽，已去年华不易追。","芍药遂输淮上乐，樱桃终念水边期。","雨馀亭外山争出，几日相看一酒卮。"]},{"t":"苦吟","f":"七言律诗","c":["苦吟遂见诗锋锐，独乐宁思饮社豪。","别去性情生淡泊，老来风致长清高。","纷纷行李君休叹，琐琐乘田吾正劳。","争似扁舟碧江上，几回风物入秋毫。"]},{"t":"晚风","f":"七言律诗","c":["南北东西万里通，往来长与水无穷。","役心一日空隋力，馀泽千年谢禹功。","满道柳阴低翠幄，夹堤桥影卧长虹。","乐游不及先生快，坐看千航起晚风。"]},{"t":"四方","f":"七言律诗","c":["四方难缀游人足，万里无嗟客子蓬。","红满桃花生细浪，白翻蘋叶起清风。","路当吴楚尘相接，源出淮夷势未穷。","闻说夜吟清不尽，月明如近水晶宫。"]},{"t":"病中寄妻兄宁文渊","f":"七言律诗","c":["百年流转寄风波，老态欺人病更多。","赖有子能知管仲，即无人可向维摩。","悠悠世味祇如此，扰扰人生能几何。","南北有时归计就，考槃终欲共山阿。"]},{"t":"和晦之所感","f":"七言律诗","c":["万物初还白帝秋，新寒苒苒上衣裘。","红泥烂醉须千日，皓发悲吟漫四愁。","气挹风云诗易取，分投胶漆意难酬。","簿书久废游从乐，最负江山翠满楼。"]},{"t":"送济叔兄","f":"七言律诗","c":["风起青蘋去鹢催，江山无路笑言陪。","泪生病眼朝千里，愁入枯肠夜九回。","秋水忍看鸿独宿，春风好与燕俱来。","别期重有文章约，老稚应须眼为开。"]},{"t":"送樊秀才召倪先生","f":"七言律诗","c":["群言分散寄遗经，天乞吾侪照未明。","犹惜是非迷后世，旁求规矩遗诸生。","骐驎始信能千里，雕鹗终须看一鸣。","杖屦从容问孤迹，为言心寄海边城。"]},{"t":"治平谅闇元夕 其一","f":"七言律诗","c":["上元无乐送长宵，泪洒城阳泣帝尧。","云障月华寒淡薄，风吹雨点细飘摇。","物随世事生悽怆，天与人心长寂寥。","不用灯花斗光景，火炉诗笔慰无聊。"]},{"t":"治平谅闇元夕 其二","f":"七言律诗","c":["仙乐谁家奏管箫，异香到处合椒聊。","风生雨后声悲惨，月在云间影动摇。","幽径小溪春寂寂，淡灯寒烛夜寥寥。","香焚敢效封人意，睿算年年祝帝尧。"]},{"t":"寄济叔兄长","f":"七言律诗","c":["东南路径走江淮，万里波声日夜回。","流水会将孤梦去，游鳞不寄尺书来。","风吹云影东西散，雨点花枝在处开。","节物伤人心总碎，一春归兴满兰陔。"]},{"t":"次致政张大夫韵二首 其一","f":"七言律诗","c":["石城山水有清音，贾堑烟萝路更深。","松竹门阑初作径，蒲荷池沼旧成林。","騑騑出适穷周道，汩汩归休傍汉阴。","莫诧大夫能作赋，但逢故老数挥金。"]},{"t":"次致政张大夫韵二首 其二","f":"七言律诗","c":["李郭曾同溪上船，途人指点作神仙。","松篁老长芰荷密，凫雁飞浮鸂鶒前。","霖雨未终岩野地，阳春方擅郢中天。","文章不敢兰亭比，翰墨才能记岁年。"]},{"t":"宴亭一首","f":"七言律诗","c":["未得从君醉宴亭，坐无酒意正醒醒。","云飞野壁春心远，蝶误花枝昼梦惊。","草履踏泥寻曲径，纱衣冒雨上重城。","金丝不厌幽闺地，时向高风叶一声。"]},{"t":"皇甫乞诗为赠因次其韵","f":"七言律诗","c":["忆昔丹书下粉闱，诸公接武上瑶池。","势淩雕鹗双鸿翼，香满蟾蜍一桂枝。","议论所存无赘学，声华此去有真知。","风松无限溪山乐，时倩秋风寄数诗。"]},{"t":"合肥府学中赓诸公韵和正寺翔甫总翠亭","f":"七言律诗","c":["危亭缥缈压城端，总拾澄虚入画栏。","地势西连金斗峻，山容东际湫湖寒。","行瞻日月光华近，坐觉乾坤器度宽。","闻说南州画工在，可能收作一屏看。"]},{"t":"和济叔灯花","f":"七言律诗","c":["灯花一点照花枝，今夕相看孰是非。","冷艳几时开密室，春光半夜到重闱。","稚儿戏蹙寒心落，羁妇争持喜信归。","寄语帘风莫催促，冷吟赢得看芳菲。"]},{"t":"杂咏诗 其一","f":"七言律诗","c":["诗轴亲题乞一寮，清心洗濯渴心焦。","云移星月来幽隐，风引英茎下寂寥。","肝胆尘生知几日，齿牙病起自今朝。","疏愚强笑为生计，不识鳌宫路径遥。"]},{"t":"杂咏诗 其二","f":"七言绝句","c":["朔风吹雪满天涯，寂寂朝云冷万家。","试步城头望坊巷，玉枝无处认梅花。"]},{"t":"苦旱和俞都官","f":"五言律诗","c":["焚烧纵炎日，长养误薰风。","责己君临厚，劳心县宰忠。","十州饥馑后，万里郁陶中。","欲寄精诚祷，天心或可通。"]},{"t":"上留守侍读生辰","f":"五言古诗","c":["素节于今杰，青春此日生。","地还坤德重，天给露华清。","鸿鹄飞昭旷，骐驎瑞太平。","云浮朱槛细，星入画图明。","簪绂师先进，旒綖望老成。","千龄逢盛际，万里起修程。","客献南山颂，人期北户荣。","学高才称副，仁厚福兼并。","香荐芝兰秀，诗言犬马诚。","祝公比松柏，早晚席台衡。"]},{"t":"九日独登城上台感怀寄兄长 其一","f":"七言律诗","c":["九日独登城上台，南山望尽祇尘埃。","黄华虽富纷纷菊，绿蚁谁同滟滟杯。","时节独催双鬓雪，利名还见此心灰。","池阳星子多朋旧，能有音书万里来。"]},{"t":"九日独登城上台感怀寄兄长 其二","f":"七言绝句","c":["孤城幽谷晚烟重，事绪无过与此同。","寒夜独吟风静后，扁舟应宿月明中。"]},{"t":"九日独登城上台感怀寄兄长 其三","f":"七言绝句","c":["秋来常苦客飘蓬，身羡归鸿飞复东。","欲问江南是何处，乱山扰扰自无穷。"]},{"t":"和应诏吟","f":"七言律诗","c":["又得华笺是浣溪，短窗翰墨自光辉。","寒梅不动情相炤，幽鸟无声意欲飞。","数四恩嘉成海渎，百千文字粲珠玑。","风花未称相望意，特为君王述万机。"]},{"t":"秋风","f":"七言律诗","c":["风战江湖飞断梗，露零霄汉听征鸿。","身虽流俗志万里，昔是少年今老翁。","双眼久因尘事黑，病颜今为酒樽红。","夜深胡蝶归魂梦，飞尽蓬瀛岛屿中。"]},{"t":"山林","f":"七言律诗","c":["鹤瘦松枯不自禁，穷愁千万欲相侵。","山林谁识谢公意，风月独高梁甫吟。","行视水痕嗟未息，静看云影爱无心。","懒随尘土趋时态，欲就丝桐丐古音。"]},{"t":"船中见庐山","f":"七言绝句","c":["翠色苍茫杳蔼间，船人指点是庐山。","浮云作意深藏护，未许行人取次看。"]},{"t":"浩歌","f":"七言律诗","c":["歌尽绿洲千古意，陶然初到性情真。","试临华岳题诗笔，欲走沧浪买钓纶。","苔润一瓢贫气味，草荒三径久埃尘。","我心自有青云在，安得羁留浊水滨。"]},{"t":"壮心","f":"七言律诗","c":["锐气销磨一水平，壮心非欲避功名。","穷通有属都天意，忧乐无端自物情。","拂地延留山月影，褰帘收拾水风声。","清吟又得松陵侣，谁惜花前酒重倾。"]},{"t":"大笑","f":"七言律诗","c":["大笑花开倾屈卮，狂来不惜典春衣。","飘浮世态知惟我，淡泊天真得者稀。","云汉露寒沾玉液，江天风静拂金徽。","樽罍易竭情无尽，海岳苍茫一梦飞。"]},{"t":"步入","f":"七言律诗","c":["步入浮游淡泊中，红尘无计到心胸。","微之散落诗千首，白也飘零酒百钟。","天地寂寥窥夜月，风霜悲惨看春松。","清晨试引青铜照，一点朱丹入病容。"]},{"t":"师言","f":"七言律诗","c":["尝就师言卜所从，万为都起至诚功。","天枢亹亹时长北，溪水悠悠夜亦东。","陋迹已生千古后，微怀方醉六经中。","竹林交友多才力，应念南轩一病翁。"]},{"t":"县舍小饮因就伯逢求馔具","f":"七言律诗","c":["霜凋老木青枫碎，雪尽空山夜月新。","收拾村醪欲歌笑，咨嗟破突久埃尘。","分为白屋穷宾客，回眷青云旧主人。","天地苦寒今有备，醉横诗笔觉精神。"]},{"t":"累承见酬因谢之","f":"七言律诗","c":["千夫拱默看文阵，百战纵横及醉乡。","齐晋亦当忧鲁弱，韩吴终是怯秦强。","威容敌国矜豪迈，气压羸兵急遁藏。","他日相期坐帷幄，为君穷力破戎羌。"]},{"t":"匪躬先之桐庐因作诗送之","f":"七言律诗","c":["男子生当自树立，莫令寂默终无名。","膏粱孰与文章乐，锦绣不如仁义荣。","予病淹留岂得已，子今閒暇固当行。","竹林交契知安否，议论从容为寄声。"]},{"t":"次韵晦之楚泗道中","f":"七言律诗","c":["白日红尘身世劳，羡君诗兴自陶陶。","敢因锦绣邀青玉，漫把瑶琼报木桃。","冰雪正寒心始见，骐驎已老气终豪。","一言起拜先生辱，羞愧无才及楚骚。"]},{"t":"暮雨","f":"七言律诗","c":["暮雨忽随江上舟，寒风彷佛转清秋。","兴随烟月成千首，醉忤莺花长四愁。","不系可怜波上叶，忘机应喜海边鸥。","一声画角吹魂梦，散落淮天晓未收。"]},{"t":"扁舟","f":"七言律诗","c":["扁舟满眼送波涛，一夜霜华上鬓毛。","雨脚已收朝日薄，潮头忽上晓风高。","江山须信游人乐，簿领还知俗吏劳。","见说指挥功利白，馀才今见解牛刀。"]},{"t":"欲寄","f":"七言律诗","c":["欲寄予声无使还，平安始见一书间。","偶从淝水经淮水，应对龟山忆蜀山。","浮世并知俱物役，利途曾复见人闲。","每言庾信愁难解，果道安仁鬓已斑。"]},{"t":"古庙","f":"七言律诗","c":["严严遗庙水岩幽，想像迟回物为秋。","堂陛终须辨臣主，山河空复誓王侯。","地全东海疑先兆，力尽淮阴意未休。","可恨游人满门下，不将敧器与君谋。"]},{"t":"楚野","f":"七言律诗","c":["楚野云寒山点缀，淮天波尽水徘徊。","古今寥廓归谈笑，气象纵横费剪裁。","愁日远随双锦翼，离情满寄百金杯。","清风正引城头望，淮上车音几日来。"]},{"t":"次韵刘景文见寄","f":"七言律诗","c":["万里飘蓬失旧游，汴堤别去又三秋。","朔风怅望心先去，夜月相瞻影独留。","偶得篇章还自失，喜因文字会忘忧。","几时樽俎追平昔，熟醉灵芝最上头。"]},{"t":"题程则之瑞墨阁","f":"七言律诗","c":["仁宗事业望唐虞，翰墨仍兼八体书。","长叹仙游今寂寞，不知遗迹在樵渔。","凰鸾影落新安水，奎壁光临处士庐。","北望昭陵云杳霭，倚栏双泪染衣裾。"]},{"t":"将及下蔡寄仲求","f":"七言律诗","c":["不见大夫行五年，渡淮欲见泪潺湲。","忧怀荏苒今衰矣，仕宦迟回亦偶然。","眼看飞云难自定，身随去鸟拟争先。","更鞭驽马登横岭，即借长桥济大川。"]},{"t":"九日同仲求登高有感","f":"七言律诗","c":["曾侍灵芝九日觞，登高从此共凄凉。","故乡江外烟波阔，上国云中道路长。","世事祇催蓬鬓雪，秋风不减菊花黄。","坐看鸿雁天涯远，甘醉茱萸盏面香。"]},{"t":"别子容","f":"七言律诗","c":["衣衫尘土待光辉，议论渊源慰渴饥。","鄙远尚思同旧学，疲驽常恐误真知。","壮怀销落非前日，孤宦邅回强此时。","万事纷纷知有在，斋心更欲问蓍龟。"]},{"t":"自北归夜梦侍亲闱久之既觉感而成诗","f":"七言律诗","c":["中宵八九梦亲闱，笑逐儿童戏綵衣。","起觉片身犹逆旅，化为双泪落征衣。","祇嗟轻逐孤蓬转，安得争先去鸟飞。","薄宦自伤无以养，亦知从昔戒脂韦。"]},{"t":"兄弟约芝山共学未暇辱以诗督之因次元韵","f":"七言律诗","c":["弟兄相寄玉为音，洗尽尘埃一寸心。","欲以蚊虻看势利，能将珠璧现光阴。","雅游潇洒知难废，故约迟留惜未寻。","北望灵芝山在处，暮云回合碧沈沈。"]},{"t":"读书","f":"七言律诗","c":["读书虽苦亦何知，仕宦纷纷强此时。","旧学望君真短短，新诗爱我已枝枝。","清生野槛晨风远，暖度山窗昼日迟。","出处从今能自卜，不庸蓍蔡已无疑。"]},{"t":"清明日仲永游荐福先秋亭晚过芝山他日有坐客献诗者仲永见率同和","f":"七言律诗","c":["行背林梢转水湾，乐游与物共安闲。","旌旗影散烟波上，金竹声流岛屿间。","宿雨未乾花焰焰，晨风不动鸟关关。","久晴见说春尤好，何日重来访旧山。"]},{"t":"送邹秘丞广汉赴御史","f":"七言律诗","c":["清论从来满士林，君王今日为虚襟。","谋维已熟言难废，势位虽隆望亦深。","可否谨须要至理，穷通知不异丹心。","北风会到江南路，日上城头听好音。"]},{"t":"广汉言事得陵州仁寿县将以诗迎之","f":"七言律诗","c":["昨日除书下禁林，诏言明白洒宸襟。","诚留魏阙初非浅，望系朝廷晚更深。","议论自关天下计，功名非系古人心。","秋风行李归来未，旦暮虚怀迟玉音。"]},{"t":"次张同年德父移松杉石楠海棠各赋一首 其一","f":"七言律诗","c":["孝思知欲寄无穷，手插松枝宅兆东。","始听灵根来涧底，会看高节入云中。","纷纷泪滴枝头露，扰扰愁随叶上风。","老尽雪霜终不变，亦知因此议穷通。"]},{"t":"次张同年德父移松杉石楠海棠各赋一首 其二","f":"七言律诗","c":["张子纷纷非世情，栽杉为径护坟茔。","烟冥接叶愁俱满，露落低枝涕泗横。","直干森森才满握，微阴细细欲盈城。","栽培会与风霜老，爱护无容蝼蚁生。"]},{"t":"次张同年德父移松杉石楠海棠各赋一首 其三","f":"七言律诗","c":["石楠梭木照春山，颜色纷纷乱碧丹。","剩叶如云散幽冢，清阴为盖覆灵坛。","沾濡细雨生秋色，摇撼惊风长夜寒。","应并孤松长共老，好栽慈竹与同看。"]},{"t":"次张同年德父移松杉石楠海棠各赋一首 其四","f":"七言律诗","c":["见说无因寄孝心，自移花种碧山岑。","栽培蒙密春先暖，想像迟回日为阴。","多恨祇悲新雨露，遗灵如得旧园林。","黄鹂不会人情思，亦向枝头送好音。"]},{"t":"寄学芝山正叔寄诗有想叹之意次元韵","f":"七言律诗","c":["想望独登城上台，重云不见首勤回。","久分笑语心几塞，忽得诗书眼为开。","草褐岸巾随鹿豕，佳山野水外尘埃。","公名方与风霆远，未可窥余寂寞来。"]},{"t":"诗寄兄长并示十二十四舍弟","f":"七言律诗","c":["去年马走途中雪，今日舟行湖上风。","吾分自天俱有定，此忧如水自无穷。","谁知云汉双飞雁，自笑江湖一断蓬。","祇有綵衣情最乐，复嗟不与弟兄同。"]},{"t":"夏六月公济与弟六人游安国竹园某有诗","f":"七言律诗","c":["万竹纷纷光欲流，花亭况在竹林幽。","阴藏绝径为深谷，风起炎天见早秋。","此地遂为千亩胜，吾侪非止七贤游。","清凉可爱无朝夕，无问昏鸦故未休。"]},{"t":"晚行竹林兄弟相率赋诗 其一","f":"七言绝句","c":["苒苒秋风吹我衣，留连清胜夜忘归。","眉横云外新蟾上，雪落林梢白鹭飞。"]},{"t":"晚行竹林兄弟相率赋诗 其二","f":"七言绝句","c":["碧竹侵云一万竿，挟书时此共盘桓。","湘沅见说官期逼，预惜朋游别去难。"]},{"t":"某在合肥尝梦同子直在横川旧游递中有诗往还子直见招因用前韵来寄","f":"七言律诗","c":["春风把酒共溪边，南北纷纷遂五年。","绿绶终朝寄尘俗，青云昨夜梦神仙。","诗多老格知难继，易外新闻念未传。","彷佛异时佳句在，吾游不敢负横川。"]},{"t":"汴水呈祖道","f":"七言律诗","c":["万事无庸轻是非，扁舟吾与子同归。","不知心逐征云远，安得身先去鸟飞。","月入江湖生夜色，风吹花木长春晖。","鬓毛每笑多新雪，衣带频惊缓旧围。"]},{"t":"和祖道见致政王中允题壁","f":"七言律诗","c":["里巷参差一水间，水边相失复三年。","旧题想见风规好，清隐传闻志尚贤。","道路尚能谈旧事，林泉宁复挂尘缘。","迟回禄仕予真怯，不独无君郭外田。"]},{"t":"江口道中","f":"七言律诗","c":["道路春晴柳叶长，川原水涸草菰黄。","阴晴天气犹寒食，村郭人家似故乡。","地旷马牛群放牧，时平儿女自耕桑。","马蹄即踏江南路，村店相看酒一觞。"]},{"t":"和祖道渡江","f":"七言律诗","c":["归上慈亲酒一觞，吾荣不啻插麾幢。","雨沾马辔行春野，风满舟樯泛晓航。","江路好山随步履，人家流水照轩窗。","梅仙不怪多诗思，莺语纷纷燕子双。"]},{"t":"晓行","f":"七言律诗","c":["迟明骑马听鸡号，雾露纷纷上鬓毛。","烟宿平芜疑远水，风鸣高木听飞涛。","暖回宿草春初见，光动扶桑日欲高。","横笛一声还出牧，稚儿无不笑吾劳。"]},{"t":"和致远登楼有感","f":"七言律诗","c":["昔人已劝莫登楼，年少登楼应白头。","鳷鹊雪残冰尚泮，蓬莱云静月如流。","灯棚影阔明千里，乐部声长在十洲。","万物莫如公最乐，诗情应祇为民忧。"]},{"t":"赠陈扩秀才","f":"七言律诗","c":["原宪家无金玉储，生涯惟有一床书。","众人清论谁知子，终日高谈谢起予。","叔夜未尝闻喜愠，伟容如不辨亲疏。","丈夫当重功名计，天子重阍好曳裾。"]},{"t":"寄子文友","f":"七言律诗","c":["古人湮没不能见，交道陵夷真可哀。","与子碧江相别后，到今青眼未曾开。","几伤尺素无人寄，犹喜新鸿昨夜来。","怀抱相思长抑郁，燕居还念此心哉。"]},{"t":"读张华传","f":"七言律诗","c":["堂堂才业世无邻，坐揖荆吴属晋民。","当日若知诛嬖妾，英魂未必死奸臣。","尚能博识周群物，谁使无谋卫一身。","典午基图从此殆，开编令我涕沾巾。"]},{"t":"春日","f":"七言律诗","c":["青春久雨郊原暗，白日新开锦绣明。","苒苒碧丝垂柳树，匀匀红粉上花英。","人生最贵逢辰乐，暇日终当载酒行。","无为草玄成寂寞，便输风景属流莺。"]},{"t":"和千乘先生诗","f":"七言律诗","c":["蓬荜犹淹济世图，独持经术振群愚。","困穷自古饶贤者，功业于今属丈夫。","天下久思安石起，时人争笑孟轲迂。","何时币聘来莘亩，伫听嘉言上禁途。"]},{"t":"赋环翠轩池鸂鶒","f":"七言律诗","c":["池轩澄澈岸花薰，吾爱微禽独此存。","野性尚思江海逸，灵心应识稻粱恩。","春风鼓舞波涛绿，夜月栖迟藻荇繁。","沙雁溪凫应羡汝，光辉终日望华轩。"]},{"t":"与程德林","f":"七言律诗","c":["俊骨风标固逸伦，况闻才术巧安民。","寻常恨不亲高谊，邂逅相逢即古人。","议论耻拘时俗态，笑歌惟取性情真。","从今便作忘形契，安得相从席上珍。"]},{"t":"病居寄程德林","f":"七言律诗","c":["槿花时态厌羁贫，谁恤天涯卧病身。","千里有家归未得，一心无赖恨长新。","形容憔悴真衰汉，意气萧条似老人。","恨乏酒樽将寂寞，独凭诗句诉酸辛。"]},{"t":"月夜忆伯兄兼寄诸友","f":"七言律诗","c":["炎暑遁逃天已凉，日阴苦短夜初长。","风声日色尽秋意，海角天涯非故乡。","莺谷久离愁满眼，鸰原一别泪沾裳。","客情欲借清吟遣，诗就客情弥惨伤。"]},{"t":"适婺","f":"七言律诗","c":["浮俗区区走利名，吾儒何事亦劳生。","昔骑马作衢江计，今买舟为婺女行。","南北东西无定日，艰难险阻亦常情。","日多好景谁同咏，樽有清醪且自倾。"]},{"t":"寄桐庐诸友","f":"七言律诗","c":["整顿衰羸尚未苏，信音都向故人疏。","须怜犬子常多病，莫笑嵇康懒作书。","庠序旧规还在否，道涂新况比何如。","鳞鸿若到江南地，愿寄声音一起予。"]},{"t":"寄邹广道 其一","f":"七言律诗","c":["陋学常嗟趣识迷，羡君先得正途归。","直从前哲评高下，羞与时人较是非。","长愤荆蒿埋杞梓，忽惊沙砾得珠玑。","相从未几又相去，东望门阑心欲飞。"]},{"t":"寄邹广道 其二","f":"七言律诗","c":["夙昔闻君有古风，里闾邂逅一相逢。","金兰密契虽深结，风月高吟未款从。","宝玉如能庇嘉谷，微蒿终待倚长松。","江头若有东归雁，时寄声音慰病容。"]},{"t":"风便示君时叔宜二弟","f":"七言律诗","c":["挂帆瞬息绝远水，行李逡巡临故乡。","雨润棣棠千叶叶，云深鸿雁一行行。","清吟未惬溪山胜，熟睡不知岐路长。","邂逅此时同此乐，萱堂卮酒意难忘。"]},{"t":"简振道判官","f":"七言律诗","c":["涉汴浮淮即渡江，一春饱满看沧浪。","临溪高柳为谁绿，隔浦幽花还自香。","暖日鱼儿浮密藻，轻风燕子语危樯。","遥知景物烦酬唱，到日诗成几百章。"]},{"t":"江流","f":"七言律诗","c":["江流缭绕转天涯，万幅风帆去若驰。","红日远山开殿阁，青天高木出旌旗。","蛟龙回泊鳍鳞动，燕雀飞翻羽翮迟。","身世百年长扰扰，扁舟多谢捕鱼儿。"]},{"t":"子发南楼饯颖叔适以使事出行因寄拙句","f":"七言律诗","c":["溪山远远绿如如，坐想南楼纵目初。","相别无缘看杨柳，赠行不敢爱琼琚。","浮生稍自尝艰险，远道非关畏简书。","云去正凝千里目，雁来能寄一行欤。"]},{"t":"送君时东归夜宿城外并桥上 其一","f":"七言绝句","c":["疏疏星月帖云浮，槐叶风声已转秋。","欲寄归帆终未得，徒分心逐水东流。"]},{"t":"送君时东归夜宿城外并桥上 其二","f":"七言律诗","c":["虹蜺盘泊宿河阴，气势凌空几百寻。","月近浑如天上坐，风来不见世间音。","吾衰祇有临渊惧，尔壮能无题柱心。","病眼昏昏长似雾，不堪频泪欲分襟。"]},{"t":"君时与董君佐以乡荐相次登甲科有诗送之邀予同赋","f":"七言律诗","c":["青衫慰子久蹉跎，各喜流年壮未过。","金玉曹刘初并价，渊源游夏复同科。","红尘去马侵星月，绿水归艎触芰荷。","邂逅故乡秋正好，相看忆听鹿鸣歌。"]},{"t":"治平赴肥陵幕侍父兄宿大孤山南今复泊于此","f":"七言律诗","c":["扁舟曾宿此江堧，当日朱颜尚少年。","彩笔偶攀天上桂，青衫初泛幕中莲。","浮生梦幻今衰矣，薄宦风波尚慎旃。","记得父兄游屣处，泪添溪水欲无边。"]},{"t":"送梁晦之","f":"七言律诗","c":["行李参差久不齐，飘蓬邂逅暂相依。","趋驰静笑营生拙，老大今知旧态非。","车马一朝君北去，江湖何日我南归。","人间物物浑虚幻，莫为分襟泪辄挥。"]},{"t":"江口","f":"七言律诗","c":["北风吹荡酒旗斜，渡口寥寥数十家。","茅屋尺椽贫活计，渔罾一幅旧生涯。","青云正著杨柳叶，白雪已开芦苇花。","蓬笠焉知慕轩冕，牛羊岂遂胜鱼虾。"]},{"t":"粹老召饮滕王阁遂过徐亭泛舟戏呈粹老","f":"七言律诗","c":["溪山高下绿参差，终日清风慰所思。","何不并携安石妓，却须一过习家池。","桐孙转影随朱槛，莲子吹香入酒卮。","晓色江湖秋更好，微云恰值雨来时。"]},{"t":"游东湖","f":"七言律诗","c":["草色蒹葭芦苇中，莲花一片万枝红。","斜阳色妒波心日，细雨香吹水面风。","泽国地开金色界，桃源人在水晶宫。","扁舟便好如张翰，好在溪边旧钓筒。"]},{"t":"诗呈季友殿丞因寄正父兄","f":"七言律诗","c":["寂寂门无车马尘，故人相过觉情亲。","焉知轩冕金朱贵，不笑齑盐藜苋贫。","看月纵吟颐阁夜，插花沉醉鉴亭春。","白头想叹童儿事，浑属溪边自在身。"]},{"t":"生日提点少卿公谔惠诗因次元韵","f":"七言律诗","c":["水日金行共一乡，丈人每爱我辰良。","骅骝未解驰千里，弧矢犹知志四方。","漫与乾坤同作客，笑看儿女已成行。","贫家祇似寻常日，金玉何为忽在堂。"]},{"t":"寄云居觉老大禅师","f":"七言律诗","c":["云中楼阁绿沉沉，杖策城头望正深。","山近想瞻师子坐，风来疑听海潮音。","三乘漫设牛羊鹿，一路谁分耳目心。","祇道不增还不减，元来非古亦非今。"]},{"t":"和莘老元日时改元丰 其一","f":"七言律诗","c":["天以元丰号太平，新年风物兆康宁。","农人待种滂沱雨，太史仍占润泽星。","初日浮阳临夏屋，宿霜澄澈照寒厅。","玉津池北池南路，还拟同探柳眼青。"]},{"t":"和莘老元日时改元丰 其二","f":"七言律诗","c":["衣冠投晓贺元正，草木欣欣共晏宁。","玉历已开新岁日，璿玑犹数去年星。","风流岂遂同乌府，香火还来共水厅。","渐老莫惊头欲白，公名久已在丹青。"]},{"t":"杨浩然见寄因次其韵","f":"七言律诗","c":["百年流转笑浮生，忧思随时苦未宁。","心胆爱君长似水，鬓毛如我欲垂星。","春风半夜烧灯院，腊雪穷年祭酒厅。","梦寐旧游如昔日，可怜庭柏自青青。"]},{"t":"和大名掾舍弟君时","f":"七言律诗","c":["大名书到慰离忧，南北还嗟各宦游。","任责踰涯吾不乐，食功随分汝何羞。","客尘汎汎常时味，河水浑浑一片愁。","綵服欲归今未可，遥将心寄日边州。"]},{"t":"和莘老城东斋祠 其一","f":"七言律诗","c":["郁郁葱葱佳气中，晓天春雾湿濛濛。","山川更洗崇朝雨，草木还催二月风。","乐国地开金色界，容台人在水晶宫。","长年饱食知无补，尚有私诚祝屡丰。"]},{"t":"和莘老城东斋祠 其二","f":"七言律诗","c":["天上春来今几时，园林已自足光辉。","桃心欲放轻红出，柳眼初分嫩绿归。","解冻暖风吹浩荡，养花新雨落霏微。","知君准拟多行乐，佳句何妨及绣衣。"]},{"t":"急雨","f":"七言律诗","c":["远岫低连野水苍，田溪急似雨淋浪。","灵坛冉冉云烟净，小径深深花草香。","落日客帆千点细，秋风渔笛一声长。","诗成未解酬真赏，追逐须将夙愿偿。"]},{"t":"山堂","f":"七言律诗","c":["江湖曲曲抱千峰，堂在山光水色中。","云薄祇疑蓬岛近，湖深遥觉海门通。","扁舟莼菜知无限，促席榴花定不空。","独倚栏干西北望，子牟此兴亦无穷。"]},{"t":"望云台","f":"七言律诗","c":["欲望都门春正深，高台孤绝更登临。","空云霭霭生归思，鸣雁雍雍多好音。","华盖荧煌天半际，瀛洲缥缈海中心。","江天抱病频搔首，自笑纷纷雪已侵。"]},{"t":"郁孤台","f":"七言律诗","c":["江城尘土日喧喧，中有苍然一点山。","日暖蜃楼浮海上，花深蓬岛在人间。","晴云鹤鹤千峰远，碧瓦鳞鳞万屋环。","却望钟陵何处所，客心先与水东还。"]},{"t":"离赣上","f":"七言律诗","c":["昨夜水生三尺来，匆匆相送若相催。","大声振地潜鱼跃，白浪粘天高岸摧。","宿雨未收云霭霭，春鸥无数雪皑皑。","问奴新酿犹馀否，为我临溪开一杯。"]},{"t":"送正夫之郓","f":"七言律诗","c":["清河如练月如霜，六月舟行亦自凉。","骢马何为轻去国，锦衣不害数还乡。","高才落落邦之杰，令问洋洋民所望。","城上望公公更远，人间今日日何长。"]},{"t":"答赵正夫","f":"七言律诗","c":["风波久与故人违，临水登山百尔思。","世事易令人苟简，年华稍恨我衰迟。","尚迁乔木出幽谷，忍舍灵龟观朵颐。","鱼雁不应嫌寂寞，时将一字寄天涯。"]},{"t":"以去年诗再答正夫","f":"七言律诗","c":["不愿与公终食违，别离草草不胜思。","老便静处溪山好，懒见闲中日月迟。","论易朱云折其角，说诗匡鼎解人颐。","岁云暮矣来何晚，倚杖相望一水涯。"]},{"t":"饮君宜弟所寄缁衣酒继得书因成小诗奉寄","f":"七言律诗","c":["少年离别似寻常，老大别离多感伤。","饮酒看云心散漫，开书对雨泪淋浪。","棣棠密织花成锦，鸿雁斜书字作行。","未到与人贪富贵，会须同汝老耕桑。"]},{"t":"寄君时学正弟","f":"七言律诗","c":["亦与儿童酌酒醪，焚香颂祝不胜劳。","命如千载松难老，德比九疑山更高。","顶上少时多鹤发，眉间近日有霜毫。","江湖复见年时雁，倚杖孤城首重搔。"]},{"t":"敏叔家会仙洞","f":"七言律诗","c":["大松十里建旌麾，晓日朝霞五色衣。","幽谷静闻猿一啸，白云时见鹤双飞。","花开洞府春长在，人会瀛洲夜未归。","家近武陵时入梦，诗成更忆故山薇。"]},{"t":"答周考功惠黄丝棕心席玉面界方","f":"七言律诗","c":["老年离别欲心折，不似旧时年少时。","人世匆忙疑是梦，鬓毛感慨欲成丝。","刚严碧玉方无玷，润泽黄丝席有仪。","观物似公长在眼，祝公千岁比灵龟。"]},{"t":"和通判章承议 其一","f":"七言律诗","c":["决胜从容樽俎间，一军争死不知还。","拔旗往蹈乌丸垒，杖箠横封函谷关。","画像麒麟天上阁，铭功鸡鹿雪中山。","我荣不与诸公比，归见慈亲一解颜。"]},{"t":"和通判章承议 其二","f":"七言律诗","c":["卢商舟淅两岐间，四月军行八月还。","龟息不妨窥道奥，鼠偷无敢近禅关。","云迷汉水沧浪水，雨湿蒲山岌嶪山。","曷日与君同此乐，清言犹可慰衰颜。"]},{"t":"答毛提举惠新酒鸡头依韵奉寄幸一笑","f":"七言律诗","c":["齐鹄顺风飞上天，空笼遂至扣犹全。","滑思琥珀千钟满，软忆珠玑一样圆。","举白醉攻愁自破，硫黄暖与病相便。","南归几梦凉堂会，咫尺书来更怆然。"]},{"t":"和张侍读游蜀山","f":"七言律诗","c":["日光拂拂已破卯，野色依依犹带秋。","风卷旌旗出城曲，云迎步履过林幽。","欲扳悬崖访猿鹤，更逐去鸟穷渊丘。","脱洒尘埃坐清旷，静窥万物都蜉蝣。"]},{"t":"送熊次道因寄了元","f":"五言古诗","c":["去入红莲幕，来仪振鹭庭。","文词元润泽，才力更精灵。","须作晚成器，拟看新发硎。","綵衣长暇日，多聚读书萤。","若见焦山老，相烦为寄声。","别来头上雪，添得一千茎。"]},{"t":"寄周朝议至乐堂 其一","f":"七言律诗","c":["赏花载酒百花洲，看雪开筵白雪楼。","不尽山川长在目，忘机鸥鸟自随舟。","当时一笑有馀味，今日相思翻百忧。","闻说作堂名至乐，几时还得与公游。"]},{"t":"寄周朝议至乐堂 其二","f":"七言律诗","c":["世味中人醉不醒，公归正似解人酲。","归云意思闲方见，瘦鹤精神老更清。","但与尧民时击壤，何须秦女会吹笙。","渊明已有归来赋，沮溺应容作耦耕。"]},{"t":"和邹汉广见寄","f":"七言律诗","c":["征旆飞飞度夕阳，画桡隐隐照溪光。","白云点缀千峰绿，青女摧残万叶黄。","林外小花留蛱蝶，岸边深藻宿鸳鸯。","沧浪可爱须沉醉，诗老无疑缓报章。"]},{"t":"济叔润之兄弟见送出小渡","f":"七言律诗","c":["欲寄穷通逐水沤，共君歌舞醉新秋。","诗辞可爱题黄叶，别意难忘寄绿洲。","雨过微风催去棹，夜凉明月满归舟。","又随天外一飞鹄，可羡波前双白鸥。"]},{"t":"晚晴","f":"七言律诗","c":["万里无云雨意醒，江湖满载夕阳明。","老翁暮钓扁舟去，稚子归樵一笛横。","溪月悠悠含夜意，林风细细作秋声。","诗魂散落无羁束，试效樊川赋晚晴。"]},{"t":"山游","f":"七言律诗","c":["试拂尘衣访远踪，诗魂独与赏心同。","低低弱柳啼秋雨，细细寒螀啸晚风。","岩石溪流相照绿，草花枫叶一般红。","玉琴写尽逍遥意，疑到蓬瀛岛屿中。"]},{"t":"过岭上","f":"七言律诗","c":["山幽渐失尘埃路，势险方知造物功。","岩溜飞光动天上，樵斤遗响落云中。","烟迷曲岛千峰细，日转寰区万里空。","安得谪仙来并此，醉浮风驭过蟾宫。"]},{"t":"将寄豫章以诗先寄文渊秘校","f":"七言律诗","c":["已传灵耗烦晨鹊，更作新诗寄塞鸿。","千里薄寒沾暮雨，百壶清笑望秋风。","仙人楼阁重湖外，帝子亭台翠霭中。","谢傅未忘丘壑意，待携歌妓醉山东。"]},{"t":"刑部丈寄酒因成短诗以谢","f":"七言律诗","c":["玉壶寄酒来三岛，蓬鬓持杯学八仙。","诗句剪裁挥翰墨，赏心飞舞度林泉。","秋风会圃寻霜实，明月归舟载锦鲜。","甘倚白云穷一醉，为公吟尽洞中天。"]},{"t":"徐中文赴新建以诗寄之","f":"七言律诗","c":["童稚欢呼喜欲颠，荡舟争揖县公贤。","荆蒿自觉风霜逼，花木须惊雨露偏。","天下事烦宜振领，古人材锐戒窥渊。","君心旧得中和说，定与龚黄议后先。"]},{"t":"新建宰徐中文尉宁文渊出城见饯","f":"七言律诗","c":["诗句飞华照彩笺，酒花浮绿动金船。","眼看世态嗟无益，心到天真喜自然。","盛德优容闻邵父，清才脱洒爱梅仙。","却嗟风雨催行色，不得相从醉洞天。"]},{"t":"别子直","f":"七言律诗","c":["高秋惜别苦匆匆，不得清吟日日同。","步履忽迎春色合，肺肠甘逐酒樽空。","一舟喜逐征帆北，千里愁逢去鹢东。","恰似江神惜离袂，夜来故作打头风。"]},{"t":"次韵周户曹水轩","f":"七言律诗","c":["新辟颓墙得小轩，未成诗思已相关。","一窗嫩绿分肥水，十里澄辉接蜀山。","近岸雨收风满径，暮天云静月当颜。","参军莫作尘埃叹，今有幽虚伴若闲。"]},{"t":"寄明甫约出饯城西既以病告遂已","f":"七言律诗","c":["结束行装赴早秋，爱怜交论重迟留。","樽空北海虚前约，病告东阳益别愁。","征旆几时归偃月，客心一夜梦藏舟。","尘埃日日无穷尽，能免幽人笑我不。"]},{"t":"和户曹池亭韵","f":"七言律诗","c":["水光苒苒上朱栏，六月轩楹起薄寒。","谁约醉翁同酒艇，欲寻溪叟问渔竿。","风飘翠芰清如洗，雨裛苍苔绿未乾。","见说诸公游兴惬，梦魂终夕为盘桓。"]},{"t":"和史司理水轩","f":"七言律诗","c":["收拾澄虚过断墙，轩楹从此有辉光。","草侵两岸春应好，水接双溪晚自凉。","诗念松陵频纵笔，会思河朔重飞觞。","渔舟占尽江湖乐，应笑吾侪簿领忙。"]},{"t":"次周户曹见寄","f":"七言律诗","c":["车马攲危冒险艰，烟尘衰飒病容颜。","游心自惜相逢晚，归兴能忘一笑闲。","野色无涯秋苒苒，溪声不息夜潺潺。","而今幕府文书少，须约诗筒重往还。"]},{"t":"长岭值风","f":"七言律诗","c":["江上避风苦流滞，林边步竹强迟留。","山迎草色浑青黛，浪逐鸥群尽白头。","垂柳丝丝萦渚岸，落花片片入溪流。","兴来却喜闾阎少，双眼无尘事事幽。"]},{"t":"西口值风","f":"七言律诗","c":["逐处烟岚照水村，谁家草色接衡门。","山藏曲圃非尘路，花满幽蹊似故园。","海燕斗风轻笑语，林莺带雨巧飞翻。","天时似有清明意，自作新歌慰旅魂。"]},{"t":"和广汉旅中韵","f":"七言律诗","c":["苒苒征衣冒晓霜，客心衰寂鬓毛苍。","故人行李来江外，游子飘蓬念异乡。","言失筌蹄知意得，醉遗簪绂觉形忘。","青衫四十犹羁旅，叹息泥沙困乘黄。"]},{"t":"席上分题得长字","f":"七言律诗","c":["肥上相逢各异乡，笑歌犹得慰参商。","人心未尽文章乐，马首还趋道路长。","鹤发久堙宗庙器，荷衣行觐赭袍光。","功名自有天时在，更尽林边酒一觞。"]},{"t":"得赵吏部所附第二书","f":"七言律诗","c":["日月不停如转车，匆匆还见岁其除。","已行沙漠数千里，才得京华第二书。","一读令人喜不寐，万金于我实何如。","遥知日月从三友，弟劝兄酬乐只且。"]},{"t":"与磁倅郭公域","f":"七言律诗","c":["熙宁天子作文功，拣点官师在学宫。","璧水三年嗟我拙，兰英一笑忆君同。","青衫昔日俱强壮，白发今时已老翁。","邂逅欲言浑不及，别离三四叹西风。"]},{"t":"元日","f":"五言古诗","c":["玉律阴阳会，璿玑日月新。","熙宁万岁历，元祐八千春。","卦象已乘泰，斗杓方建寅。","白头谙守岁，红烛最知春。","柏酒人怀远，饧盘客荐新。","老来长道路，惭愧百年身。"]},{"t":"答相州司谏同年","f":"七言律诗","c":["白简风声雨雪霜，几回趋走并鹓行。","清名久自还吾党，治誉今尤慰所望。","安稳慈亲行小径，光辉彩服侍华堂。","我今不复有此乐，一读君诗三断肠。"]},{"t":"望云岭饮酒","f":"七言律诗","c":["班荆解马面遥岑，北劝南酬喜倍寻。","天色与人相似好，人情似酒一般深。","豚鱼尚可及人信，胡越何难推以心。","立望尧云搔短发，不堪霜雪苦相侵。"]},{"t":"北使还代书寄颖叔","f":"七言律诗","c":["南行湖海北幽州，不见故人今几秋。","万事尘沙浑是梦，百年露电只如流。","欲观王俭红莲幕，更上庾公明月楼。","旧说楞严多少义，由来祇在一毫头。"]},{"t":"尚德","f":"七言律诗","c":["万里沙陀险且遥，雪霜尘土共萧条。","草莱长大牛羊众，窟穴阻深豺虎骄。","往日御夷谁似宋，今时尚德莫如尧。","试看虞舜岩廊上，何羡呼韩渭水朝。"]},{"t":"南归","f":"七言律诗","c":["匆匆灯火着征衫，客劝宾酬酒既酣。","老马经时俱首北，大鹏今日会图南。","拟寻乐事羞华发，欲问生涯指旧庵。","贪惜上恩归未得，素餐自愧百无堪。"]},{"t":"广平甸谓虏地险至此广大而平易云","f":"七言律诗","c":["四更起趁广平朝，上下沙陀道路遥。","洞入桃源花点缀，门横苇箔草萧条。","时平主客文何缛，地大君臣气已骄。","莫善吾皇能尚德，将军不用霍嫖姚。"]},{"t":"诸君约归日","f":"七言律诗","c":["黄金束带锦貂裘，白发追随每自羞。","已见冰澌流碧水，遥知春色满皇州。","红开金谷楼前面，绿暗玉津池上头。","衰病到家应稍健，为公须醉百金瓯。"]},{"t":"归期","f":"七言律诗","c":["归期元约是花时，曲指花时定可归。","日暖拥云迎马首，天寒飘雪点人衣。","老胡泪落不忍别，野鹊性灵相近飞。","到得归时春更晚，故园桃李正芳菲。"]},{"t":"沙陀逢正旦使副","f":"七言律诗","c":["踏雪予今济土河，驱车君始入沙陀。","异乡邂逅不可得，别酒留连能几何。","缥缈飞鸿无限意，凋零白草不胜歌。","到家正是花时节，酒饮休辞杯数多。"]},{"t":"送鄱阳太守 其一","f":"七言律诗","c":["青春一日锦衣还，酒上亲闱喜动颜。","静视浮名虽羽翼，回瞻明德已丘山。","身留桑梓孤衷结，目断旌麾一泪潸。","初仕正忧民事拙，愿书馀训起疏顽。"]},{"t":"送鄱阳太守 其二","f":"七言律诗","c":["朝星一夜渡寒江，千里瞻依重慨慷。","荆土定能碑岘首，召南安敢废甘棠。","遗恩未散波涛润，令德长馀锦绣香。","吟尽肺肠还自惜，江湖不似去思长。"]},{"t":"送鄱阳太守 其三","f":"七言律诗","c":["天明下诏寂寥滨，师帅高才得献臣。","事出中和民自怿，令捐苛细物长春。","红裙涕泣瞻征旆，白首驩呼滞去轮。","簪绂相先问行色，几时携节渡江濒。"]},{"t":"和程秀才望五老峰","f":"七言律诗","c":["忆步灵芝望翠峦，扁舟今入望中山。","沾濡晓雾仙衣湿，点缀春苔鹤发班。","幽谷静闻寒布落，重崖晴见暮云还。","世途正为声荣困，谁伴苍颜老此间。"]},{"t":"和谒孝肃祠堂","f":"七言律诗","c":["声容不见见灵祠，眷惜徘徊重叹咨。","樵牧万家歌旧泽，簪绅百拜望英资。","深图遂失商霖远，清论空随海月垂。","欲拾绪言嗟未得，风流喜读大夫碑。"]},{"t":"和李馀干干越亭","f":"七言律诗","c":["溪流可到非千里，客梦相望欲十年。","胜概昔闻遗老说，乐游今见令君贤。","月移波影归珠箔，风转滩声落绮筵。","安得浩歌寻涧曲，独飞纶钓醉霜天。"]},{"t":"次皇甫登兴化水亭韵","f":"七言律诗","c":["簿领终朝困蒸暑，危亭一息得微凉。","草迷幽径回环绿，花落沧波在处香。","永夜鹤声双唳月，清秋松色自凌霜。","平生爱乐澄虚地，一梦迟留夜未忘。"]},{"t":"同游独山 其一","f":"七言律诗","c":["路蹊曲曲上乔岑，风物疏疏接远林。","携妓笑无安石乐，爱山喜似晋公心。","步寻翠石伤荆玉，行接幽岩望傅霖。","别去几时重会此，欲君无避酒船深。"]},{"t":"同游独山 其二","f":"七言律诗","c":["独山亭子山之心，万竹相围尽翠阴。","古刹地幽红日永，悬崖人静碧云深。","轻风细细无朝夕，劲节依依自古今。","吏役几嗟诗笔废，兴来不惜为君吟。"]},{"t":"同游独山 其三","f":"七言律诗","c":["城楼日日望霄垠，车马今来访旧闻。","寒石万寻围翠竹，危峰一点缀青云。","洒然自有林泉乐，去矣吾非鸟兽群。","安得画工图绝致，尽收苍翠寄诸君。"]},{"t":"同游独山 其四","f":"五言律诗","c":["相期一樽乐，共宿独山青。","尘土不能污，梦魂还自醒。","夕阳登绝径，明月步危亭。","为我题僧壁，炎天此日经。"]},{"t":"谢公权赐蜀笺","f":"七言律诗","c":["君得奇笺自蜀溪，缄封密密寄幽栖。","香销翠玉花枝软，影落青云凤翼低。","书橐一朝丰绮绣，诗心半夜振虹霓。","报之重愧无琼玖，强拾刍言细细题。"]},{"t":"次韵答刘行甫同年","f":"七言律诗","c":["江外书来墨未乾，笑言可惜碍云山。","字无尘迹精神健，诗有天才态度闲。","皓月分明生海上，仙韶容易落人间。","夜深一梦无拘束，飞度重湖晓未还。"]},{"t":"和张侍读总翠亭","f":"七言律诗","c":["城隅东北起危亭，卧栋飞檐控地形。","万井不藏平野绿，一湖才见远山青。","春归会圃低华幄，雨歇寒芜露翠屏。","日暮登临望楼阙，误随飞鸟下南溟。"]},{"t":"和馆阁诸公游池韵","f":"七言律诗","c":["达士超然独若遗，赋诗行酒似儿嬉。","一杯相属非人力，四者难并异昔时。","高柳去随波斗绿，啼莺未与燕为期。","春晴岂但群公乐，万物纷纷总自私。"]},{"t":"和致远学士游池 其一","f":"七言律诗","c":["堤外波澜浸彩霓，花间宫殿出高枝。","风高夭矫凤飞去，雨止蜿蜒龙倒垂。","早晚烟霞相间杂，浮沉鱼鸟并游嬉。","文王台沼群贤至，不比山阴祓禊时。"]},{"t":"和致远学士游池 其二","f":"七言律诗","c":["岸岸垂杨障绿阴，时时好鸟啭清音。","昭回河汉波澜阔，方丈蓬莱雨露深。","到处香烟浓作雾，谁家珠翠密成林。","争标想见千人唱，声入青云画鼓深。"]},{"t":"送程给事并次中丞杂端韵","f":"七言律诗","c":["公去江淮今几年，欢谣今日尚纷然。","恩荣复拥千兵出，课最应当一路先。","诗字细题幽寺竹，酒卮深泛碧池莲。","风流会续兰亭盛，幕府能无窦巩贤。"]},{"t":"持正率和中丞诸公喜雨诗二首用前韵","f":"七言律诗","c":["滂沱自足慰民忧，更洗瓯闽四五州。","风入远林惊海坼，水吞平陆看川流。","禾麻嶷嶷私时泽，鱼鸟欣欣惬所求。","凉簟饱眠吾亦乐，静窥槐叶拟开秋。"]},{"t":"次中丞韵","f":"七言律诗","c":["人家碧瓦照朱丹，缥缈烟涛密琐关。","一水北邻千里海，万峰南揖四明山。","鸟啼浮世尘埃外，人在青云道路间。","祇恐公归难久驻，匆匆便捧诏书还。"]},{"t":"次杂端韵","f":"七言律诗","c":["画舫参差看欲飞，纷纷车马压尘泥。","右军笔墨空兰渚，安道风流访剡溪。","白首得时归莫遽，丹心怀国去犹稽。","月明会醉蓬莱阁，应笑云霄自有梯。"]},{"t":"持正率和诸太一宫诗","f":"七言古诗","c":["上方忧乐共元元，祠宇知非泥故言。","真室转临双阙近，清坛还拱五神尊。","光辉散烛光华旦，动植归藏厚载坤。","旗出荆幡威震叠，马来龙种瑞便蕃。","溶溶远水浮仙岛，苒苒晴霞近紫垣。","画像百灵朝閟宇，制名千福遍重门。","壶中日永春长在，洞口云深昼亦昏。","但祝君王千万岁，人心无以报隆恩。"]},{"t":"问龚深之疾往复 其一","f":"七言律诗","c":["未识先生病所因，调料想亦费精神。","无人可问维摩疾，顾我徒知管仲贫。","未肯一经终皓首，不应千里漫思莼。","藤床卧对炉烟细，想岸渊明漉酒巾。"]},{"t":"问龚深之疾往复 其二","f":"七言律诗","c":["居士如泡如焰身，目前应接亦非神。","枝辞自已知吾拙，饱学谁能笑子贫。","午饮频来同鲙鲤，朝齑漫说欲羹莼。","黄昏急雨秋风湿，想见青灯一幅巾。"]},{"t":"问龚深之疾往复 其三","f":"七言律诗","c":["丈室宽閒独病身，一经反覆足怡神。","漫从方外论空色，笑与人间共贱贫。","菊有细花浮楚醴，鱼无圆鲫煮吴莼。","初凉愿与厌厌饮，预判荒荒月满巾。"]},{"t":"和上官彦衡斋祠 其一","f":"七言律诗","c":["廊陛纷纷响佩环，半天星月晓班班。","误瞻宫阙星辰上，疑听金丝阙里间。","万国祭祠严谷旦，百年文物盛贤关。","奉常固不烦为最，太史徒知咏仰山。"]},{"t":"和上官彦衡斋祠 其二","f":"七言律诗","c":["五更欲踏月明还，去意迟留马亦班。","栋宇参差天左界，綖旒隐约殿中间。","简编雅有多闻富，杖履清无一事关。","俗状情知烦爱惜，更容栖息道家山。"]},{"t":"出城呈君玉都官","f":"七言律诗","c":["天寒雨气满林幽，道上风尘拥布裘。","万室未堪今日弊，一官敢念此生浮。","平常素拙公家事，夙夜聊分县尹忧。","见说至尊方旰食，吾侪何术补涓流。"]},{"t":"舟中暮雨","f":"七言律诗","c":["骑马昔由建春去，泛舟今自美丰归。","水中仙子红莲出，物外幽人白鹭飞。","风起岸蘋寒苒苒，雨生烟谷细霏霏。","吏情转觉尘埃丑，叹息沧浪属钓矶。"]},{"t":"春雨","f":"七言律诗","c":["三月江淮物正新，等闲风雨挫芳春。","狂飘柳色低垂地，暗损花枝自恼人。","垄亩千家知有望，江湖万里喜通津。","鸰原莫放朝华去，共约新晴醉绿茵。"]},{"t":"渔艇寄莲花","f":"七言律诗","c":["鸟飞池曲冒尘埃，眼看莲花叶叶开。","行李偶随孤艇出，好风飘寄一枝来。","雨中秀色供吟眼，风外清香入酒杯。","半夜梦魂生枕簟，神仙无语下阳台。"]},{"t":"骤雨","f":"七言律诗","c":["乍喜物情争发育，无端骤雨欲残春。","阎闾已负游芳意，畎亩犹滋望岁人。","厚泽颙颙苏品汇，微波泛泛涨江津。","城头便好狂吟去，草木青红衬锦茵。"]},{"t":"感怀","f":"七言律诗","c":["浪计寻思直径归，大疏不与世情宜。","吟成白雪无人问，歌尽清风祇自知。","是否不能寻物议，穷通浑欲付天时。","轲雄已矣吾谁适，犹有尘编旧训辞。"]},{"t":"次张德甫朔雪韵","f":"七言律诗","c":["朔风吹雪落天涯，醉立飞楼四望赊。","粪壤不知涵润泽，蒿莱无复见纤瑕。","半宵庭槛光争晓，穷腊园林物自花。","谁借一舟湖北岸，月明东访戴生家。"]},{"t":"梅","f":"七言律诗","c":["春入园林总不知，墙头初见一梅枝。","朔风不挫寒冰骨，夜月偏饶白玉姿。","密意忍容莺蝶污，英心长与雪霜期。","人情愿得和羹实，无纵羌童把笛吹。"]},{"t":"睡觉","f":"七言律诗","c":["漏急难留一梦清，灯寒相伴寸心明。","暖薰绣被春风信，寒战莎阶夜雨声。","尽晓丝篁来竹幄，何时锦绣满花城。","病夫不称诗魔役，愁见吟魂续续生。"]},{"t":"送太守舒郎中赴阙 其一","f":"七言律诗","c":["英谋一发破昏冥，道路喁喁侧耳听。","千里啸歌趋雨露，百胥奸猾避雷霆。","闾阎有让风长暖，囹圄无尘草自青。","朝罢雍容问民瘼，愿言康乐上宸庭。"]},{"t":"送太守舒郎中赴阙 其二","f":"七言律诗","c":["陋迹迟回寂寞滨，欲闻高谊叹无津。","声华未及膺门客，揖让犹皆蜀守民。","白日忽收千里诏，清风长挟万家春。","穷途倾眷陶钧力，吟尽肝肠一惨神。"]},{"t":"送太守舒郎中赴阙 其三","f":"七言律诗","c":["解郡西南促去程，扁舟西下照江明。","旌麾益近青云路，剑佩行朝白玉京。","势位久淹犹郡国，光华此去即公卿。","山林愿听功名起，野拙犹能颂治声。"]},{"t":"过陶太尉庙","f":"七言律诗","c":["刘石纷纭正忧戈，尽心收得晋山河。","巍巍功业能如此，藉藉浮言意若何。","风雨旧祠藏石壁，丹青遗像落江波。","黄昏欲作溪头钓，愿丐当时壁上梭。"]},{"t":"伯兄归自桐江未至因有作示诸弟","f":"七言律诗","c":["遥思徒驭去江干，道路谁何共险艰。","长使庭闱终日望，不知车马几时还。","伫期笑乐同尘席，应有文章慰病颜。","酒瓮半空为收拾，筮言当见立谈间。"]},{"t":"将归寄润之弟","f":"七言律诗","c":["纷纷穷绪不能禁，一缕俄惊百万寻。","风月正牵相望眼，山川难系欲归心。","萧条又作新秋意，牢落谁同永夜吟。","车马鼎来吾即起，梦魂先傍竹亭阴。"]},{"t":"奉别张伯逢先生","f":"七言律诗","c":["强鞭驽蹇逐尘踪，百驾方成跬步功。","天地有心成草木，蚊蝇无力负衡嵩。","纷然又见瓜期及，晚矣犹思吾道东。","一寸古心长自歉，依依馀恨满西风。"]},{"t":"断编","f":"七言律诗","c":["断编尘简即吾师，万里徘徊得路迟。","览照忽惊颜色古，临空叹息羽毛衰。","迂愚未尽田瞿学，庸贱空收鲍叔知。","安有微波增海曲，愿因穷腊看松枝。"]},{"t":"高议","f":"七言律诗","c":["高议轩昂破丽淫，清风遗散落尘襟。","倚山渐识浮云意，临水方思太古音。","无状欲随仁义老，未完犹怯是非侵。","西归须念津涂惑，愿丐中庸镂腹心。"]},{"t":"牢落","f":"七言律诗","c":["牢落归来水一隅，卧思天阙自烦纡。","祇知今夕又明日，不觉少年成壮夫。","祸去不虞堪太息，势临无备独长吁。","忧时未有如君老，愿听丹囊上禁涂。"]},{"t":"王太博自浮梁移蒙州作送之","f":"七言律诗","c":["平时沉伏草莱间，见说昌江治政贤。","爱浃羽毛人自畏，诗成金玉俗争传。","一麾出守今行矣，万室倾思正惨然。","祇恐又膺明诏去，蒙山无计重留连。"]},{"t":"送周掾赴阙","f":"七言律诗","c":["白驹一掷起尘埃，紫凤高鶱出草莱。","盛德日随流水远，清声时逐好风来。","百年正属文明际，万事犹须干济才。","荐牍几多闻九极，宠章何日下三台。"]},{"t":"寄伯兄兼问子文 其一","f":"七言古诗","c":["富贵浪图虽汩汩，诗书馀力尚桓桓。","圣门一室相从易，世路多岐欲合难。","仪凤稳依深阁宿，老蛟寒即碧溪蟠。","青云有侣歌鱼藻，空谷无朋唱考槃。","缘木退藏冲汉翼，扁舟归整钓鳌竿。","临风愿听王阳仕，洗手思弹贡禹冠。"]},{"t":"寄伯兄兼问子文 其二","f":"七言古诗","c":["壮志当年欲请缨，孤踪今日尚飘萍。","尘埃易染羁容黑，气义难邀俗眼青。","冯客剑寒长自击，伯牙弦古欲谁听。","风云勇胆驰燕塞，社稷丹心望汉庭。","思入鹡原愁四散，梦驰莺谷涕双零。","客悰愿托诗情见，吟尽清宵卒未醒。"]},{"t":"送子文赴阙","f":"七言律诗","c":["槿花时态甘相失，金玉交情喜独亲。","慷慨有心探虎穴，邅回无计附龙鳞。","君方奋翼青冥上，我即潜舟寂寞滨。","从事功名有馀力，勉为书寄考槃人。"]},{"t":"寄润之弟兼附呈伯兄 其一","f":"七言律诗","c":["一棹孤舟接杳冥，无聊长恨别离轻。","利名汩汩乱人意，南北悠悠分我情。","风触鹡鸰寒影散，日蒙棠棣绿阴成。","莫令泽国频回首，时倩江鳞寄一声。"]},{"t":"寄润之弟兼附呈伯兄 其二","f":"七言律诗","c":["江外如今独转蓬，思君不敢望飞鸿。","寸心引逐征云北，孤梦争先落叶东。","卧病此时千里隔，微吟何日一樽同。","却嗟逐客为羁客，还见春风换朔风。"]},{"t":"寄润之弟兼附呈伯兄 其三","f":"七言律诗","c":["风规落落已非俗，气宇堂堂知有才。","安得骅骝归道路，不甘楩梓滞蒿莱。","青阳路径新萌柳，白雪林亭欲放梅。","愿逐羽翰归故国，相从歌酒趁春来。"]},{"t":"东流道遇伯兄西归寄二篇 其一","f":"七言律诗","c":["君栖京国我天涯，病眼相望泪满衣。","邂逅得为千里会，仓皇不及一言归。","穷通固属时之遇，取舍犹惭议者非。","未得宠光荣里落，久行犹足慰庭闱。"]},{"t":"东流道遇伯兄西归寄二篇 其二","f":"五言律诗","c":["久雨泥涂恶，春风草木花。","相逢一笑乐，欲去百咨嗟。","何日定行役，此时应到家。","平居倾望意，汗漫正无涯。"]},{"t":"喜文渊登第因寄二篇 其一","f":"七言律诗","c":["春风吹诏落天涯，喜听君荣及盛时。","桂籍功名知自取，云台事业旧相期。","骐驎有力争千里，燕雀无才寄一枝。","士稚果能先越石，苏秦应欲愤张仪。"]},{"t":"喜文渊登第因寄二篇 其二","f":"七言律诗","c":["十年共力诗书学，万里相期将相科。","白屋自知难掩抑，青山聊得慰蹉跎。","宠荣未有如君早，衰病争加若我何。","灯下无人知此意，独鸣寒剑一悲歌。"]},{"t":"喜择之子文至桐江次伯兄韵","f":"七言律诗","c":["病夫憔悴浙江边，谁恻穷途旧橐单。","尺素不闻倾塞雁，扁舟未至望沙滩。","羁栖久客情无赖，邂逅相逢意倍欢。","幽夜冥冥思取火，与君同取白榆钻。"]},{"t":"闻庭佐不安因驰归","f":"七言律诗","c":["山居倾眷旧朋俦，日落原头望不收。","奴仆忽来传汝病，信音不寄使人愁。","羁怀缕缕无穷尽，归意飞飞可滞留。","一舍道途千里远，那堪风雨重衣裘。"]},{"t":"自东流归","f":"七言律诗","c":["久郁圭蓬困不胜，狂游天地眼双明。","行逢梅浦不能去，步接松林无限清。","风雨寂寥知物意，山川崎曲见人情。","愁悰触物纷无寄，喜听村垆卖酒声。"]},{"t":"东流道中作","f":"七言律诗","c":["轻快飞舆出古城，蟠迂行径转沙汀。","鸬鹚映日露纁翅，鸿鹄斗风开雪翎。","水瘦不藏寒石绿，云归才见远峰青。","苦怜野色溪光好，倍觉诗魂酒魄醒。"]},{"t":"喜徐景宗秀才至","f":"七言律诗","c":["久客羁栖正无赖，故人邂逅一相逢。","红泥绿酒方沈醉，白雪清吟未款从。","昏翳忽收尘耳目，欢欣争入病颜容。","秋风且醉江山碧，莫纵离愁到客悰。"]},{"t":"元祐三年同深之学士子开侍郎在初考今复承乏有怀旧游因作此诗并幕次唱酬二章寄呈深之学士子开侍郎 其一","f":"五言律诗","c":["集英今日事，全似戊辰春。","文彩窥多士，游从忆故人。","抗旌浮海角，舣棹即河漘。","试作诗相寄，诗成更损神。"]},{"t":"元祐三年同深之学士子开侍郎在初考今复承乏有怀旧游因作此诗并幕次唱酬二章寄呈深之学士子开侍郎 其二","f":"五言律诗","c":["数烛知归日，思家似老人。","此凡三锁宿，今复一经旬。","猛着棋销日，深凭酒送春。","萧条双短鬓，半夜总如银。"]},{"t":"和致远学士韵","f":"五言律诗","c":["落笔千人畏，挥谈一坐倾。","竹林冬更好，星斗夜深明。","爱古情何远，忧时气未平。","老人无见解，祇愿酒频行。"]},{"t":"十四弟得书承已次东流赴省试因寄小诗呈推官承务弟","f":"五言律诗","c":["恰见蜘蛛喜，便知鸿雁来。","大波窥汹涌，遥岫见崔嵬。","怀土欲心折，拆书先眼开。","系舟龙化处，亭子旧名雷。"]},{"t":"云盖老僧八十二","f":"五言律诗","c":["邂逅还相见，慇勤复自陈。","三千大千界，八十二年人。","衲衣云水旧，头鬓雪霜新。","手种庭前柏，如今大似身。"]},{"t":"云居相送至下杉庄","f":"五言律诗","c":["莫宿昏初黑，晨装晓已分。","鸡啼江上月，犬吠岭边云。","好去庞居士，善来洪上人。","临行须一勘，腊后几时春。"]},{"t":"昨日陪深之学士饭净因登罗汉阁期致远不至忆山阴弟各赋一首遂寄二君","f":"五言律诗","c":["丹凤禁城近，青鸳宝阁开。","九天瞻佛日，万国在春台。","东观人何处，山阴弟未来。","飞云来自在，相望兴悠哉。"]},{"t":"宿金钩","f":"五言律诗","c":["绝域三千里，穷村五七家。","云深无去雁，日暮有栖鸦。","雾拥云垂野，霜连月在沙。","夜长无复寐，寂寞听寒笳。"]},{"t":"惠州 其一","f":"五言律诗","c":["城垒四五尺，闾阎千百家。","朝尘疑作雨，暮雪欲飞花。","旧寺僧何在，空堂鬼自邪。","三更愁不寐，相笑是皇华。"]},{"t":"惠州 其二","f":"五言律诗","c":["雾暗山千叠，冰寒水一涯。","风高天作雪，日晚露迷沙。","居士身如梦，行人驿是家。","青灯无意绪，点点自成花。"]},{"t":"惠州 其三","f":"五言律诗","c":["绝域冬犹暖，孤村日易斜。","浮云点晴汉，幽鸟篆平沙。","白草单于垒，青灯渤海家。","夜蟾无定处，流转共天涯。"]},{"t":"途中见接伴曰三得家书因作是诗寄候","f":"五言律诗","c":["谁似老胡喜，一朝三得书。","去家长念汝，触事独愁予。","水冻鱼全少，天寒雁更疏。","三冬多壅热，安否比何如。"]},{"t":"长垣路中 其一","f":"五言律诗","c":["欲作图南翼，却乘之北辕。","百年随所值，万事拟无言。","短发霜如白，孤心叶似丹。","夜深何许梦，双阙九重阍。"]},{"t":"长垣路中 其二","f":"五言律诗","c":["身似水中木，险夷惟所遭。","不堪誇拙速，可复叹贤劳。","雨脚三冬少，尘头一丈高。","故乡何处是，南望首重搔。"]},{"t":"天保弟被荐继得子因寄是诗","f":"五言律诗","c":["雁足书何速，灯花喜更频。","桂攀天上近，珠入掌中新。","骥种仍多子，龙标又得人。","贺觞俱见在，留待禁城春。"]},{"t":"和瑛师","f":"五言律诗","c":["泽国春初好，江城雨易昏。","系舟林下寺，步屧水边村。","法悦长如此，诗情剩欲论。","归心师莫问，一旆正翻翻。"]},{"t":"和通判承议","f":"五言律诗","c":["水边人不到，吾与子同行。","始见游鱼乐，时闻幽鸟声。","山如仁者静，风是圣之清。","拟买扁舟去，江湖老此生。"]},{"t":"南安道中","f":"五言律诗","c":["南安穷且僻，况复阻凶饥。","破屋人何在，空山鸟自归。","儿童多素韠，妇女祇青衣。","好雨兆丰岁，斯民其庶几。"]},{"t":"癸未偕子仲都官文渊节推游东湖分题和子仲湖字韵","f":"五言律诗","c":["泛泛林边晚，扁舟忆五湖。","丹青难作赋，水墨好为图。","龙蛰云长在，霜寒草自枯。","诗翁足幽兴，潇洒在蓬壶。"]},{"t":"和文渊同字韵","f":"五言律诗","c":["湖上多佳致，清樽况不空。","乐游今日并，幽思几人同。","苒苒芰荷雨，萧萧芦苇风。","南州人不见，流水自无穷。"]},{"t":"送宁和仲","f":"五言律诗","c":["玉粒稻初熟，霜螯蟹正肥。","薄言酌我酒，聊以送君归。","叠翠屏疑画，淩空凤欲飞。","山前猿与鹤，最识旧征衣。"]},{"t":"和君宜弟诗韵蕲州所寄","f":"五言律诗","c":["棠棣花开处，衡阳雁去时。","封题开远信，涕泪裛新诗。","知道频嗟晚，谋田更恨迟。","去留君莫问，方寸正如丝。"]},{"t":"有感","f":"五言律诗","c":["往复何为者，功名安在哉。","茅心迷簿领，蓬鬓老尘埃。","鱼蠹生书帙，蛛丝在酒杯。","渊明缘底事，苦死赋归来。"]},{"t":"溪上","f":"五言律诗","c":["濯发溪头水，披衣林际风。","低枝折杨柳，高叶荫梧桐。","鱼跃浮萍上，鸟啼幽谷中。","清凉仍各有，彼此一无穷。"]},{"t":"君宜得种茶诗予和韵","f":"五言律诗","c":["始傍东园种，初从北苑移。","本根原自好，造化总无私。","紫笋时名误，乌程旧种卑。","酪奴吾不问，酒圣尔何为。"]},{"t":"病中","f":"五言律诗","c":["富贵来何晚，穷愁固有馀。","病多皇甫谧，贫甚马相如。","思乱诗魂散，忧深酒兴疏。","此心无可奈，徒尔重欷歔。"]},{"t":"病起","f":"五言律诗","c":["失意忧多病，予今喜少痊。","寝兴今泰矣，容质尚苍然。","郁抑丹心塞，纷纭万虑阗。","此情无可奈，整顿赖诗篇。"]},{"t":"醉极有感","f":"五言律诗","c":["饮极人之乐，余心反自伤。","气因人愤激，情与酒飞飏。","泪落侵双鬓，愁多郁寸肠。","空赢山简醉，不似乐天狂。"]},{"t":"小径","f":"五言律诗","c":["南北通官道，东西隘乱山。","无时轮迹道，经雨藓痕斑。","世路同攲侧，人心共险艰。","亟由平易去，宁苦险巇间。"]},{"t":"日暮","f":"五言律诗","c":["人去红尘息，林幽晚意清。","秋阳红旆乱，夕霭翠绅横。","新月淡无色，微风寒有声。","此吟犹未竟，城吏已严更。"]},{"t":"叹交","f":"五言律诗","c":["儿童不可近，况复与之亲。","薤露不终刻，松风知几春。","嚬嚬徒满目，切切竟何人。","诵罢莺鸣咏，空馀涕满巾。"]},{"t":"陈秀才扩因旬休不至以诗呼之","f":"五言律诗","c":["寂寂碧窗下，业同诗酒欢。","暌违才一日，恨怅已千端。","无忽离群异，须矜会友难。","相望正展转，行矣莫盘桓。"]},{"t":"题扬州因大师小池","f":"五言律诗","c":["阒寂黄金宇，清泠碧玉池。","轩楹收冷淡，松竹让幽奇。","岸蹙源流浅，山阴月到迟。","未能活鱼鳖，安可卧蛟螭。"]},{"t":"题袁州紫翠轩","f":"五言律诗","c":["黯淡襟横野，迢遥面古城。","丹青难尽意，紫翠漫为名。","山石开新雨，溪枫照晚晴。","杖藜饶纵目，谈笑不无情。"]},{"t":"寄庭佐弟 其一","f":"五言律诗","c":["愿我今黄发，嗟君亦白头。","读书少不竞，从士老堪羞。","陋巷曷其乐，首阳何所求。","一廛如好在，聊欲与君谋。"]},{"t":"寄庭佐弟 其二","f":"五言律诗","c":["幸免葬鱼腹，更难骑虎头。","少狂真忍耻，老退似包羞。","蓬苇径非远，桑麻田可求。","浮生一箭速，火急为兄谋。"]},{"t":"江上","f":"五言律诗","c":["柳翠芦尤碧，枫殷蓼更红。","金波连夕照，玉浪起秋风。","霄汉双飞鸟，波澜一钓篷。","江湖如许景，总合付诗翁。"]},{"t":"伏承宠示滕王阁佳句因用原韵","f":"五言律诗","c":["滕王帝子阁，徐孺聘君亭。","南浦水秋涨，东湖云昼冥。","江山晴更碧，松桧雪逾青。","安得泛舟去，与君同醉醒。"]},{"t":"送和仲","f":"五言律诗","c":["心因行已老，事更与心违。","恶景多离合，浮生半是非。","愁闻南浦雁，梦采北山薇。","昨日见之子，问予胡不归。"]},{"t":"诗示庭佐弟","f":"五言律诗","c":["世味祇如此，消忧奚所娱。","心烦多恶酒，眼病顿捐书。","倦倚筇枝竹，寒围木火炉。","公宁机械废，我拙笑公愚。"]},{"t":"夜坐谨成小诗呈晦堂心老","f":"五言律诗","c":["修鍊清彻骨，斡旋幽入神。","寸丝缚九虎，一指挂三钧。","丈室夜忽旦，寒崖冬自春。","师乎何所命，学佛亦非人。"]},{"t":"和题真相院","f":"五言律诗","c":["山色随行止，溪声满见闻。","灯花秋寂淡，香火夜氛氲。","野色迷修竹，厨烟长白云。","大夫材力健，故宠寺僧勤。"]},{"t":"和题净慈寺","f":"五言律诗","c":["已失禅关治，空严古殿尊。","佛香尘草莽，僧饭饱鱼豚。","万竹藏秋色，丰碑落烧痕。","废兴俱物鉴，谁似语公孙。"]},{"t":"道中时有山水之遇因用林字韵","f":"五言律诗","c":["我今倦尘土，邂逅得幽林。","云外千山色，溪边万竹阴。","还憎俗吏态，稍快野夫心。","世事非樽酒，天寒不自禁。"]},{"t":"寄公权","f":"五言律诗","c":["灵源起幽谷，萧洒与秋宜。","世事有穷处，泉声无尽时。","流沾一山足，泽入万田滋。","祇恐明朝别，清风到梦思。"]},{"t":"欲雨","f":"五言律诗","c":["车马冒蒸暑，道途伤久晴。","云生蜀山静，风度远秋清。","白蚁纷纷斗，鸤鸠在在鸣。","微阴知雨意，失意问农耕。"]},{"t":"薄荷","f":"五言律诗","c":["神农取辛苦，病客爱清新。","寂淡花无色，虚凉药有神。","烦心侵冰雪，眩目失埃尘。","自是芝兰臭，非同草木春。"]},{"t":"寄邹秘丞同赴京师","f":"五言律诗","c":["马上梅曾赋，林边酒记赊。","乾坤新帝业，山野旧人家。","自昔馀篇翰，经年五岁华。","诗成无雁寄，一梦入天涯。"]},{"t":"春秋成字韵 其一","f":"五言律诗","c":["凤鸟知何处，麟经卒告成。","人人无义战，岁岁有王正。","秦楚空强力，桓文漫主盟。","是非微旨在，终始愿深明。"]},{"t":"春秋成字韵 其二","f":"五言律诗","c":["法为衰周起，文因旧史成。","有权皆反正，无事亦书正。","泣血葵丘会，伤心首止盟。","三家自萤爝，未助太阳明。"]},{"t":"春秋成字韵 其三","f":"五言律诗","c":["圣念周邦弱，经因鲁史成。","尊王常谨始，罪隐不书正。","弗义嗟频战，无常叹屡盟。","幽微今焕若，宁复比丘明。"]},{"t":"春秋成字韵 其四","f":"五言律诗","c":["赏罚陵迟久，春秋笔削成。","称人讥楚僭，书月谨周正。","国国强并弱，时时会复盟。","前贤褒贬在，一览是非明。"]},{"t":"和深父伤字韵 其一","f":"五言律诗","c":["郑弃非人弃，梁亡只自亡。","危机交弊弱，血刃第争强。","恃力虽千国，推尊独一王。","衰微今已往，掩卷益增伤。"]},{"t":"和深父伤字韵 其二","f":"五言律诗","c":["前史权衡在，当时法度亡。","力扶周室弱，深抑楚人强。","言战嗟无义，书元示有王。","细推褒贬意，掩卷一悲伤。"]},{"t":"和深父伤字韵 其三","f":"五言律诗","c":["战伐周纲替，春秋救已亡。","缀旒忧主弱，问鼎叹臣强。","萧斧惩当世，蓍龟鉴后王。","最怜君学苦，能为古人伤。"]},{"t":"和深父伤字韵 其四","f":"五言律诗","c":["春秋二百战，一一叙兴亡。","书战皆非义，称人亦贬强。","临文常抑楚，谨始必尊王。","穷究当时事，应须发感伤。"]},{"t":"深父学士示易诗四首某辄和韵 其一","f":"五言律诗","c":["学易非吾敢，疲驽亦勉旃。","冥心二篇策，皓首一韦编。","忧患生拘羑，几微续草玄。","相期须畛域，慎勿泥蹄筌。"]},{"t":"深父学士示易诗四首某辄和韵 其二","f":"五言律诗","c":["大易诚微矣，吾门敢舍旃。","文虽重旧旨，孔亦断残编。","道远为功骏，言微蓄意玄。","江鱼如可得，朝夕自忘筌。"]},{"t":"深父学士示易诗四首某辄和韵 其三","f":"五言律诗","c":["圣意藏羲易，人心勿舍旃。","玩爻知上古，经火叹遗编。","六画功成简，三才道亦玄。","兄今微大过，默默识真筌。"]},{"t":"深父学士示易诗四首某辄和韵 其四","f":"五言律诗","c":["易道更三古，愚心愿勉旃。","研几甘白首，穷理自黄编。","西伯爻于繇，扬雄准以玄。","意先言象得，从此舍鱼筌。"]},{"t":"毛诗 其一","f":"五言律诗","c":["美刺诗之奥，予今得所归。","议收天地远，心到圣贤微。","雅颂藏兴废，虫鱼隐是非。","篇章三百五，一一数珠玑。"]},{"t":"毛诗 其二","f":"五言律诗","c":["古诗皆有托，正道岂无归。","风雅收功远，弦歌得趣微。","王刘终少是，毛郑亦多非。","儒氏潜深爱，篇篇尽玉玑。"]},{"t":"毛诗 其三","f":"五言律诗","c":["周鲁诗三百，篇篇自有归。","人心散堙郁，物意露幽微。","原本今无复，风华比益非。","遒人不知采，空此缀明玑。"]},{"t":"和章承议通判来章","f":"五言律诗","c":["近水班荆坐，缘山拄杖行。","云烟窥胜概，风雨听寒声。","久累维摩病，多惭卫玠清。","波澜终未息，衮衮共劳生。"]},{"t":"问侗","f":"五言律诗","c":["知现维摩病，莫淫皇甫书。","去归吾未可，调治尔何如。","眼忌时时拭，头便日日梳。","首先惩忿怒，次第学呵嘘。"]},{"t":"云盖寺","f":"五言律诗","c":["旧日蛇虺穴，今时薝卜林。","寒泉三井旧，高阁五峰深。","翠竹娟娟老，长松漠漠阴。","凤凰池好在，谁得老师心。"]},{"t":"渔家","f":"五言律诗","c":["小径通山坞，扁舟宿钓矶。","儿童汲水上，妇女背樵归。","腊月鱼虾足，丰年鸡鸭肥。","是非人世事，应不到柴扉。"]},{"t":"道中","f":"五言律诗","c":["湖天冬不雪，山地晚多风。","岸草犹全绿，村花或自红。","差池岁聿暮，寂寞雨其濛。","南北随蓬转，浮生旅寓中。"]},{"t":"马上读书寄君时 其一","f":"五言律诗","c":["夜秣骎骎马，晨脂绎绎车。","更行犹挟策，渐老欲捐书。","漫意窥原委，非工辨鲁鱼。","相知今亦少，舍汝更谁欤。"]},{"t":"马上读书寄君时 其二","f":"五言律诗","c":["独自鞭驽马，谁何惜后车。","浮云看富贵，陈迹泥诗书。","画虎岂类狗，忘筌在得鱼。","田园须稍葺，吾与汝归欤。"]},{"t":"某闻老母到叶未得平安家书作小诗寄君时弟","f":"五言律诗","c":["慈闱闻及叶，坐待到天明。","望月魂先往，闻更梦不成。","花开灯有信，书少雁无情。","欲往终多畏，迟留叹此生。"]},{"t":"和念一弟诗韵","f":"五言律诗","c":["事如车转轴，日夜不曾周。","固各有分定，疑皆非本谋。","能鸣君似雁，不系我为舟。","扰扰胶胶者，怜渠不自由。"]},{"t":"内乡招提寺","f":"五言律诗","c":["淫雨宿萧寺，白云思楚山。","病催颜色老，泪裛鬓毛斑。","流水终何事，飞禽倦未还。","梦归无别处，鹫岭凤林关。"]},{"t":"春阴呈兄长 其一","f":"五言律诗","c":["春阴祇欲睡，世事固相寻。","簿领粗官意，尘埃故国心。","风吹花点点，雨压柳阴阴。","几日城头步，乾坤共醉吟。"]},{"t":"春阴呈兄长 其二","f":"五言律诗","c":["春容猛狼藉，暑意已侵寻。","寂寞悲时事，凄凉上客心。","莺飞啼野色，蝶戏落花阴。","喜有城隅望，乘风听苦吟。"]},{"t":"春阴呈兄长 其三","f":"五言律诗","c":["花开初熟醉，月上夜微吟。","志节伤时序，诗书爱寸阴。","未忘他日意，无用此时心。","更约藏舟步，馀芳尚可寻。"]},{"t":"途中早起寄兄弟","f":"五言律诗","c":["为惜庭闱别，方惊道路难。","醉怜山月古，病怯野风寒。","驻马询农耜，临溪问钓竿。","新诗如有得，写染寄归翰。"]},{"t":"和岩夫如字韵","f":"五言律诗","c":["霆声破幽郁，雨点散空虚。","日夕分长短，阴阳竞惨舒。","柳丝吹细细，花片落疏疏。","试望孤城远，江山画不如。"]},{"t":"送岩夫庭佐归宁 其一","f":"五言律诗","c":["花满春来路，云归雨后天。","红尘一马去，白日寸肝悬。","秀色歌棠棣，归心听杜鹃。","东风吹眼尾，客泪滴涓涓。"]},{"t":"送岩夫庭佐归宁 其二","f":"五言律诗","c":["春雨伤行色，秋风问后期。","欲吟黄鸟意，更遗白华诗。","客路看山色，亲帏有梦思。","遥知到家日，正好采莼丝。"]},{"t":"武冈驿","f":"五言律诗","c":["破屋山间驿，穷阎溪上村。","云山能近郭，池水故当门。","气象生诗笔，波澜动酒樽。","夜长归梦远，凭尔与招魂。"]},{"t":"驿前人家小池","f":"五言律诗","c":["黄茅前驿路，闇淡小池园。","春近花林好，日斜凫鸭喧。","幕云寒苒苒，眉月夜番番。","莫笑村居僻，谁如拙养尊。"]},{"t":"武阳寨闻峒中作乐","f":"五言律诗","c":["成康已措刑，文景不言兵。","夷俗家家曲，蛮歌处处声。","长腰筒拍鼓，细竹葫芦笙。","物意惟安乐，人间共一情。"]},{"t":"武阳寨见村中梅花","f":"五言律诗","c":["茅屋蛮溪路，梅花亦自开。","雪深忧思远，风静暗香来。","故国春何似，孤城兴远哉。","晚风吹片片，恣意点苍苔。"]},{"t":"寄二弟时在白彪庄 其一","f":"五言律诗","c":["携箧戴星去，荷锄冲雨行。","堤防询故老，铚艾倚新氓。","移竹三千个，添松一万茎。","但能逃冻饿，吾不慕公卿。"]},{"t":"寄二弟时在白彪庄 其二","f":"五言律诗","c":["伊尹初耕野，儿宽自带经。","故须聊假手，无或甚劳形。","曲曲水如带，峨峨山似屏。","夜窗吟更老，不负读书声。"]},{"t":"催君时归并寄君宜弟 其一","f":"五言律诗","c":["命彼仆夫驾，晨鸡初一声。","朔风不可渡，南径却堪行。","贫莫甚今日，瘦无如尔兄。","故惭鱼得计，最爱雁能鸣。"]},{"t":"催君时归并寄君宜弟 其二","f":"五言律诗","c":["三复棣华赋，俛焉怀古风。","少时贪壮决，老去自童蒙。","以病故有病，既空何用空。","不须多问此，万劫刹那中。"]},{"t":"和君时弟","f":"五言律诗","c":["老马青骢色，扁舟画鹢文。","长烟横作带，叠浪似成纹。","北岭夜收雨，南冈朝出云。","赋诗知有意，畎亩不忘君。"]},{"t":"答君时弟 其一","f":"五言律诗","c":["埙篪与鸿雁，一气更同声。","鼓则与桴应，形惟从影行。","无如我宜弟，颇笑尔难兄。","洵美歌棠棣，仍须听鹤鸣。"]},{"t":"答君时弟 其二","f":"五言律诗","c":["埙篪无俗韵，鸿雁有秋声。","更类偲偲友，非同踽踽行。","爱无踰玉季，名有愧龙兄。","莫作升堂赋，相期以道鸣。"]},{"t":"答君时弟 其三","f":"五言律诗","c":["梦觉山头月，归乘湖面风。","远林寒寂寂，幽径晓蒙蒙。","反哺乌鸣屋，成行雁贴空。","物情缘底事，祇欲搅予中。"]},{"t":"答君时弟 其四","f":"五言律诗","c":["是露复是电，非铃亦非风。","应作如是解，无为彼所蒙。","世累不见累，真空亦非空。","欲知如是意，不在内外中。"]},{"t":"和子忠弟见寄元韵","f":"五言律诗","c":["诗书非不乐，富贵竟何加。","岁月流年晚，山川行路赊。","学须千古到，行畏一毫差。","阃阈相期远，宁惟效兔罝。"]},{"t":"和运干奉议见赠元韵","f":"五言律诗","c":["沉碑万山脚，骑马习池头。","元凯亦过虑，山公聊自谋。","青烟鹿门净，黄竹凤林秋。","兴废不可问，登临徒百忧。"]},{"t":"离武阳寨","f":"五言律诗","c":["山谷多时雨，乾坤昨夜晴。","经年淹坏舍，破晓出边城。","青女吹风急，常娥伴月明。","人间春到久，寂寞壮心惊。"]},{"t":"和君时弟洗竹","f":"五言律诗","c":["斩伐奚伤性，繁枝漫作阴。","静留朝日暖，寒聚晚烟深。","叶有禽栖息，根无蚁蠹侵。","龙孙今转盛，终待凤凰音。"]},{"t":"和君时弟有感","f":"五言律诗","c":["鬓发非蓬草，秋来亦自衰。","简书公迫促，岁月细推移。","见客簪裳懒，登楼杖履迟。","故园松菊在，归计定何时。"]}]};